-- Recover missing creature dialogue translations from broadcast_text.
--
-- _13 concluded there was no source, having looked only at tables named
-- creature_text_locale. The translations exist in a differently shaped table:
-- broadcast_text is the client's master list of spoken lines. Newer TrinityCore
-- links the two with a BroadcastTextID column that this fork's creature_text
-- does not have, which is why the connection is invisible from the schema.
--
-- Matching on the English text is exact, not fuzzy. A line whose sources
-- disagree on the translation is dropped, and a female variant is imported only
-- where this database has a female English string that matches.

INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`, `TextFemale`) VALUES
(951,0,0,'deDE','MÖGE DAS LICHT EUCH ERNEUERN!',NULL),
(951,0,0,'esES','¡QUE LA LUZ TE RENUEVE!',NULL),
(951,0,0,'esMX','¡QUE LA LUZ TE RENUEVE!',NULL),
(951,0,0,'frFR','PAR LA LUMIÈRE QUI VOUS RENOUVELLE !',NULL),
(951,0,0,'koKR','빛의 힘으로 소생할 것입니다!',NULL),
(951,0,0,'zhCN','在圣光的照耀下焕发新生！',NULL),
(951,0,0,'zhTW','以聖光之名，復原吧!',NULL),
(951,0,1,'deDE','UND ICH LEGE EUCH MEINE HÄNDE AUF!',NULL),
(951,0,1,'esES','¡Y YO DEJO CAER MIS MANOS SOBRE TI!',NULL),
(951,0,1,'esMX','¡Y YO DEJO CAER MIS MANOS SOBRE TI!',NULL),
(951,0,1,'frFR','ET J\'IMPOSE MES MAINS SUR VOUS !',NULL),
(951,0,1,'koKR','치유의 손길이 그대에게 닿으리니!',NULL),
(951,0,1,'zhCN','我在全力治疗你！',NULL),
(951,0,1,'zhTW','我用我的雙手來治療你!',NULL),
(951,0,2,'deDE','Möge das Heilige Licht Euch umarmen!',NULL),
(951,0,2,'esES','¡Que la Luz Sagrada te envuelva!',NULL),
(951,0,2,'esMX','¡Que la Luz Sagrada te envuelva!',NULL),
(951,0,2,'frFR','Que la Lumière sacrée te baigne !',NULL),
(951,0,2,'koKR','성스러운 빛에 몸을 맡기십시오!',NULL),
(951,0,2,'zhCN','让圣光拥抱你！',NULL),
(951,0,2,'zhTW','願聖光擁抱你!',NULL),
(1477,0,0,'deDE','Kannst du dich noch erinnern, wie Danath alle Söldner von Sturmwind versammelt hat und wir zum Kampf bei Nethergarde marschiert sind?',NULL),
(1477,0,0,'esES','¿Recuerdas cuando Danath reunió a todos los mercenarios de Ventormenta y marchamos a combatir a Nethergarde?',NULL),
(1477,0,0,'esMX','¿Recuerdas cuando Danath reunió a todos los mercenarios de Ventormenta y marchamos a combatir a Nethergarde?',NULL),
(1477,0,0,'frFR','Te souviens-tu de la fois où Danath avait réuni tous les mercenaires de Hurlevent et que nous avions marché sur Rempart-du-Néant pour livrer bataille ?',NULL),
(1477,0,0,'koKR','다나스가 스톰윈드의 모든 용병을 모아 전투를 위해 네더가드로 진격해 갔던 때를 기억하나?',NULL),
(1477,0,0,'zhCN','你还记得当年达纳斯聚集了暴风城的所有雇佣兵，然后开到守望堡去跟兽人大战的事情吗？',NULL),
(1477,0,0,'zhTW','你還記得當年達納斯聚集了暴風城的所有雇傭兵，然後揮軍守望堡展開大戰的事情嗎?',NULL),
(1477,0,1,'deDE','Ich sage dir, mir fehlt der Große Krieg überhaupt nicht. Ich weiß noch, wie wir bei Darromer kämpften. Wir lagen die ganze Nacht bei Nebel in einem modrigen Graben.',NULL),
(1477,0,1,'esES','Ya te digo, yo no echo nada de menos la Gran Guerra. Recuerdo cuando luchamos en Darrowmere. Toda la noche en medio de la niebla, tendidos en una trinchera llena de lodo.',NULL),
(1477,0,1,'esMX','Ya te digo, yo no echo nada de menos la Gran Guerra. Recuerdo cuando luchamos en Darrowmere. Toda la noche en medio de la niebla, tendidos en una trinchera llena de lodo.',NULL),
(1477,0,1,'frFR','Je le dis, la Grande Guerre ne me manque pas du tout. Je me souviens de la bataille que nous avons livrée à Darrowmere. Toute la nuit dans le brouillard, tapis dans une tranchée pleine de boue.',NULL),
(1477,0,1,'koKR','난 대전쟁을 속속들이 다 겪었어. 우리가 다로우미어 호수에서 싸웠을 때가 생각나는군. 질퍽거리는 참호 속에서 밤을 꼬박 새웠었지.',NULL),
(1477,0,1,'zhCN','我跟你说，我参加了整场大战。我还记得当时我们在达隆米尔战斗的情景。整个晚上都是雾，我们就躺在满是泥泞的战壕里。',NULL),
(1477,0,1,'zhTW','我跟你說，我一點都不懷念那場大戰。我還記得當時我們在達隆米爾戰鬥的情景。整個晚上都是霧，我們就躺在滿是泥濘的戰壕裡。',NULL),
(1477,0,2,'deDE','Mir fehlt das Zwergenbier, das wir immer in diesem Gasthaus in Lordaeron getrunken haben. Erinnerst du dich noch an den Kampf, den wir dort anfingen?',NULL),
(1477,0,2,'esES','Echo de menos la cerveza enana que nos daban en la taberna de Lordaeron. ¿Te acuerdas la pelea que iniciamos allí?',NULL),
(1477,0,2,'esMX','Echo de menos la cerveza enana que nos daban en la taberna de Lordaeron. ¿Te acuerdas la pelea que iniciamos allí?',NULL),
(1477,0,2,'frFR','Je regrette la bière des nains qu’on avait l’habitude de boire dans cette auberge, à Lordaeron. Tu te souviens de la bagarre qu’on avait commencée là-bas ?',NULL),
(1477,0,2,'koKR','로데론의 그 여관에서 마시곤 했던 드워프 에일 맥주가 그리워. 자네, 거기서 시작된 우리의 전투를 기억하나?',NULL),
(1477,0,2,'zhCN','我真的很怀念洛丹伦的那个旅馆里的矮人麦酒。还记得我们在那里开始的战斗吗？',NULL),
(1477,0,2,'zhTW','我真的很懷念羅德隆的那個旅館裡的矮人麥酒。還記得我們在裡頭打的那一架嗎?',NULL),
(1477,0,3,'deDE','Weniger als Hundert von uns und mehr als tausend Orcs. Nur eine Handvoll von uns hat das überlebt.',NULL),
(1477,0,3,'esES','Éramos menos de un centenar y los orcos, más de un millar. Solo muy pocos conseguimos escapar de aquello.',NULL),
(1477,0,3,'esMX','Éramos menos de un centenar y los orcos, más de un millar. Solo muy pocos conseguimos escapar de aquello.',NULL),
(1477,0,3,'frFR','Nous étions moins de cent et il y avait plus d’un millier d’orcs. Seule une poignée d’entre nous a réussi à en réchapper cette fois-là.',NULL),
(1477,0,3,'koKR','우리는 백 명이 안 되고 오크 놈들은 천 명이 넘었지. 우리 중 몇 명만이 그 전투에서 살아 돌아올 수 있었어.',NULL),
(1477,0,3,'zhCN','我们不足百人，兽人却有上千个。区区百人怎么能够战胜他们？',NULL),
(1477,0,3,'zhTW','我們不足百人，獸人卻有上千個。最後我們只有少數人活著離開那個戰場。',NULL),
(1477,0,4,'deDE','Das Beste muss der Ausdruck auf Perenoldes Gesicht gewesen sein, als unsere Armee direkt bis vor seine Haustür marschiert ist. Was für eine Schlacht!',NULL),
(1477,0,4,'esES','Lo mejor tuvo que ser la cara de Perenolde cuando nuestros ejércitos marchaban hacia su propia puerta. ¡Qué batalla!',NULL),
(1477,0,4,'esMX','Lo mejor tuvo que ser la cara de Perenolde cuando nuestros ejércitos marchaban hacia su propia puerta. ¡Qué batalla!',NULL),
(1477,0,4,'frFR','Le mieux devait être le visage de Perenolde lorsqu’il a vu notre armée à sa porte. Quelle bataille !',NULL),
(1477,0,4,'koKR','최고의 순간은 우리 군대가 자기 집 문 앞에까지 진격해 가자 사색이 된 페레놀드의 표정을 보았을 때였지. 정말 대단한 전투였어!',NULL),
(1477,0,4,'zhCN','在我们的部队开到匹瑞诺德家门口的时候，你真该看看他的脸色。真是一场恶战！',NULL),
(1477,0,4,'zhTW','最精采的是我們的部隊進軍匹瑞諾德門口的時候，你真該看看他的臉色。真是精采啊!',NULL),
(1477,0,5,'deDE','Ich kann mir bessere Orte als diesen Morast für einen Krieg gegen den Schattenhammer vorstellen.',NULL),
(1477,0,5,'esES','Luchar contra ese grupo del Martillo Crepuscular en las Ciénagas... se me ocurren mejores lugares para una guerra.',NULL),
(1477,0,5,'esMX','Luchar contra ese grupo del Martillo Crepuscular en las Ciénagas... se me ocurren mejores lugares para una guerra.',NULL),
(1477,0,5,'frFR','Se battre contre cette bande du Marteau du crépuscule dans le Noir Marécage... On peut rêver meilleur endroit pour faire la guerre.',NULL),
(1477,0,5,'koKR','그 황혼의 망치단 무리와 습지대에서 싸웠었는데... 정말 끔찍한 전투였지.',NULL),
(1477,0,5,'zhCN','与沼泽中的暮光之锤信徒战斗，那感觉真是糟透了。',NULL),
(1477,0,5,'zhTW','與沼澤中的暮光之錘信徒戰鬥，那感覺真是糟透了。',NULL),
(1477,0,6,'deDE','Ach ja, jetzt erinnere ich mich, deine Hochzeitsnacht, nicht wahr?',NULL),
(1477,0,6,'esES','Ah, sí, ahora lo recuerdo, fue en tu noche de bodas, ¿no es así?',NULL),
(1477,0,6,'esMX','Ah, sí, ahora lo recuerdo, fue en tu noche de bodas, ¿no es así?',NULL),
(1477,0,6,'frFR','Ah oui, maintenant je m\'en souviens, c\'était ta nuit de noces, non ?',NULL),
(1477,0,6,'koKR','아 그래, 이제 생각나는군. 자네 결혼식 날밤 말이지?',NULL),
(1477,0,6,'zhCN','啊，对，现在我记起来了，是在你的新婚之夜吧？',NULL),
(1477,0,6,'zhTW','啊，對，現在我記起來了，是在你的新婚之夜吧?',NULL),
(1477,0,7,'deDE','Ah, die Glustewelt-Zwillinge!',NULL),
(1477,0,7,'esES','¡Ahh, los gemelos Glustewelt!',NULL),
(1477,0,7,'esMX','¡Ahh, los gemelos Glustewelt!',NULL),
(1477,0,7,'frFR','Ah, les jumeaux Glustewelt !',NULL),
(1477,0,7,'koKR','아, 그 글러스트웰트 쌍둥이!',NULL),
(1477,0,7,'zhCN','啊啊！',NULL),
(1477,0,7,'zhTW','啊啊，是克魯斯威特雙胞胎!',NULL),
(1477,1,0,'deDE','Ich habe immer noch Narben aus dieser Nacht.',NULL),
(1477,1,0,'esES','Aún conservo cicatrices de aquella noche.',NULL),
(1477,1,0,'esMX','Aún conservo cicatrices de aquella noche.',NULL),
(1477,1,0,'frFR','J’ai encore les cicatrices de cette nuit-là.',NULL),
(1477,1,0,'koKR','그날 밤 입은 상처 자국이 아직 남아 있다고.',NULL),
(1477,1,0,'zhCN','那晚的伤痕依然留在我身上。',NULL),
(1477,1,0,'zhTW','那晚的傷痕依然留在我身上。',NULL),
(1477,1,1,'deDE','In der Nacht hab ich mir beide Beine gebrochen. Wie könnt ich das vergessen?',NULL),
(1477,1,1,'esES','Esa noche me rompieron las dos piernas. ¿Cómo olvidarlo?',NULL),
(1477,1,1,'esMX','Esa noche me rompieron las dos piernas. ¿Cómo olvidarlo?',NULL),
(1477,1,1,'frFR','Mes deux jambes ont été brisées cette nuit-là. Je risque pas d\'oublier.',NULL),
(1477,1,1,'koKR','그날 밤 두 다리가 모두 부러졌었는데 어떻게 잊을 수 있겠나?',NULL),
(1477,1,1,'zhCN','那天晚上我断了两条腿。我怎么会忘记呢？',NULL),
(1477,1,1,'zhTW','那天晚上我斷了兩條腿。我怎麼會忘記呢?',NULL),
(1477,1,2,'deDE','Drei Wochen später wachte ich in einem Bett in Nordhain wieder auf. Ich erinnere mich an gar nichts mehr.',NULL),
(1477,1,2,'esES','Desperté en una cama en Villanorte tres semanas después. No recordaba nada en absoluto.',NULL),
(1477,1,2,'esMX','Desperté en una cama en Villanorte tres semanas después. No recordaba nada en absoluto.',NULL),
(1477,1,2,'frFR','Je me suis réveillé alité à Comté-du-Nord trois semaines plus tard. Je me souviens de rien.',NULL),
(1477,1,2,'koKR','3주 후에 북녘골의 침대 위에서 깨어났지. 하나도 기억이 나질 않더라고.',NULL),
(1477,1,2,'zhCN','三个星期之后，我在北郡醒来。但是我已经想不起任何事了。',NULL),
(1477,1,2,'zhTW','三個星期之後，我在北郡醒來。但是我已經想不起任何事了。',NULL),
(1477,1,3,'deDE','War das nicht die Nacht, als wir meinen Daumen aufsammeln und ihn in deiner Tabaktasche herumtragen mussten?',NULL),
(1477,1,3,'esES','¿No fue aquella la noche en que tuvimos que recoger mi pulgar y meterlo en tu bolsa de cigarrillos?',NULL),
(1477,1,3,'esMX','¿No fue aquella la noche en que tuvimos que recoger mi pulgar y meterlo en tu bolsa de cigarrillos?',NULL),
(1477,1,3,'frFR','N’était-ce pas la nuit où nous avions dû ramasser mon pouce et le transporter dans ta pochette à grenade ?',NULL),
(1477,1,3,'koKR','그날 밤에 내 반지를 주워서 자네 담배 주머니 안에 넣지 않았던가?',NULL),
(1477,1,3,'zhCN','是啊，那天晚上我们不得不捡起我的手指，然后把它放进你的烟袋里带了回来。',NULL),
(1477,1,3,'zhTW','那不就是我們得撿起我的大拇指，然後把它放進你的煙袋裡帶回來的那天晚上?',NULL),
(1477,1,4,'deDE','Ich habe ein Stück Eisen in meinem Rücken, das mich für den Rest meines Lebens an diese Nacht erinnern wird.',NULL),
(1477,1,4,'esES','Tengo incrustado un trozo de hierro en la espalda, que me recordará esa noche durante el resto de mi vida.',NULL),
(1477,1,4,'esMX','Tengo incrustado un trozo de hierro en la espalda, que me recordará esa noche durante el resto de mi vida.',NULL),
(1477,1,4,'frFR','J’ai un morceau de fer dans le dos qui me rappellera cette nuit pour le restant de ma vie.',NULL),
(1477,1,4,'koKR','내 등에 있는 상처가 아마 평생 그날 밤 일을 기억하게 할 걸세.',NULL),
(1477,1,4,'zhCN','我的后背里还有一小块铁片，这会让我永远记得那个晚上。',NULL),
(1477,1,4,'zhTW','我的背裡還有一小塊鐵片，提醒我永遠記得那晚上的事情。',NULL),
(1477,1,5,'deDE','Klar erinner ich mich an die Nacht. Fünf Zentimeter weiter links, und ich würd\' jetzt nich\' hier sitzen un\' mit dir trinken, Morris. Un\' das war auch noch mein bestes Hemd.',NULL),
(1477,1,5,'esES','Claro que recuerdo aquella noche. De haber estado cinco centímetros más a la izquierda, ahora estarías bebiendo con ese elfo, Morris. Esa era también mi mejor camisa.',NULL),
(1477,1,5,'esMX','Claro que recuerdo aquella noche. De haber estado cinco centímetros más a la izquierda, ahora estarías bebiendo con ese elfo, Morris. Esa era también mi mejor camisa.',NULL),
(1477,1,5,'frFR','Bien sûr que je me souviens de cette nuit. Deux pouces plus à gauche et vous seriez en train de boire avec cet elfe, Morris. J\'y ai perdu ma meilleure chemise.',NULL),
(1477,1,5,'koKR','물론 그날 밤은 기억하지. 조금만 왼쪽으로 비켜 맞았어도 자네는 지금쯤 그 엘프 모리스와 함께 뒤틀린 황천에서 술을 마시고 있을 거야. 참, 그리고 그건 내가 가장 좋아하는 셔츠였다고.',NULL),
(1477,1,5,'zhCN','我当然记得那晚的情形。你就在我左边两英尺左右的地方，一直和那个名叫莫里斯的精灵在喝酒。那晚我还穿着我最好的衬衫哪。',NULL),
(1477,1,5,'zhTW','我當然記得那晚的情形。再往左邊偏個兩英吋，肯定就掛點了。那晚我還穿著我最好的襯衫呢。',NULL),
(1477,1,6,'deDE','War es das dritte oder vierte Mal, als du beinahe Hackfleisch aus mir gemacht hättest, als du einen deiner verrückten Tricks ausprobiert hast?',NULL),
(1477,1,6,'esES','¿No fue esa la tercera o cuarta vez que casi me destrozas probando una de tus locas proezas?',NULL),
(1477,1,6,'esMX','¿No fue esa la tercera o cuarta vez que casi me destrozas probando una de tus locas proezas?',NULL),
(1477,1,6,'frFR','C’était la troisième ou la quatrième fois que tu as bien failli me faire crever en me faisant essayer l’une de tes cascades démentes ?',NULL),
(1477,1,6,'koKR','자네가 그 정신 나간 묘기에 도전하다가 내가 복부에 크게 상처 입은 게 그때가 세 번째 아니면 네 번째였지, 아마?',NULL),
(1477,1,6,'zhCN','那是我第三次还是第四次呕吐了？你那些疯狂的烈酒……',NULL),
(1477,1,6,'zhTW','...那是第三次、還是第四次?你那些個瘋狂的舉動又害我差點肚破腸流了?',NULL),
(1477,1,7,'deDE','Ja, und danke, dass du mich in dieser Nacht meine eigene Hand zurück zu den Priestern hast tragen lassen.',NULL),
(1477,1,7,'esES','Sí, y gracias por dejarme llevar mi propia mano a los sacerdotes esa noche.',NULL),
(1477,1,7,'esMX','Sí, y gracias por dejarme llevar mi propia mano a los sacerdotes esa noche.',NULL),
(1477,1,7,'frFR','Oui, et merci de m’avoir laissé rapporter ma propre main aux prêtres cette nuit-là.',NULL),
(1477,1,7,'koKR','그래, 그날 밤 내 손을 가지고 사제들에게 돌아갈 수 있도록 해 준 건 고맙게 생각하네.',NULL),
(1477,1,7,'zhCN','嗯，谢谢你那天晚上让我能把自己的手捡回去。',NULL),
(1477,1,7,'zhTW','嗯，謝謝你那天晚上讓我能把自己的手撿回去給牧師治療。',NULL),
(1477,2,0,'deDE','Hehe, Schlappschwanz.',NULL),
(1477,2,0,'esES','Je, je, chaval.',NULL),
(1477,2,0,'esMX','Je, je, chaval.',NULL),
(1477,2,0,'frFR','Hé hé, mauviette.',NULL),
(1477,2,0,'koKR','헤헤, 소심하긴...',NULL),
(1477,2,0,'zhCN','呵呵，废物。',NULL),
(1477,2,0,'zhTW','呵呵，廢物。',NULL),
(1477,2,1,'deDE','Du hast geschrien wie ein kleines Mädchen - war das Lustigste, was ich je gesehen habe.',NULL),
(1477,2,1,'esES','Gritabas como una nena, fue lo más gracioso que he visto jamás.',NULL),
(1477,2,1,'esMX','Gritabas como una nena, fue lo más gracioso que he visto jamás.',NULL),
(1477,2,1,'frFR','Tu hurlais comme une gamine, je n\'ai jamais autant ri.',NULL),
(1477,2,1,'koKR','그때 자넨 어린 여자 아이처럼 비명을 질러댔지. 지금까지 내가 본 것 중 가장 우스운 광경이었어, 하하.',NULL),
(1477,2,1,'zhCN','你像个小女孩一般地尖叫，这真是我见过的最好笑的事。',NULL),
(1477,2,1,'zhTW','你叫得跟個小女孩一樣，真是我見過最好笑的事。',NULL),
(1477,2,2,'deDE','Am Ende hat doch alles geklappt.',NULL),
(1477,2,2,'esES','Al final todo salió bien.',NULL),
(1477,2,2,'esMX','Al final todo salió bien.',NULL),
(1477,2,2,'frFR','Tout a fini par rentrer dans l’ordre.',NULL),
(1477,2,2,'koKR','결국엔 다 잘 됐지.',NULL),
(1477,2,2,'zhCN','最后终于全搞定了。',NULL),
(1477,2,2,'zhTW','最後終於全搞定了。',NULL),
(1477,2,3,'deDE','Lass uns erst gar nicht damit anfangen, Kampfnarben zu vergleichen, mein Freund.',NULL),
(1477,2,3,'esES','Ay, amigo, no nos pongamos ahora a comparar nuestras cicatrices de guerra.',NULL),
(1477,2,3,'esMX','Ay, amigo, no nos pongamos ahora a comparar nuestras cicatrices de guerra.',NULL),
(1477,2,3,'frFR','Ne commençons pas à comparer nos cicatrices de guerre, mon ami.',NULL),
(1477,2,3,'koKR','전투에서 입은 흉터를 비교하는 짓은 아예 시작도 하지 말자고, 친구.',NULL),
(1477,2,3,'zhCN','让我们不要再比较身上的伤痕了，朋友。',NULL),
(1477,2,3,'zhTW','讓我們不要再比較身上的傷痕了，朋友。',NULL),
(1477,2,4,'deDE','Ich habe noch nie jemanden gesehen, der sich so schnell bewegt hat.',NULL),
(1477,2,4,'esES','En mi vida vi a alguien moverse tan rápido.',NULL),
(1477,2,4,'esMX','En mi vida vi a alguien moverse tan rápido.',NULL),
(1477,2,4,'frFR','Je n\'ai jamais vu personne se déplacer aussi vite.',NULL),
(1477,2,4,'koKR','내 지금껏 살면서 그렇게 빨리 움직이는 친구는 본 적이 없어.',NULL),
(1477,2,4,'zhCN','我从来没看到过有人逃得这么快。',NULL),
(1477,2,4,'zhTW','我從來沒看到過有人逃得這麼快。',NULL),
(1477,2,5,'deDE','Du überraschst mich ständig aufs Neue damit, was eine Person alles ertragen kann.',NULL),
(1477,2,5,'esES','Constantemente me sorprendes con todo lo que una persona es capaz de soportar.',NULL),
(1477,2,5,'esMX','Constantemente me sorprendes con todo lo que una persona es capaz de soportar.',NULL),
(1477,2,5,'frFR','Ça m’étonnera toujours, ce qu’une personne peut endurer…',NULL),
(1477,2,5,'koKR','자네와 같이 지내다 보면 그 파란만장한 삶에 끊임없이 놀라게 된다니까.',NULL),
(1477,2,5,'zhCN','你真的令我感到非常惊讶，你居然活了下来。',NULL),
(1477,2,5,'zhTW','你真的令我感到非常驚訝，你居然活了下來。',NULL),
(1477,2,6,'deDE','Nun, du bist immer noch hier. Ich würde sagen, dass wir darauf einen trinken sollten.',NULL),
(1477,2,6,'esES','Bien, aquí sigues. Parece que hay algo bueno de beber.',NULL),
(1477,2,6,'esMX','Bien, aquí sigues. Parece que hay algo bueno de beber.',NULL),
(1477,2,6,'frFR','Enfin, tu es encore là, et je trouve que ça justifie bien une tournée !',NULL),
(1477,2,6,'koKR','뭐, 우리가 아직 이렇게 살아 있다는 것만으로도 축배를 들 만한 일이 아닌가?',NULL),
(1477,2,6,'zhCN','好吧，你还好端端地坐在这里。我想说这里还是有些东西值得我们举杯庆贺的。',NULL),
(1477,2,6,'zhTW','好吧，你還好端端地坐在這裡。我想說這裡還是有些東西值得我們舉杯慶賀的。',NULL),
(1477,2,7,'deDE','Du kannst dich jederzeit bei mir dafür bedanken, dass ich dein Leben interessanter gemacht habe.',NULL),
(1477,2,7,'esES','Cuando quieras puedes agradecerme por hacer tu vida más interesante.',NULL),
(1477,2,7,'esMX','Cuando quieras puedes agradecerme por hacer tu vida más interesante.',NULL),
(1477,2,7,'frFR','Tu peux me remercier d’avoir ajouté un peu de piment à ta vie.',NULL),
(1477,2,7,'koKR','자네 삶을 아주 흥미진진하게 만들어 준 내게 항상 감사하라고.',NULL),
(1477,2,7,'zhCN','你可以在任何时候感谢我，因为我令你的生活更加有趣。',NULL),
(1477,2,7,'zhTW','你可以在任何時候感謝我，因為我令你的生活更加有趣。',NULL),
(1478,0,0,'deDE','He, Reese, noch \'ne Runde für Christoph und mich.',NULL),
(1478,0,0,'esES','Oye, Reese, invítanos a Christoph y a mí a otra ronda.',NULL),
(1478,0,0,'esMX','Oye, Reese, invítanos a Christoph y a mí a otra ronda.',NULL),
(1478,0,0,'frFR','Hé Reese, sers-nous une autre tournée, à moi et Christoph.',NULL),
(1478,0,0,'koKR','이봐 리즈, 크리스토프에게 한 잔 더 주게.',NULL),
(1478,0,0,'zhCN','嘿，瑞斯，给我和克里斯托弗再来一杯。',NULL),
(1478,0,0,'zhTW','嘿，瑞斯，給我和克里斯多夫再來一杯。',NULL),
(1478,1,0,'deDE','Eine warme Taverne und ein kaltes Bier. Was wollen wir mehr?',NULL),
(1478,1,0,'esES','Una taberna caliente y una cerveza fría. ¿Qué más podemos pedir?',NULL),
(1478,1,0,'esMX','Una taberna caliente y una cerveza fría. ¿Qué más podemos pedir?',NULL),
(1478,1,0,'frFR','Une taverne bien chauffée et une bière bien fraîche. Que rêver de plus ?',NULL),
(1478,1,0,'koKR','따뜻한 선술집과 차가운 맥주라... 더 바랄 게 없지.',NULL),
(1478,1,0,'zhCN','暖和的旅店，冰爽的麦酒。我们还能要求什么呢？',NULL),
(1478,1,0,'zhTW','溫暖的旅店，冰爽的麥芽酒。我們還能要求什麼呢?',NULL),
(1478,2,0,'deDE','Kannst du dich noch erinnern, wie Danath alle Söldner von Sturmwind versammelt hat und wir zum Kampf bei Nethergarde marschiert sind?',NULL),
(1478,2,0,'esES','¿Recuerdas cuando Danath reunió a todos los mercenarios de Ventormenta y marchamos a combatir a Nethergarde?',NULL),
(1478,2,0,'esMX','¿Recuerdas cuando Danath reunió a todos los mercenarios de Ventormenta y marchamos a combatir a Nethergarde?',NULL),
(1478,2,0,'frFR','Te souviens-tu de la fois où Danath avait réuni tous les mercenaires de Hurlevent et que nous avions marché sur Rempart-du-Néant pour livrer bataille ?',NULL),
(1478,2,0,'koKR','다나스가 스톰윈드의 모든 용병을 모아 전투를 위해 네더가드로 진격해 갔던 때를 기억하나?',NULL),
(1478,2,0,'zhCN','你还记得当年达纳斯聚集了暴风城的所有雇佣兵，然后开到守望堡去跟兽人大战的事情吗？',NULL),
(1478,2,0,'zhTW','你還記得當年達納斯聚集了暴風城的所有雇傭兵，然後揮軍守望堡展開大戰的事情嗎?',NULL),
(1478,2,1,'deDE','Ich sage dir, mir fehlt der Große Krieg überhaupt nicht. Ich weiß noch, wie wir bei Darromer kämpften. Wir lagen die ganze Nacht bei Nebel in einem modrigen Graben.',NULL),
(1478,2,1,'esES','Ya te digo, yo no echo nada de menos la Gran Guerra. Recuerdo cuando luchamos en Darrowmere. Toda la noche en medio de la niebla, tendidos en una trinchera llena de lodo.',NULL),
(1478,2,1,'esMX','Ya te digo, yo no echo nada de menos la Gran Guerra. Recuerdo cuando luchamos en Darrowmere. Toda la noche en medio de la niebla, tendidos en una trinchera llena de lodo.',NULL),
(1478,2,1,'frFR','Je le dis, la Grande Guerre ne me manque pas du tout. Je me souviens de la bataille que nous avons livrée à Darrowmere. Toute la nuit dans le brouillard, tapis dans une tranchée pleine de boue.',NULL),
(1478,2,1,'koKR','난 대전쟁을 속속들이 다 겪었어. 우리가 다로우미어 호수에서 싸웠을 때가 생각나는군. 질퍽거리는 참호 속에서 밤을 꼬박 새웠었지.',NULL),
(1478,2,1,'zhCN','我跟你说，我参加了整场大战。我还记得当时我们在达隆米尔战斗的情景。整个晚上都是雾，我们就躺在满是泥泞的战壕里。',NULL),
(1478,2,1,'zhTW','我跟你說，我一點都不懷念那場大戰。我還記得當時我們在達隆米爾戰鬥的情景。整個晚上都是霧，我們就躺在滿是泥濘的戰壕裡。',NULL),
(1478,2,2,'deDE','Mir fehlt das Zwergenbier, das wir immer in diesem Gasthaus in Lordaeron getrunken haben. Erinnerst du dich noch an den Kampf, den wir dort anfingen?',NULL),
(1478,2,2,'esES','Echo de menos la cerveza enana que nos daban en la taberna de Lordaeron. ¿Te acuerdas la pelea que iniciamos allí?',NULL),
(1478,2,2,'esMX','Echo de menos la cerveza enana que nos daban en la taberna de Lordaeron. ¿Te acuerdas la pelea que iniciamos allí?',NULL),
(1478,2,2,'frFR','Je regrette la bière des nains qu’on avait l’habitude de boire dans cette auberge, à Lordaeron. Tu te souviens de la bagarre qu’on avait commencée là-bas ?',NULL),
(1478,2,2,'koKR','로데론의 그 여관에서 마시곤 했던 드워프 에일 맥주가 그리워. 자네, 거기서 시작된 우리의 전투를 기억하나?',NULL),
(1478,2,2,'zhCN','我真的很怀念洛丹伦的那个旅馆里的矮人麦酒。还记得我们在那里开始的战斗吗？',NULL),
(1478,2,2,'zhTW','我真的很懷念羅德隆的那個旅館裡的矮人麥酒。還記得我們在裡頭打的那一架嗎?',NULL),
(1478,2,3,'deDE','Weniger als Hundert von uns und mehr als tausend Orcs. Nur eine Handvoll von uns hat das überlebt.',NULL),
(1478,2,3,'esES','Éramos menos de un centenar y los orcos, más de un millar. Solo muy pocos conseguimos escapar de aquello.',NULL),
(1478,2,3,'esMX','Éramos menos de un centenar y los orcos, más de un millar. Solo muy pocos conseguimos escapar de aquello.',NULL),
(1478,2,3,'frFR','Nous étions moins de cent et il y avait plus d’un millier d’orcs. Seule une poignée d’entre nous a réussi à en réchapper cette fois-là.',NULL),
(1478,2,3,'koKR','우리는 백 명이 안 되고 오크 놈들은 천 명이 넘었지. 우리 중 몇 명만이 그 전투에서 살아 돌아올 수 있었어.',NULL),
(1478,2,3,'zhCN','我们不足百人，兽人却有上千个。区区百人怎么能够战胜他们？',NULL),
(1478,2,3,'zhTW','我們不足百人，獸人卻有上千個。最後我們只有少數人活著離開那個戰場。',NULL),
(1478,2,4,'deDE','Das Beste muss der Ausdruck auf Perenoldes Gesicht gewesen sein, als unsere Armee direkt bis vor seine Haustür marschiert ist. Was für eine Schlacht!',NULL),
(1478,2,4,'esES','Lo mejor tuvo que ser la cara de Perenolde cuando nuestros ejércitos marchaban hacia su propia puerta. ¡Qué batalla!',NULL),
(1478,2,4,'esMX','Lo mejor tuvo que ser la cara de Perenolde cuando nuestros ejércitos marchaban hacia su propia puerta. ¡Qué batalla!',NULL),
(1478,2,4,'frFR','Le mieux devait être le visage de Perenolde lorsqu’il a vu notre armée à sa porte. Quelle bataille !',NULL),
(1478,2,4,'koKR','최고의 순간은 우리 군대가 자기 집 문 앞에까지 진격해 가자 사색이 된 페레놀드의 표정을 보았을 때였지. 정말 대단한 전투였어!',NULL),
(1478,2,4,'zhCN','在我们的部队开到匹瑞诺德家门口的时候，你真该看看他的脸色。真是一场恶战！',NULL),
(1478,2,4,'zhTW','最精采的是我們的部隊進軍匹瑞諾德門口的時候，你真該看看他的臉色。真是精采啊!',NULL),
(1478,2,5,'deDE','Ich kann mir bessere Orte als diesen Morast für einen Krieg gegen den Schattenhammer vorstellen.',NULL),
(1478,2,5,'esES','Luchar contra ese grupo del Martillo Crepuscular en las Ciénagas... se me ocurren mejores lugares para una guerra.',NULL),
(1478,2,5,'esMX','Luchar contra ese grupo del Martillo Crepuscular en las Ciénagas... se me ocurren mejores lugares para una guerra.',NULL),
(1478,2,5,'frFR','Se battre contre cette bande du Marteau du crépuscule dans le Noir Marécage... On peut rêver meilleur endroit pour faire la guerre.',NULL),
(1478,2,5,'koKR','그 황혼의 망치단 무리와 습지대에서 싸웠었는데... 정말 끔찍한 전투였지.',NULL),
(1478,2,5,'zhCN','与沼泽中的暮光之锤信徒战斗，那感觉真是糟透了。',NULL),
(1478,2,5,'zhTW','與沼澤中的暮光之錘信徒戰鬥，那感覺真是糟透了。',NULL),
(1478,2,6,'deDE','Ach ja, jetzt erinnere ich mich, deine Hochzeitsnacht, nicht wahr?',NULL),
(1478,2,6,'esES','Ah, sí, ahora lo recuerdo, fue en tu noche de bodas, ¿no es así?',NULL),
(1478,2,6,'esMX','Ah, sí, ahora lo recuerdo, fue en tu noche de bodas, ¿no es así?',NULL),
(1478,2,6,'frFR','Ah oui, maintenant je m\'en souviens, c\'était ta nuit de noces, non ?',NULL),
(1478,2,6,'koKR','아 그래, 이제 생각나는군. 자네 결혼식 날밤 말이지?',NULL),
(1478,2,6,'zhCN','啊，对，现在我记起来了，是在你的新婚之夜吧？',NULL),
(1478,2,6,'zhTW','啊，對，現在我記起來了，是在你的新婚之夜吧?',NULL),
(1478,2,7,'deDE','Ah, die Glustewelt-Zwillinge!',NULL),
(1478,2,7,'esES','¡Ahh, los gemelos Glustewelt!',NULL),
(1478,2,7,'esMX','¡Ahh, los gemelos Glustewelt!',NULL),
(1478,2,7,'frFR','Ah, les jumeaux Glustewelt !',NULL),
(1478,2,7,'koKR','아, 그 글러스트웰트 쌍둥이!',NULL),
(1478,2,7,'zhCN','啊啊！',NULL),
(1478,2,7,'zhTW','啊啊，是克魯斯威特雙胞胎!',NULL),
(1478,3,0,'deDE','Ich habe immer noch Narben aus dieser Nacht.',NULL),
(1478,3,0,'esES','Aún conservo cicatrices de aquella noche.',NULL),
(1478,3,0,'esMX','Aún conservo cicatrices de aquella noche.',NULL),
(1478,3,0,'frFR','J’ai encore les cicatrices de cette nuit-là.',NULL),
(1478,3,0,'koKR','그날 밤 입은 상처 자국이 아직 남아 있다고.',NULL),
(1478,3,0,'zhCN','那晚的伤痕依然留在我身上。',NULL),
(1478,3,0,'zhTW','那晚的傷痕依然留在我身上。',NULL),
(1478,3,1,'deDE','In der Nacht hab ich mir beide Beine gebrochen. Wie könnt ich das vergessen?',NULL),
(1478,3,1,'esES','Esa noche me rompieron las dos piernas. ¿Cómo olvidarlo?',NULL),
(1478,3,1,'esMX','Esa noche me rompieron las dos piernas. ¿Cómo olvidarlo?',NULL),
(1478,3,1,'frFR','Mes deux jambes ont été brisées cette nuit-là. Je risque pas d\'oublier.',NULL),
(1478,3,1,'koKR','그날 밤 두 다리가 모두 부러졌었는데 어떻게 잊을 수 있겠나?',NULL),
(1478,3,1,'zhCN','那天晚上我断了两条腿。我怎么会忘记呢？',NULL),
(1478,3,1,'zhTW','那天晚上我斷了兩條腿。我怎麼會忘記呢?',NULL),
(1478,3,2,'deDE','Drei Wochen später wachte ich in einem Bett in Nordhain wieder auf. Ich erinnere mich an gar nichts mehr.',NULL),
(1478,3,2,'esES','Desperté en una cama en Villanorte tres semanas después. No recordaba nada en absoluto.',NULL),
(1478,3,2,'esMX','Desperté en una cama en Villanorte tres semanas después. No recordaba nada en absoluto.',NULL),
(1478,3,2,'frFR','Je me suis réveillé alité à Comté-du-Nord trois semaines plus tard. Je me souviens de rien.',NULL),
(1478,3,2,'koKR','3주 후에 북녘골의 침대 위에서 깨어났지. 하나도 기억이 나질 않더라고.',NULL),
(1478,3,2,'zhCN','三个星期之后，我在北郡醒来。但是我已经想不起任何事了。',NULL),
(1478,3,2,'zhTW','三個星期之後，我在北郡醒來。但是我已經想不起任何事了。',NULL),
(1478,3,3,'deDE','War das nicht die Nacht, als wir meinen Daumen aufsammeln und ihn in deiner Tabaktasche herumtragen mussten?',NULL),
(1478,3,3,'esES','¿No fue aquella la noche en que tuvimos que recoger mi pulgar y meterlo en tu bolsa de cigarrillos?',NULL),
(1478,3,3,'esMX','¿No fue aquella la noche en que tuvimos que recoger mi pulgar y meterlo en tu bolsa de cigarrillos?',NULL),
(1478,3,3,'frFR','N’était-ce pas la nuit où nous avions dû ramasser mon pouce et le transporter dans ta pochette à grenade ?',NULL),
(1478,3,3,'koKR','그날 밤에 내 반지를 주워서 자네 담배 주머니 안에 넣지 않았던가?',NULL),
(1478,3,3,'zhCN','是啊，那天晚上我们不得不捡起我的手指，然后把它放进你的烟袋里带了回来。',NULL),
(1478,3,3,'zhTW','那不就是我們得撿起我的大拇指，然後把它放進你的煙袋裡帶回來的那天晚上?',NULL),
(1478,3,4,'deDE','Ich habe ein Stück Eisen in meinem Rücken, das mich für den Rest meines Lebens an diese Nacht erinnern wird.',NULL),
(1478,3,4,'esES','Tengo incrustado un trozo de hierro en la espalda, que me recordará esa noche durante el resto de mi vida.',NULL),
(1478,3,4,'esMX','Tengo incrustado un trozo de hierro en la espalda, que me recordará esa noche durante el resto de mi vida.',NULL),
(1478,3,4,'frFR','J’ai un morceau de fer dans le dos qui me rappellera cette nuit pour le restant de ma vie.',NULL),
(1478,3,4,'koKR','내 등에 있는 상처가 아마 평생 그날 밤 일을 기억하게 할 걸세.',NULL),
(1478,3,4,'zhCN','我的后背里还有一小块铁片，这会让我永远记得那个晚上。',NULL),
(1478,3,4,'zhTW','我的背裡還有一小塊鐵片，提醒我永遠記得那晚上的事情。',NULL),
(1478,3,5,'deDE','Klar erinner ich mich an die Nacht. Fünf Zentimeter weiter links, und ich würd\' jetzt nich\' hier sitzen un\' mit dir trinken, Morris. Un\' das war auch noch mein bestes Hemd.',NULL),
(1478,3,5,'esES','Claro que recuerdo aquella noche. De haber estado cinco centímetros más a la izquierda, ahora estarías bebiendo con ese elfo, Morris. Esa era también mi mejor camisa.',NULL),
(1478,3,5,'esMX','Claro que recuerdo aquella noche. De haber estado cinco centímetros más a la izquierda, ahora estarías bebiendo con ese elfo, Morris. Esa era también mi mejor camisa.',NULL),
(1478,3,5,'frFR','Bien sûr que je me souviens de cette nuit. Deux pouces plus à gauche et vous seriez en train de boire avec cet elfe, Morris. J\'y ai perdu ma meilleure chemise.',NULL),
(1478,3,5,'koKR','물론 그날 밤은 기억하지. 조금만 왼쪽으로 비켜 맞았어도 자네는 지금쯤 그 엘프 모리스와 함께 뒤틀린 황천에서 술을 마시고 있을 거야. 참, 그리고 그건 내가 가장 좋아하는 셔츠였다고.',NULL),
(1478,3,5,'zhCN','我当然记得那晚的情形。你就在我左边两英尺左右的地方，一直和那个名叫莫里斯的精灵在喝酒。那晚我还穿着我最好的衬衫哪。',NULL),
(1478,3,5,'zhTW','我當然記得那晚的情形。再往左邊偏個兩英吋，肯定就掛點了。那晚我還穿著我最好的襯衫呢。',NULL),
(1478,3,6,'deDE','War es das dritte oder vierte Mal, als du beinahe Hackfleisch aus mir gemacht hättest, als du einen deiner verrückten Tricks ausprobiert hast?',NULL),
(1478,3,6,'esES','¿No fue esa la tercera o cuarta vez que casi me destrozas probando una de tus locas proezas?',NULL),
(1478,3,6,'esMX','¿No fue esa la tercera o cuarta vez que casi me destrozas probando una de tus locas proezas?',NULL),
(1478,3,6,'frFR','C’était la troisième ou la quatrième fois que tu as bien failli me faire crever en me faisant essayer l’une de tes cascades démentes ?',NULL),
(1478,3,6,'koKR','자네가 그 정신 나간 묘기에 도전하다가 내가 복부에 크게 상처 입은 게 그때가 세 번째 아니면 네 번째였지, 아마?',NULL),
(1478,3,6,'zhCN','那是我第三次还是第四次呕吐了？你那些疯狂的烈酒……',NULL),
(1478,3,6,'zhTW','...那是第三次、還是第四次?你那些個瘋狂的舉動又害我差點肚破腸流了?',NULL),
(1478,3,7,'deDE','Ja, und danke, dass du mich in dieser Nacht meine eigene Hand zurück zu den Priestern hast tragen lassen.',NULL),
(1478,3,7,'esES','Sí, y gracias por dejarme llevar mi propia mano a los sacerdotes esa noche.',NULL),
(1478,3,7,'esMX','Sí, y gracias por dejarme llevar mi propia mano a los sacerdotes esa noche.',NULL),
(1478,3,7,'frFR','Oui, et merci de m’avoir laissé rapporter ma propre main aux prêtres cette nuit-là.',NULL),
(1478,3,7,'koKR','그래, 그날 밤 내 손을 가지고 사제들에게 돌아갈 수 있도록 해 준 건 고맙게 생각하네.',NULL),
(1478,3,7,'zhCN','嗯，谢谢你那天晚上让我能把自己的手捡回去。',NULL),
(1478,3,7,'zhTW','嗯，謝謝你那天晚上讓我能把自己的手撿回去給牧師治療。',NULL),
(1478,4,0,'deDE','Hehe, Schlappschwanz.',NULL),
(1478,4,0,'esES','Je, je, chaval.',NULL),
(1478,4,0,'esMX','Je, je, chaval.',NULL),
(1478,4,0,'frFR','Hé hé, mauviette.',NULL),
(1478,4,0,'koKR','헤헤, 소심하긴...',NULL),
(1478,4,0,'zhCN','呵呵，废物。',NULL),
(1478,4,0,'zhTW','呵呵，廢物。',NULL),
(1478,4,1,'deDE','Du hast geschrien wie ein kleines Mädchen - war das Lustigste, was ich je gesehen habe.',NULL),
(1478,4,1,'esES','Gritabas como una nena, fue lo más gracioso que he visto jamás.',NULL),
(1478,4,1,'esMX','Gritabas como una nena, fue lo más gracioso que he visto jamás.',NULL),
(1478,4,1,'frFR','Tu hurlais comme une gamine, je n\'ai jamais autant ri.',NULL),
(1478,4,1,'koKR','그때 자넨 어린 여자 아이처럼 비명을 질러댔지. 지금까지 내가 본 것 중 가장 우스운 광경이었어, 하하.',NULL),
(1478,4,1,'zhCN','你像个小女孩一般地尖叫，这真是我见过的最好笑的事。',NULL),
(1478,4,1,'zhTW','你叫得跟個小女孩一樣，真是我見過最好笑的事。',NULL),
(1478,4,2,'deDE','Am Ende hat doch alles geklappt.',NULL),
(1478,4,2,'esES','Al final todo salió bien.',NULL),
(1478,4,2,'esMX','Al final todo salió bien.',NULL),
(1478,4,2,'frFR','Tout a fini par rentrer dans l’ordre.',NULL),
(1478,4,2,'koKR','결국엔 다 잘 됐지.',NULL),
(1478,4,2,'zhCN','最后终于全搞定了。',NULL),
(1478,4,2,'zhTW','最後終於全搞定了。',NULL),
(1478,4,3,'deDE','Lass uns erst gar nicht damit anfangen, Kampfnarben zu vergleichen, mein Freund.',NULL),
(1478,4,3,'esES','Ay, amigo, no nos pongamos ahora a comparar nuestras cicatrices de guerra.',NULL),
(1478,4,3,'esMX','Ay, amigo, no nos pongamos ahora a comparar nuestras cicatrices de guerra.',NULL),
(1478,4,3,'frFR','Ne commençons pas à comparer nos cicatrices de guerre, mon ami.',NULL),
(1478,4,3,'koKR','전투에서 입은 흉터를 비교하는 짓은 아예 시작도 하지 말자고, 친구.',NULL),
(1478,4,3,'zhCN','让我们不要再比较身上的伤痕了，朋友。',NULL),
(1478,4,3,'zhTW','讓我們不要再比較身上的傷痕了，朋友。',NULL),
(1478,4,4,'deDE','Ich habe noch nie jemanden gesehen, der sich so schnell bewegt hat.',NULL),
(1478,4,4,'esES','En mi vida vi a alguien moverse tan rápido.',NULL),
(1478,4,4,'esMX','En mi vida vi a alguien moverse tan rápido.',NULL),
(1478,4,4,'frFR','Je n\'ai jamais vu personne se déplacer aussi vite.',NULL),
(1478,4,4,'koKR','내 지금껏 살면서 그렇게 빨리 움직이는 친구는 본 적이 없어.',NULL),
(1478,4,4,'zhCN','我从来没看到过有人逃得这么快。',NULL),
(1478,4,4,'zhTW','我從來沒看到過有人逃得這麼快。',NULL),
(1478,4,5,'deDE','Du überraschst mich ständig aufs Neue damit, was eine Person alles ertragen kann.',NULL),
(1478,4,5,'esES','Constantemente me sorprendes con todo lo que una persona es capaz de soportar.',NULL),
(1478,4,5,'esMX','Constantemente me sorprendes con todo lo que una persona es capaz de soportar.',NULL),
(1478,4,5,'frFR','Ça m’étonnera toujours, ce qu’une personne peut endurer…',NULL),
(1478,4,5,'koKR','자네와 같이 지내다 보면 그 파란만장한 삶에 끊임없이 놀라게 된다니까.',NULL),
(1478,4,5,'zhCN','你真的令我感到非常惊讶，你居然活了下来。',NULL),
(1478,4,5,'zhTW','你真的令我感到非常驚訝，你居然活了下來。',NULL),
(1478,4,6,'deDE','Nun, du bist immer noch hier. Ich würde sagen, dass wir darauf einen trinken sollten.',NULL),
(1478,4,6,'esES','Bien, aquí sigues. Parece que hay algo bueno de beber.',NULL),
(1478,4,6,'esMX','Bien, aquí sigues. Parece que hay algo bueno de beber.',NULL),
(1478,4,6,'frFR','Enfin, tu es encore là, et je trouve que ça justifie bien une tournée !',NULL),
(1478,4,6,'koKR','뭐, 우리가 아직 이렇게 살아 있다는 것만으로도 축배를 들 만한 일이 아닌가?',NULL),
(1478,4,6,'zhCN','好吧，你还好端端地坐在这里。我想说这里还是有些东西值得我们举杯庆贺的。',NULL),
(1478,4,6,'zhTW','好吧，你還好端端地坐在這裡。我想說這裡還是有些東西值得我們舉杯慶賀的。',NULL),
(1478,4,7,'deDE','Du kannst dich jederzeit bei mir dafür bedanken, dass ich dein Leben interessanter gemacht habe.',NULL),
(1478,4,7,'esES','Cuando quieras puedes agradecerme por hacer tu vida más interesante.',NULL),
(1478,4,7,'esMX','Cuando quieras puedes agradecerme por hacer tu vida más interesante.',NULL),
(1478,4,7,'frFR','Tu peux me remercier d’avoir ajouté un peu de piment à ta vie.',NULL),
(1478,4,7,'koKR','자네 삶을 아주 흥미진진하게 만들어 준 내게 항상 감사하라고.',NULL),
(1478,4,7,'zhCN','你可以在任何时候感谢我，因为我令你的生活更加有趣。',NULL),
(1478,4,7,'zhTW','你可以在任何時候感謝我，因為我令你的生活更加有趣。',NULL),
