(34851,0,0,'deDE','Was... Was sind diese Dinger da auf den Dächern?','Was... Was sind diese Dinger da auf den Dächern?'),
(34851,0,0,'esES','¿Qué... qué son esas cosas que andan por los tejados?','¿Qué... que son esas cosas que andan por los tejados?'),
(34851,0,0,'esMX','¿Qué... qué son esas cosas que andan por los tejados?','¿Qué... que son esas cosas que andan por los tejados?'),
(34851,0,0,'frFR','Ces… Ces choses sur le toit, c\'est quoi ?','Ces… Ces choses sur le toit, c\'est quoi ?'),
(34851,0,0,'koKR','저기... 지붕 위에 무언가가 있습니다!','저기... 지붕 위에 있는 게 뭔가요?'),
(34851,0,0,'zhCN','屋顶上那些……是什么东西？','屋顶上那些……是什么东西？'),
(34851,0,0,'zhTW','在那屋頂上的是...是什麼?','在那屋頂上的是...是什麼?'),
(34851,0,1,'deDE','So rette mich doch jemand!','So rette mich doch jemand!'),
(34851,0,1,'esES','¡Que alguien me salve!','¡Que alguien me salve!'),
(34851,0,1,'esMX','¡Que alguien me salve!','¡Que alguien me salve!'),
(34851,0,1,'frFR','Qu\'on me sauve, quelqu\'un !','Qu\'on me sauve, quelqu\'un !'),
(34851,0,1,'koKR','누가 좀 구해주세요!','누가 좀 구해주세요!'),
(34851,0,1,'zhCN','谁来救救我！','谁来救救我！'),
(34851,0,1,'zhTW','誰來救救我!','誰來救救我!'),
(34851,0,2,'deDE','Verschont mein Leben! Ich werde diesen Ort für immer verlassen! Bitte!','Verschont mein Leben! Ich werde diesen Ort für immer verlassen! Bitte!'),
(34851,0,2,'esES','¡Perdóname la vida! ¡Abandonaré este lugar para siempre! ¡Por favor!','¡Perdóname la vida! ¡Abandonaré este lugar para siempre! ¡Por favor!'),
(34851,0,2,'esMX','¡Perdóname la vida! ¡Abandonaré este lugar para siempre! ¡Por favor!','¡Perdóname la vida! ¡Abandonaré este lugar para siempre! ¡Por favor!'),
(34851,0,2,'frFR','Épargnez-moi ! Je jure de partir d\'ici ! Je vous en prie !','Épargnez-moi ! Je jure de partir d\'ici ! Je vous en prie !'),
(34851,0,2,'koKR','살려 주세요! 다시는 돌아오지 않겠습니다. 제발요!','살려 주세요! 다시는 돌아오지 않겠습니다. 제발요!'),
(34851,0,2,'zhCN','饶命！我会离开的！永远不会回来！求你！','饶命！我会离开的！永远不会回来！求你！'),
(34851,0,2,'zhTW','饒了我一命!我會永遠離開這個地方的!求求你!','饒了我一命!我會永遠離開這個地方的!求求你!'),
(34851,0,4,'deDE','Sie... sie haben versprochen, dass wir in Sicherheit wären...','Sie... sie haben versprochen, dass wir in Sicherheit wären...'),
(34851,0,4,'esES','Ell... Ellos prometieron que estaríamos a salvo...','Ell... Ellos prometieron que estaríamos a salvo...'),
(34851,0,4,'esMX','Ell... Ellos prometieron que estaríamos a salvo...','Ell... Ellos prometieron que estaríamos a salvo...'),
(34851,0,4,'frFR','Ils… Ils avaient promis de nous sauver…','Ils… Ils avaient promis de nous sauver…'),
(34851,0,4,'koKR','저... 저들이 우린 안전할 거라고 약속했는데...','저... 저들이 우린 안전할 거라고 약속했는데...'),
(34851,0,4,'zhCN','人生…人生真是无常啊...','人生…人生真是无常啊...'),
(34851,0,4,'zhTW','他...他們答應過要保我安全的...','他...他們答應過要保我安全的...'),
(34851,0,5,'esES','¡Soy demasiado joven para morir!','¡Soy demasiado joven para morir!'),
(34851,0,5,'esMX','¡Soy demasiado joven para morir!','¡Soy demasiado joven para morir!'),
(34851,0,6,'deDE','Bitte, ich gebe Euch alles, was Ihr verlangt! Nur lasst mir mein Leben!','Bitte, ich gebe Euch alles, was Ihr verlangt! Nur lasst mir mein Leben!'),
(34851,0,6,'esES','¡Pide lo que quieras y será tuyo! ¡Tan solo perdóname la vida!','¡Pide lo que quieras y será tuyo! ¡Tan solo perdóname la vida!'),
(34851,0,6,'esMX','¡Pide lo que quieras y será tuyo! ¡Tan solo perdóname la vida!','¡Pide lo que quieras y será tuyo! ¡Tan solo perdóname la vida!'),
(34851,0,6,'frFR','Demandez-moi n\'importe quoi, vous l\'aurez ! Mais ne me tuez pas !','Demandez-moi n\'importe quoi, vous l\'aurez ! Mais ne me tuez pas !'),
(34851,0,6,'koKR','뭐든 말씀만 하시면 드리겠습니다! 목숨만 살려주세요!','뭐든 말씀만 하시면 드리겠습니다! 제발 살려주세요!'),
(34851,0,6,'zhCN','我绝不会在敌人面前屈服的！','我绝不会在敌人面前屈服的！'),
(34851,0,6,'zhTW','只要饒我一命!你要任何東西，我都給!','只要饒我一命!你要任何東西，我都給!'),
(34851,1,0,'deDE','So einfach gehe ich nicht zu Boden!','So einfach gehe ich nicht zu Boden!'),
(34851,1,0,'esES','¡No acabarás conmigo tan fácilmente!','¡No acabarás conmigo tan fácilmente!'),
(34851,1,0,'esMX','¡No acabarás conmigo tan fácilmente!','¡No acabarás conmigo tan fácilmente!'),
(34851,1,0,'frFR','Je ne vais pas me laisser tuer si facilement !','Je ne vais pas me laisser tuer si facilement !'),
(34851,1,0,'koKR','그렇게 쉽게 죽지는 않을 것이다!','내가 그리 순순히 당할 것 같으냐!'),
(34851,1,0,'zhCN','我不会轻易倒下的！','我不会轻易倒下的！'),
(34851,1,0,'zhTW','我不會輕易倒下的!','我不會輕易倒下的!'),
(34851,1,1,'deDE','Stirb, Geißeldreck! STIRB!','Stirb, Geißeldreck! STIRB!'),
(34851,1,1,'esES','¡Muere, perro de la Plaga! ¡MUERE!','¡Muere, perro de la Plaga! ¡MUERE!'),
(34851,1,1,'esMX','¡Muere, perro de la Plaga! ¡MUERE!','¡Muere, perro de la Plaga! ¡MUERE!'),
(34851,1,1,'frFR','Meurs, chien du Fléau ! MEURS !','Meurs, chien du Fléau ! MEURS !'),
(34851,1,1,'koKR','스컬지의 개 같으니! 죽어라!','스컬지의 개 같으니! 죽어라!'),
(34851,1,1,'zhCN','天灾的走狗！死吧！','天灾的走狗！死吧！'),
(34851,1,1,'zhTW','死吧，天譴走狗!死吧!','死吧，天譴走狗!死吧!'),
(34851,1,2,'deDE','Ist das alles, was die Geißel drauf hat?','Ist das alles, was die Geißel drauf hat?'),
(34851,1,2,'esES','¿Es esto lo mejor que puede conseguir la Plaga?','¿Es esto lo mejor que puede conseguir la Plaga?'),
(34851,1,2,'esMX','¿Es esto lo mejor que puede conseguir la Plaga?','¿Es esto lo mejor que puede conseguir la Plaga?'),
(34851,1,2,'frFR','C\'est tout ce que dont le Fléau est capable ?','C\'est tout ce que dont le Fléau est capable ?'),
(34851,1,2,'koKR','스컬지라는 것들이 겨우 이 정도였나?','스컬지라는 것들이 겨우 이 정도였군?'),
(34851,1,2,'zhCN','这就是你全部的能耐吗？','这就是你全部的能耐吗？'),
(34851,1,2,'zhTW','這就是天譴軍的能耐嗎?','這就是天譴軍的能耐嗎?'),
(34851,1,3,'deDE','Ihr könnt mir vielleicht mein Leben nehmen, aber nicht meine Freiheit!','Ihr könnt mir vielleicht mein Leben nehmen, aber nicht meine Freiheit!'),
(34851,1,3,'esES','¡Puedes quitarme la vida, pero no me quitarás la libertad!','¡Puedes quitarme la vida, pero no me quitarás la libertad!'),
(34851,1,3,'esMX','¡Puedes quitarme la vida, pero no me quitarás la libertad!','¡Puedes quitarme la vida, pero no me quitarás la libertad!'),
(34851,1,3,'frFR','Tu peux me prendre ma vie, mais tu n\'auras jamais ma liberté !','Tu peux me prendre ma vie, mais tu n\'auras jamais ma liberté !'),
(34851,1,3,'koKR','목숨은 빼앗겨도 자유는 빼앗기지 않으리라!','목숨은 빼앗겨도 자유는 빼앗기지 않을 거다!'),
