(37951,0,0,'frFR','$n, Zuni, votre maître, vous l\'trouverez sur le terrain d\'entraînement à l\'est. Les Sombrelances, faites-leur honneur.',NULL),
(37951,0,0,'koKR','동쪽의 훈련장에 직업 상급자가 있네. 검은창 부족의 자부심을 보여주게.',NULL),
(37951,0,0,'zhCN','$n。祖尼。你们可以在东边的训练场找到你的训练师。不要给暗矛部族丢脸。',NULL),
(37951,0,0,'zhTW','$n。朱尼。你們會在東邊的訓練區那找到你的訓練師。為暗矛帶來榮耀。',NULL),
(37988,0,0,'deDE','Ja, Mann. Lasst uns ein paar Tikizielschädel knacken!',NULL),
(37988,0,0,'esES','Sí, colega. ¡Aplah\'temos algunas calaveras diana Tiki!',NULL),
