(37988,0,0,'frFR','Yo. Viens, on va casser la tête des cibles tiki !',NULL),
(37988,0,0,'koKR','좋습니다, 친구. 티키 표적을 박살 냅시다!',NULL),
(37988,0,0,'zhCN','耶，兄弟。去敲烂几个蒂基面具假人吧！',NULL),
(37988,0,0,'zhTW','是啊，老兄。讓我們敲爛一些提基頭顱吧!',NULL),
(37988,1,0,'deDE','Dein Lehrer sollte hier irgendwo in der Nähe sein. Ich seh dich dann später, Mann.',NULL),
(37988,1,0,'esES','Tu inh\'tructor debería andar po\' aquí. No\' vemos luego, colega.',NULL),
(37988,1,0,'esMX','Tu entrenador tiene que estar por aquí. Hablamos luego, hombre.',NULL),
(37988,1,0,'frFR','Ton maître, il doit être quelque part par ici. On s\'revoit plus tard.',NULL),
(37988,1,0,'koKR','당신을 가르쳐줄 사람이 여기 어딘가에 있을 겁니다. 나중에 봅시다.',NULL),
(37988,1,0,'zhCN','你的训练师应该就在不远的地方。稍后我再来找你，兄弟。',NULL),
