(38225,0,0,'deDE','Es war dumm von dir, herzukommen, Meerhexe. Einmal bist du unserer Rache entgangen, noch einmal kommst du uns nicht davon.',NULL),
(38225,0,0,'esES','Venir aquí ha si\'o una insensatez, Bruja del Mar. Escapah’te a nueh’tra venganza una vez, pero la tribu Lanza Neg\'a no volverá a tolerar que nos invadas de nuevo.',NULL),
(38225,0,0,'esMX','Qué tonta fuiste en venir aquí, Bruja de Mar. Ya escapaste a nuestra venganza, pero la Tribu Lanza Negra no te volverá a permitir esta ofensa.',NULL),
(38225,0,0,'frFR','Venir ici c\'était idiot, sorcière des mers. Notre vengeance, tu y as échappé une fois, mais les Sombrelances ils vont pas te laisser revenir.',NULL),
(38225,0,0,'koKR','여기로 돌아오다니, 바보 같은 것. 네가 한 번은 복수의 손길을 빠져나갔다만, 검은창 부족이 이번에도 널 봐주리라 생각지는 마라.',NULL),
(38225,0,0,'zhCN','你来到这里是个错误，女海巫。你曾经逃脱过我们的复仇。但暗矛氏族不会容忍你再次践踏我们的家园。',NULL),
(38225,0,0,'zhTW','海巫，你真的很蠢才會來這。你本來已經逃離我們的復仇，但這次暗矛部族不會再忍受你的入侵。',NULL),
(38225,1,0,'deDE','Sie entzieht ihre Macht aus dem Feuer! Schnell, löscht die Kohlenpfannen!',NULL),
(38225,1,0,'esES','¡Está absorbiendo energía del fuego! ¡Apaga las hogueras, rápido!',NULL),
(38225,1,0,'esMX','¡Está absorbiendo energía del fuego! ¡Apaga las hogueras, rápido!',NULL),
(38225,1,0,'frFR','Elle tire son pouvoir des feux ! Étouffez les braseros, vite !',NULL),
(38225,1,0,'koKR','바다 마녀가 불에서 힘을 뽑아내고 있습니다. 빨리 화로를 끄십시오!',NULL),
(38225,1,0,'zhCN','她正在从火焰中吸取力量！赶快扑灭火盆！',NULL),
(38225,1,0,'zhTW','她正在從火中吸取能量!撲滅火盆!快!',NULL),
(38225,2,0,'deDE','Es ist vollbracht. Unsere uralte Feindin ist vernichtet.',NULL),
(38225,2,0,'esES','Eh’tá hecho. Nueh’tra vieja enemiga ha si\'o derrota\'a.',NULL),
(38225,2,0,'esMX','Hecho está. Nuestro enemigo ancestral, derrotado.',NULL),
(38225,2,0,'frFR','C\'est fait. Notre vieille ennemie, elle a perdu.',NULL),
(38225,2,0,'koKR','끝났네. 오랜 원수를 마침내 처치했군.',NULL),
(38225,2,0,'zhCN','结束了。我们古老的敌人被击败了。',NULL),
(38225,2,0,'zhTW','結束了。我們的宿敵被擊敗了。',NULL),
(38225,3,0,'deDE','Ich habe lange darauf gewartet, meinen Vater zu rächen. Eine große Last wurde von meinen Schultern genommen.',NULL),
(38225,3,0,'esES','Llevaba mucho tiempo eh’perando la opoh’tunidad de vengar a mi padre. El peso que cargaba en mis hombros ha desapareci\'o.',NULL),
(38225,3,0,'esMX','Esperé mucho tiempo la oportunidad de vengar a mi padre. Mis hombros ya no cargan ese peso enorme.',NULL),
(38225,3,0,'frFR','Longtemps j\'ai attendu de pouvoir venger mon père. Le grand poids qui était sur mes épaules il est parti.',NULL),
(38225,3,0,'koKR','참으로 오랫동안 아버님의 복수를 염원했다네. 오늘 드디어 그 무거운 짐을 내려놓는군.',NULL),
(38225,3,0,'zhCN','为了清算我父亲的仇恨，我已经等待了很长时间。现在，这副重担终于卸下了。',NULL),
(38225,3,0,'zhTW','我等待了很久才找到機會替我父親報仇。我肩膀上的重擔終於減輕了。',NULL),
(38225,4,0,'deDE','Ich muss zur Dunkelspeerfeste zurück. Komm zu mir, sobald Vanira die Heilung des Jungen vollendet hat.',NULL),
(38225,4,0,'esES','Debo regresar al Bah’tión Lanza Neg\'a. Reúnete allí conmigo cuando Vanira te\'mine de sanar al muchacho.',NULL),
(38225,4,0,'esMX','Debo volver al Bastión Lanza Negra. Ven a buscarme cuando Vanira ya haya curado al chico.',NULL),
(38225,4,0,'frFR','Le bastion des Sombrelances, je dois y retourner. Retrouve-moi là-bas quand Vanira elle aura fini de soigner le petit.',NULL),
(38225,4,0,'koKR','나는 검은창 요새로 돌아가야 하네. 바니라가 소년을 치료하고 나면 돌아와서 날 찾아오게.',NULL),
(38225,4,0,'zhCN','我必须回到暗矛要塞去。当瓦妮拉结束对这个孩子的治疗以后，请到那里去找我。',NULL),
