(39128,1,0,'ruRU','Неужели слишком поздно? Я чувствую присутствие Смертокрыла!',NULL),
(39128,1,0,'zhCN','是否已经太晚了？我感觉到死亡之翼就在附近！',NULL),
(39128,1,0,'zhTW','太遲了嗎?我感覺到死亡之翼在附近!',NULL),
(39128,2,0,'deDE','Der Feuerfürst ist auferstanden! Wir müssen die anderen warnen. Beeilung!',NULL),
