(39128,2,0,'esMX','¡El Señor del Fuego se ha levantado! Avisemos a los demás. ¡Pronto!',NULL),
(39128,2,0,'frFR','Le seigneur du Feu s\'est réveillé ! Nous devons prévenir les autres. Faisons vite !',NULL),
(39128,2,0,'koKR','불의 군주가 나타났군! 다른 이에게 알려야 한다. 서두르자!',NULL),
(39128,2,0,'ruRU','Повелитель Огня пробудился! Нужно оповестить остальных. Скорей!',NULL),
