(42646,0,0,'zhTW','笨蛋$r還以為$g他:她;是我老大。',NULL),
(42646,1,0,'deDE','Das war mein bester Kampf seit Wochen! Den Rest spare ich für unsere Feinde auf.',NULL),
(42646,1,0,'esES','¡Es la mejor pelea que he tenido desde hace semanas! Reservaré lo demás para nuestros enemigos.',NULL),
(42646,1,0,'esMX','¡Es la mejor pelea que he tenido desde hace semanas! Reservaré lo demás para nuestros enemigos.',NULL),
(42646,1,0,'frFR','C\'est ma plus belle baston depuis des semaines ! Je vais garder le reste en réserve pour nos ennemis.',NULL),
(42646,1,0,'koKR','지난 몇 주간 벌인 싸움 중에 제일 대단했소! 이제는 우리 적과 싸우겠소.',NULL),
(42646,1,0,'ruRU','Это моя лучшая драка за последние недели! Остальную энергию оставлю для врагов.',NULL),
(42646,1,0,'zhCN','那是我几个星期以来最痛快的一次吵架了！我要把剩下的留给我们的敌人。',NULL),
(42646,1,0,'zhTW','這幾個禮拜以來就屬這一架打得最過癮。其他的就留給我們的敵人吧。',NULL),
