(44086,0,1,'deDE','Meine Kinder sind alleine in Sturmsiel! Ich muss zu ihnen!','Meine Kinder sind alleine in Sturmsiel! Ich muss zu ihnen!'),
(44086,0,1,'esES','¡Mis hijos están solos en Valletormenta! ¡Tengo que ir a por ellos!','¡Mis hijos están solos en Valletormenta! ¡Tengo que ir a por ellos!'),
(44086,0,1,'esMX','¡Mis hijos están solos en Valletormenta! ¡Tengo que ir por ellos!','¡Mis hijos están solos en Valletormenta! ¡Tengo que ir por ellos!'),
(44086,0,1,'frFR','Mes enfants sont tous seuls à Val-Tempête ! Il faut que je les rejoigne !','Mes enfants sont tous seuls à Val-Tempête ! Il faut que je les rejoigne !'),
(44086,0,1,'koKR','아이들이 폭풍협곡에 혼자 있습니다! 아이들에게 가 봐야 한단 말입니다!','아이들이 폭풍협곡에 혼자 있어요! 아이들에게 가 봐야 해요!'),
(44086,0,1,'zhCN','我的孩子们还在风谷村里，没有人照顾！我必须去找到他们！','我的孩子们还在风谷村里，没有人照顾！我必须去找到他们！'),
