(44086,0,2,'deDE','Was ist los? Ich dachte, ich hätte was auf den Dächern gesehen.','Was ist los? Ich dachte, ich hätte was auf den Dächern gesehen.'),
(44086,0,2,'esES','¿Qué está pasando? Me ha parecido ver algo por los tejados.','¿Qué está pasando? Me ha parecido ver algo por los tejados.'),
(44086,0,2,'esMX','¿Qué está pasando? Me ha parecido ver algo por los tejados.','¿Qué está pasando? Me ha parecido ver algo por los tejados.'),
(44086,0,2,'frFR','Qu\'est-ce qui se passe ? Je crois que j\'ai vu quelque chose sur les toits.','Qu\'est-ce qui se passe ? Je crois que j\'ai vu quelque chose sur les toits.'),
(44086,0,2,'koKR','무슨 일이 일어난 겁니까? 지붕 위에서 뭔가를 본 것 같은데 말이죠.','무슨 일이 일어난 건가요? 지붕 위에서 뭔가를 본 것 같아요.'),
(44086,0,2,'zhCN','出了什么事？我仿佛看到有什么东西在房顶上。','出了什么事？我仿佛看到有什么东西在房顶上。'),
(44086,0,2,'zhTW','發生什麼事情?我好像看到屋頂上有東西。','發生什麼事情?我好像看到屋頂上有東西。'),
(44086,0,3,'deDE','Wir müssen hier raus! Das Heulen wird jede Nacht lauter.','Wir müssen hier raus! Das Heulen wird jede Nacht lauter.'),
(44086,0,3,'esES','¡Tenemos que salir de aquí! Cada noche los aullidos suenan más altos.','¡Tenemos que salir de aquí! Cada noche los aullidos suenan más altos.'),
(44086,0,3,'esMX','¡Tenemos que salir de aquí! Cada noche los aullidos suenan más altos.','¡Tenemos que salir de aquí! Cada noche los aullidos suenan más altos.'),
(44086,0,3,'frFR','Il faut qu\'on parte d\'ici ! Les hurlements sont plus forts chaque nuit.','Il faut qu\'on parte d\'ici ! Les hurlements sont plus forts chaque nuit.'),
(44086,0,3,'koKR','어서 이곳을 벗어나야만 합니다! 울부짖는 소리가 매일 밤 더 커지고 있단 말입니다.','어서 이곳을 벗어나야만 해요! 울부짖는 소리가 매일 밤 더 커지고 있단 말이에요.'),
(44086,0,3,'zhCN','我们必须离开这里！嚎叫声每晚都在变得更大。','我们必须离开这里！嚎叫声每晚都在变得更大。'),
