(46935,0,0,'deDE','Der große Schmelztiegel des Gemetzels erwartet Euch, $n. Denkt dran: Sobald der Kampf begonnen hat, müsst Ihr in der Arena bleiben. SIEGT ODER STERBT!',NULL),
(46935,0,0,'esES','Te espera el gran Crisol de Matanza, $n. Recuerda, una vez empieza la pelea, tienes que permanecer en la arena. ¡GANA O MUERE!',NULL),
(46935,0,0,'esMX','Te espera el gran Crisol de Matanza, $n. Recuerda, una vez empieza la pelea, tienes que permanecer en la arena. ¡GANA O MUERE!',NULL),
(46935,0,0,'frFR','Le grand Creuset du carnage vous attend, $n. N\'oubliez pas, une fois qu\'un combat est lancé, vous devez rester dans l\'arène. LA VICTOIRE OU LA MORT !',NULL),
(46935,0,0,'koKR','웅장한 대학살의 도가니가 자네를 기다리는군, $n. 기억하라고. 일단 전투가 시작되면 투기장에서 나가면 안 돼. 죽이 되든 밥이 되든 말이지!',NULL),
(46935,0,0,'ruRU','Горнило Крови ждет тебя, $n. Помни, как только начнется бой, тебе нельзя покидать арену. ПОБЕДА ИЛИ СМЕРТЬ!',NULL),
(46935,0,0,'zhCN','伟大的杀戮熔炉正在等着你，$n。记住，当战斗开始的时候，你将无法离开竞技场。你的结局非赢即死！',NULL),
(46935,0,0,'zhTW','偉大的兇殘之爐競技場正在等著你，$n。切記，一旦戰鬥開始了，你就得待在競技場的場地裡頭。不是勝利就是死亡!',NULL),
(46935,1,0,'deDE','Hier sind wir wieder, meine Damen und Herren. Der epische Kampf um Leben und Tod im Schmelztiegel des Gemetzels! In dieser Runde kämpft $n gegen einen... dicken, fetten Oger? Wartet, ernsthaft?! Das ist alles, was uns so kurzfristig eingefallen ist? Wofür bezahle ich Euch?',NULL),
(46935,1,0,'esES','Aquí estamos de nuevo, damas y caballeros. ¡El épico conflicto entre vida y muerte en el Crisol de Matanza! En esta ronda tenemos a $n contra... ¿un ogro la tira de gordo? ¡¿Cómo, en serio?! ¿Esto es lo mejor que hemos encontrado con poca antelación? ¿Para qué os pago?',NULL),
(46935,1,0,'esMX','Aquí estamos de nuevo, damas y caballeros. ¡El épico conflicto entre vida y muerte en el Crisol de Matanza! En esta ronda tenemos a $n contra... ¿un orco bien gordo? ¡¿Cómo, en serio?! ¿Esto es lo mejor que hemos encontrado con poca antelación? ¿Para qué les pago?',NULL),
(46935,1,0,'frFR','Nous nous retrouvons une nouvelle fois, mesdames et messieurs. L\'affrontement épique entre la Vie et la Mort dans le Creuset du carnage ! Pour le round suivant, je vous présente $n contre… un ogre obèse ? Euh, sérieusement ?! Vous n\'avez pas eu le temps de trouver mieux ? Mais à quoi je vous paie ?',NULL),
(46935,1,0,'koKR','신사 숙녀 여러분, 새로운 이야기가 시작됩니다. 대학살의 도가니에서 펼쳐지는 삶과 죽음의 드라마를 지켜보십시오! 이번에 $n의 상대는... 무지 뚱뚱한 오우거? 잠깐, 이게 뭐야?! 뭐? 시간이 없어서 이렇게밖에 못 썼다고? 그러고는 무슨 월급을 받겠다는 거야?!',NULL),
(46935,1,0,'ruRU','Дамы и господа, эпическая борьба между жизнью и смертью в Горниле Крови снова начинается! В этом раунде $n встретится с... жирным огром? Серьезно? А кого-то получше мы не могли подыскать? За что я вам деньги плачу, спрашивается?',NULL),
(46935,1,0,'zhCN','女士们，先生们，我们共聚在杀戮熔炉，再次见证生与死的伟大战斗！在这一轮中，我们将看到$n与……一个真正的肥食人魔对战？等等，这是真的？！我们就只能看到这个？我付钱给你是为了什么？',NULL),
(46935,1,0,'zhTW','女士先生們，我們又再度來到此處。生與死的精采掙扎即將在兇殘之爐競技場內展開!這一回合要和$n對決的是...一隻真的很肥的巨魔?等一下，這不是在搞笑吧?!什麼?臨時就只找得到這種選手?我付錢請你到底是幹什麼的?',NULL),
(46935,2,0,'deDE','Wie dem auch sei, möge der Kampf beginnen!',NULL),
(46935,2,0,'esES','¡Qué más da! ¡Que empiece la pelea!',NULL),
(46935,2,0,'esMX','¡Qué más da! ¡Que empiece la pelea!',NULL),
(46935,2,0,'frFR','Peu importe, que le combat commence !',NULL),
(46935,2,0,'koKR','하여튼, 전투를 시작합니다!',NULL),
(46935,2,0,'ruRU','Как бы там ни было, бой начинается!',NULL),
(46935,2,0,'zhCN','不管怎样，让战斗开始吧！',NULL),
(46935,2,0,'zhTW','隨便啦，決鬥開始!',NULL),
(46935,3,0,'deDE','S-S-S-SIEGER! Wir haben einen Sieger! Gut gemacht und so!',NULL),
(46935,3,0,'esES','¡V-V-V-VICTORIA! ¡Tenemos $gun ganador:una ganadora;! ¡Buen trabajo y todo eso!',NULL),
(46935,3,0,'esMX','¡V-V-V-VICTORIA! ¡Tenemos $gun ganador:una ganadora;! ¡Buen trabajo y todo eso!',NULL),
(46935,3,0,'frFR','V-V-V-VICTOIRRRRE ! Nous avons un vainqueur ! Bravo et tutti quanti !',NULL),
(46935,3,0,'koKR','오오! 승부가 났습니다! 승리자가 결정됐어요! 힘찬 박수로 축하해 주십시오!',NULL),
(46935,3,0,'ruRU','ПОБЕДИ-И-ТЕЛЬ! У нас есть победитель! Вот это уровень! Вот это класс!',NULL),
(46935,3,0,'zhCN','有人赢了——赢了赢了赢了赢了！我们有了一位胜利者！干得漂亮！',NULL),
(46935,3,0,'zhTW','冠—冠—冠—冠軍!冠軍誕生了!幹得好啊!',NULL),
(46935,4,0,'deDE','Der große Schmelztiegel des Gemetzels erwartet Euch, $n. Denkt dran: Sobald der Kampf begonnen hat, müsst Ihr in der Arena bleiben. SIEGT ODER STERBT!',NULL),
(46935,4,0,'esES','Te espera el gran Crisol de Matanza, $n. Recuerda, una vez empieza la pelea, tienes que permanecer en la arena. ¡GANA O MUERE!',NULL),
(46935,4,0,'esMX','Te espera el gran Crisol de Matanza, $n. Recuerda, una vez empieza la pelea, tienes que permanecer en la arena. ¡GANA O MUERE!',NULL),
(46935,4,0,'frFR','Le grand Creuset du carnage vous attend, $n. N\'oubliez pas, une fois qu\'un combat est lancé, vous devez rester dans l\'arène. LA VICTOIRE OU LA MORT !',NULL),
(46935,4,0,'koKR','웅장한 대학살의 도가니가 자네를 기다리는군, $n. 기억하라고. 일단 전투가 시작되면 투기장에서 나가면 안 돼. 죽이 되든 밥이 되든 말이지!',NULL),
(46935,4,0,'ruRU','Горнило Крови ждет тебя, $n. Помни, как только начнется бой, тебе нельзя покидать арену. ПОБЕДА ИЛИ СМЕРТЬ!',NULL),
(46935,4,0,'zhCN','伟大的杀戮熔炉正在等着你，$n。记住，当战斗开始的时候，你将无法离开竞技场。你的结局非赢即死！',NULL),
(46935,4,0,'zhTW','偉大的兇殘之爐競技場正在等著你，$n。切記，一旦戰鬥開始了，你就得待在競技場的場地裡頭。不是勝利就是死亡!',NULL),
(46935,5,0,'deDE','Ich habe diesmal etwas ganz BESONDERES für Euch, Leute! An diesen Halbling kommt keiner ran! $n gegen den wilden Wildhammer... SULLY KNIESCHEIBLER!!!',NULL),
(46935,5,0,'esES','¡Esta vez tengo una PEQUEÑA sorpresa para vosotros, amigos! ¡No eres la mitad de hombre que este medio-hombre! ¡¡¡$n contra el despiadado SULLY CORTARRÓTULAS de los Martillo Salvaje!!!',NULL),
(46935,5,0,'esMX','¡Esta vez tengo una PEQUEÑA sorpresa para ustedes, amigos! ¡No eres la mitad de hombre que este medio-hombre! ¡¡¡$n contra el despiadado SULLY CORTARRÓTULAS de los Martillo Salvaje!!!',NULL),
(46935,5,0,'frFR','Cette fois-ci, mes amis, j\'ai un PETIT quelque chose de spécial à vous proposer ! Même un homme averti ne vaut pas la moitié de cette moitié d\'homme ! $n contre le féroce Marteau-hardi… Sully Pète-Rotule !',NULL),
(46935,5,0,'koKR','여러분, 이번엔 특별히 "조그만" 놀라움을 준비했습니다! 작은 고추가 매운 법! 잔인한 와일드해머 드워프... 설리 니캐퍼와 $n의 대결을 지켜보십시오!',NULL),
(46935,5,0,'ruRU','На сей раз у меня для вас есть МА-А-АЛЕНЬКИЙ сюрприз, друзья мои! Вы не стоите и половины этого полурослика! Итак, $n против яростного дворфа Громового Молота... Сулла Коленодроба!!!',NULL),
(46935,5,0,'zhCN','接下来为大家准备了个特别的节目！你们在这家伙面前简直渺小如微尘！$n对决凶残的蛮锤斗士……萨利·碎膝！！！',NULL),
(46935,5,0,'zhTW','各位觀眾!這回我特別安排了個「小」東西要給大家!告訴你們，你們連這個一半身高的傢伙的一半都比不上!由$n對決最兇、最狠的蠻錘矮人:蘇利·碎膝者!',NULL),
(46935,6,0,'deDE','Dieser Kampf wird auf jeden Fall KURZ sein! Okay, okay, ich bin ja schon fertig. Möge das Blutbad beginnen!',NULL),
(46935,6,0,'esES','¡Esta pelea seguro que será de CORTA duración! Está bien, está bien, ya termino. ¡Que empiece el baño de sangre!',NULL),
(46935,6,0,'esMX','¡Esta pelea seguro que será de CORTA duración! Está bien, está bien, ya termino. ¡Que empiece el baño de sangre!',NULL),
(46935,6,0,'frFR','Ce combat devrait être COURT ! Oui, bon, d\'accord, j\'arrête. Que le bain de sang commence !',NULL),
(46935,6,0,'koKR','이번 경기는 정말로 짧을 겁니다! 네, 네, 쓸데없는 소리는 이만 줄이지요. 피의 향연을 즐기십시오!',NULL),
(46935,6,0,'ruRU','Этот бой уж точно должен быть КОРОТКИМ! Ладно, ладно, я закругляюсь. Пусть начнется кровавая бойня!',NULL),
(46935,6,0,'zhCN','这一战必定会速战速决！好吧，好吧，我说完了。血战开始！',NULL),
(46935,6,0,'zhTW','相信這場比賽肯定也只要一半的時間就會打完了!好了，好了，我說完了。開始屠殺吧!',NULL),
(46935,7,0,'deDE','Meine Damen und Herren, diese Verursacher von Verstümmelungen sind SIEGREICH aus dem Kampf hervorgetreten! Die Wetten für die nächste Runde werden ab sofort entgegen genommen! Lasst die Münzen springen!',NULL),
(46935,7,0,'esES','¡Damas y caballeros, estos campeones de la desmembración han salido VICTORIOSOS! ¡Desde ahora se aceptan apuestas para la siguiente ronda! Qué empiece a fluir el dinero.',NULL),
(46935,7,0,'esMX','¡Damas y caballeros, estos campeones de la desmembración han salido VICTORIOSOS! ¡Desde ahora se aceptan apuestas para la siguiente ronda! Qué empiece a fluir el dinero.',NULL),
(46935,7,0,'frFR','Mesdames et messieurs, les distributeurs de démembrements triomphent ! Les paris sont ouverts pour le prochain round ! Faites-moi circuler tout ce bel argent.',NULL),
(46935,7,0,'koKR','신사 숙녀 여러분, 상대를 박살 내 버린 우리의 승리자를 보십시오! 바로 지금 다음 판 베팅을 시작합니다! 흐름을 놓치지 마십시오.',NULL),
(46935,7,0,'ruRU','Леди и джентльмены, те, кто выстоял в этой кровавой бойне, – наши ПОБЕДИТЕЛИ! Ставки на следующий раунд уже принимаются! Пусть денежки текут рекой, дорогие мои!',NULL),
(46935,7,0,'zhCN','女士们，先生们，这些斗士已经取得了胜利！下一场的赌盘现在开始！让我们的钱舞动起来吧。',NULL),
(46935,7,0,'zhTW','先生女士們，這些肢解者們獲得了勝利!下一輪的下注開始了!快快下注!',NULL),
(46935,8,0,'deDE','Der Kampf wird in Kürze beginnen! $n gegen den wilden Drachenmalorc, Torg Drachenschinder! Ich FINDE jedenfalls, dass er wild ist - es ist schwer zu sagen. Ich habe ihn nur hier reingelassen, weil sie uns ihre alte Arena hier benutzen lassen. Hoffen wir mal auf Blut!',NULL),
(46935,8,0,'esES','¡El combate está a punto de comenzar! ¡$n contra el sañoso Faucedraco, Torg Cazadraco! Bueno, CREO que es sañoso, es difícil de decir. Solo le he dejado pasar porque nos traspasaron esta vieja arena. ¡Ojalá haya sangre!',NULL),
(46935,8,0,'esMX','¡El combate está a punto de comenzar! ¡$n contra el sañoso Faucedraco, Torg Cazadraco! Bueno, CREO que es sañoso, es difícil de decir. Solo le he dejado pasar porque nos traspasaron esta vieja arena. ¡Ojalá haya sangre!',NULL),
(46935,8,0,'frFR','Le combat va commencer ! $n contre le cruel guerrier des Gueules-de-dragon, Torg Écorche-drake ! En tout cas, je suis presque sûr qu\'il est cruel, même si ça paraît dur à dire. À vrai dire, je l\'ai juste laissé participer parce qu\'ils nous ont autorisés à récupérer leur vieille arène. Allez, et prions pour un bain de sang !',NULL),
(46935,8,0,'koKR','전투가 곧 시작됩니다! 잔인한 용아귀 부족, 비룡잡이 토르그와 $n의 대결입니다! 잔인한 상대 맞겠죠?! 뭐, 확실하진 않습니다만... 우리에게 자신들의 옛 싸움터를 내준 데 감사하는 뜻에서 그냥 그렇다고 쳐 주죠. 피비린내나는 한판을 기대해 봅시다!',NULL),
(46935,8,0,'ruRU','Бой вот-вот начнется! $n против разъяренного орка из Драконьей Пасти, Торга Свежевателя Драконов! ЛИЧНО Я ДУМАЮ, он ВСЕГДА разъярен, но нам сложно судить. Я допустил его, поскольку они отдали нам свою старую арену. Что ж, надеемся на кровопролитную схватку!',NULL),
(46935,8,0,'zhCN','战斗就要开始了！$n对凶狠的龙喉兽人——“托格·掠龙者”！嗯，我想他应该是很凶狠的，虽然现在还很难说。既然他们让我们管理他们的老竞技场，我就把他放了出来。因为这里需要一些真正精彩的战斗！',NULL),
(46935,8,0,'zhTW','決鬥即將展開!由$n對決龍喉氏族最兇狠的獸人，托爾格·剝龍者!好啦，我覺得他應該是很兇狠才對啦—不過其實這也很難講，因為是龍喉氏族的傢伙把這個舊競技場給我們用，我才讓他參加的。好好流點血給我們瞧瞧吧!',NULL),
(46935,9,0,'deDE','Schmerzhaft, aber wunderschön! Gurgthock gibt Euch, was Ihr wollt! Die beste Blutbadvorstellung in ganz Azeroth! Zeigt mir ein wenig Liebe, Leute!',NULL),
(46935,9,0,'esES','¡Doloroso pero hermoso! ¡Gurgthock os da lo que queréis! ¡El mejor espectáculo de masacre de todo Azeroth! ¡Gente, mostradme vuestro amor!',NULL),
(46935,9,0,'esMX','¡Doloroso pero hermoso! ¡Gurgthock les da lo que quieren! ¡El mejor espectáculo de masacre de todo Azeroth! ¡Gente, muéstrenme su amor!',NULL),
(46935,9,0,'frFR','Douloureux mais majestueux ! Gurgthock vous donne ce que vous vouliez : un carnage d\'une qualité insurpassée sur Azeroth. Allez, montrez comme vous l\'aimez !',NULL),
(46935,9,0,'koKR','끔찍하지만 아름다운 경기! 이 굴그토크는 언제나 여러분이 바라는 장면을 보여 드립니다. 아제로스에서 가장 극적인 대학살! 만족하셨다면 박수로 화답해 주십시오!',NULL),
(46935,9,0,'ruRU','Болезненно, конечно, но ведь прекрасно! Гаргток дает вам то, чего вы ждете! Блестящий пример резни по-азеротски. Ну? Восхищайтесь же, народ!',NULL),
(46935,9,0,'zhCN','痛苦，但是美丽！古尔戈索克将满足你们的欲望！这是艾泽拉斯最有观赏性的角斗场。朋友们，让我感受到你们的热情吧！',NULL),
(46935,9,0,'zhTW','痛苦的美學!葛爾薩克會給你所要的!艾澤拉斯最棒的屠殺表演!表現一下你們的熱情吧!',NULL),
(46935,10,0,'deDE','Stellt Euch meine Überraschung vor, als mich das Genie der Verlassenen Calder Grau ansprach und mir vorschlug, einen Kämpfer aus all den Teilen unserer vorherigen Champions zusammenzuflicken... BUCHSTÄBLICH! Wer könnte so eine Gelegenheit ungenutzt verstreichen lassen, CALDERS SCHÖPFUNG herauszufordern?!',NULL),
(46935,10,0,'esES','Imaginad mi sorpresa cuando el genio Renegado, Calder Gray, se puso en contacto conmigo y me propuso un combatiente que reúne las mejores características de nuestros anteriores campeones... ¡LITERALMENTE! ¡¿Quién podría negarse a desafiar la CREACIÓN DE CALDER?!',NULL),
(46935,10,0,'esMX','Imagínense mi sorpresa cuando el genio Renegado, Calder Gray, se puso en contacto conmigo y me propuso un combatiente que reúne las mejores características de nuestros anteriores campeones... ¡LITERALMENTE! ¡¿Quién podría negarse a desafiar la CREACIÓN DE CALDER?!',NULL),
(46935,10,0,'frFR','Imaginez ma surprise quand un véritable génie parmi les Réprouvés, Calder Gray, m\'a approché et proposé un combattant qui regrouperait ce qu\'il y avait de mieux chez nos précédents champions... LITTÉRALEMENT ! Qui serait assez idiot pour laisser passer une occasion de défier la CRÉATURE DE CALDER ?!',NULL),
(46935,10,0,'koKR','여러분, 천재 포세이큰 과학자, 칼더 그레이가 제게 연락해 엄청난 투사를 제공하겠다는 제안을 했습니다. 지난 모든 용사들의 가장 훌륭한 특징을 말 그대로 "합쳐 놓은" 투사를요! 제가 얼마나 놀랐을지 상상이 가십니까? 칼더의 창조물과 싸워볼 기회를 세상 어느 용사가 거부할 수 있겠습니까?!',NULL),
(46935,10,0,'ruRU','Вообразите мое удивление, когда ко мне обратился гениальный Отрекшийся, Колдер Грей, и предложил бойца, состоящего из лучших боевых частей наших предыдущих чемпионов... в БУКВАЛЬНОМ СМЫСЛЕ СЛОВА! Кто может отказаться от шанса бросить вызов ТВОРЕНИЮ КОЛДЕРА?!',NULL),
(46935,10,0,'zhCN','想象一下，当我遇到那个被遗忘者天才卡尔德·格雷的时候，是多么惊讶。他说，他制造出了一名战士，那名战士拥有以前所有勇士的全部最优秀的能力……真的会有这样的战士！有谁能拒绝向卡尔德的造物挑战的机会？！',NULL),
(46935,10,0,'zhTW','各位請想像一下，當考德爾·葛雷這位被遺忘者的鬼才主動來找我的時候，當時我有多麼驚訝。而且他還帶來了一位「真的」結合了許多歷屆冠軍勇士精髓的參賽者!誰能夠拒絕得了如此難得的機會，挑戰考德爾的創作?!',NULL),
(46935,11,0,'deDE','Wisst Ihr, was man sagt... Wenn Ihr sie nicht besiegen könnt, schließt Euch ihnen an. In diesem Fall werdet Ihr diese Wahl nicht haben! Schmelztiegel des Gemetzels, ich finde dich einfach anbetungswürdig.',NULL),
(46935,11,0,'esES','Ya sabéis lo que dicen... Si no puedes vencerlos, ¡únete a ellos! ¡En este caso, no hay alternativa! Crisol de Matanza, cuánto te quiero.',NULL),
(46935,11,0,'esMX','Ya saben lo que dicen... Si no puedes vencerlos, ¡únete a ellos! ¡En este caso, no hay alternativa! Crisol de Matanza, cuánto te quiero.',NULL),
(46935,11,0,'frFR','Vous savez ce qu\'on dit… Si l\'ennemi est trop fort, attachez-vous à lui. Et dans le cas présent, ce sera avec du fil et une aiguille ! Oh, Creuset du carnage, comme je t\'aime.',NULL),
(46935,11,0,'koKR','그런 말이 있습니다... 꺾지 못할 상대와는 차라리 함께하라고요! 이 자리에서 패배한 도전자는 선택의 여지도 없이 상대와 함께해야 합니다! 아아, 찬란한 대학살의 도가니여!',NULL),
(46935,11,0,'ruRU','Знаете, как говорят... Если не можешь победить, присоединяйся! А в этом случае у вас даже не будет иного выбора! Горнило Крови – я его просто обожаю!',NULL),
(46935,11,0,'zhCN','你知道他们所说的……如果不能击败他们，就加入他们！除此之外，你将别无选择！杀戮熔炉，我是如此热爱你。',NULL),
(46935,11,0,'zhTW','你知道俗話是怎麼說的...打不贏人家，就加入人家!可惜，這回恐怕你沒有這個機會啦!兇殘之爐，我愛你!',NULL),
(46935,12,0,'deDE','OOOOOOOH! Jetzt seht Euch mal dieses Durcheinander an! Ein erstaunlicher Sieg! Was für eine Art, ihn mit dem Stock zu treffen!',NULL),
(46935,12,0,'esES','¡OOOOOOOH! ¡Mirad esa masacre! ¡Una victoria alucinante! ¡Vaya forma de atravesarlo con eso!',NULL),
(46935,12,0,'esMX','¡OOOOOOOH! ¡Miren esa masacre! ¡Una victoria alucinante! ¡Vaya forma de atravesarlo con eso!',NULL),
(46935,12,0,'frFR','OOOOOHHH ! Mais regardez-moi ce bain de sang ! Fantastique victoire ! Quelle mise à mort de fort belle facture !',NULL),
(46935,12,0,'koKR','오오오오오! 정말 끔찍한 광경이로군요! 놀라운 승리입니다! 멋들어지게 처리했어요!',NULL),
(46935,12,0,'ruRU','О-о! Только поглядите на эти ошметки! Какая победа! Потрясающее зрелище!',NULL),
(46935,12,0,'zhCN','哦！！！看看这混乱的一切！真是令人震惊的胜利！他到底有着怎样的力量！',NULL),
(46935,12,0,'zhTW','噢噢噢噢!看看那堆血肉模糊的東西!贏得真漂亮!看看穿過他的東西!',NULL),
(46935,13,0,'deDE','UFF! Der hier wird den "Schaber" brauchen.',NULL),
(46935,13,0,'esES','¡UUUF! Ese va a necesitar el "raspador".',NULL),
(46935,13,0,'esMX','¡UUUF! Ese va a necesitar el "raspador".',NULL),
(46935,13,0,'frFR','OUILLE ! Pour nettoyer celle-là, il va falloir sortir « le Grattoir ».',NULL),
(46935,13,0,'koKR','우왓! 저분은 완전히 곤죽이 되셨는데요.',NULL),
(46935,13,0,'ruRU','УФФ! Этого придется отчищать "скребком"."',NULL),
(46935,13,0,'zhCN','哇！那家伙需要好好地“刮一刮”！',NULL),
(46935,13,0,'zhTW','「嗚嗚咈! 那個需要『鏟土機』。」',NULL),
(46935,14,0,'deDE','Aus der nähergelegenen, geschundenen Landschaft stammend, die einst Gilneas war, erhebt sich unser Champion! Glaubt mir, $n, dem Mann wollt Ihr nicht im Mondschein begegnen!',NULL),
(46935,14,0,'esES','¡Nuestro siguiente campeón procede del desastre relativamente distante que antes fuera Gilneas! ¡Que no se te caigan los pantalones, $n, no quieres que este tío vea la luna llena!',NULL),
(46935,14,0,'esMX','¡Nuestro siguiente campeón procede del desastre relativamente distante que antes fuera Gilneas! ¡Que no se te caigan los pantalones, $n, no quieres que este tipo vea la luna llena!',NULL),
(46935,14,0,'frFR','Venu tout droit des pas si lointains que ça vestiges ravagés de ce qui fut un jour Gilnéas, voici notre champion ! Attachez bien votre pantalon, $n, lui montrer la pleine lune ne serait pas très judicieux.',NULL),
(46935,14,0,'koKR','그리 멀지 않은 그곳, 한때 길니아스라고 불린 짓밟힌 땅에서 우리의 용사가 분연히 일어났습니다! $n|1과;와; 친구들은 단단히 준비해야 할 겁니다. 특히 이번 상대에게 보름달을 보여 주는 건 금기라는 사실을 명심하십시오!',NULL),
(46935,14,0,'ruRU','Наш следующий герой родом из живописных развалин, ранее называвшихся Гилнеасом! Подтяни штаны, $n, ты же не хочешь ослепить его своим блеском?',NULL),
(46935,14,0,'zhCN','从遥远的吉尔尼斯废墟中传出阵阵吼声，我们的勇士来了！把裤子穿好，$n，你不会想让他看到两轮满月吧！',NULL),
(46935,14,0,'zhTW','來自有點遙遠而且毀得差不多的吉爾尼斯，誕生了我們這位勇士!拉好你的褲頭，$n，千萬別讓這傢伙看到你跟滿月一樣圓的屁股!',NULL),
(46935,15,0,'deDE','Man kann es einfach nicht leugnen - da ist aber mal jemand richtig gefaltet worden! So viel zu unserem früheren Champion!',NULL),
(46935,15,0,'esES','¡No se puede negar... que han acabado con ese perro! ¡Vaya ex campeón!',NULL),
(46935,15,0,'esMX','¡No se puede negar... que han acabado con ese perro! ¡Vaya ex campeón!',NULL),
(46935,15,0,'frFR','On ne peut pas le nier, ils lui ont fait un mal de chien ! Et voilà notre ancien champion expédié !',NULL),
(46935,15,0,'koKR','아, 승부가 났습니다. 도전자들이 저 멍멍이를 확실히 쓰러뜨렸습니다! 대학살의 도가니 최고의 용사가 이렇게 무너지나요!',NULL),
(46935,15,0,'ruRU','Они прикончили эту собаку! Вот и конец нашему защитнику!',NULL),
(46935,15,0,'zhCN','不可否认——他们真的干掉了那条狗！我们的前任冠军也只不过是这个水平而已！',NULL),
(46935,15,0,'zhTW','這是無庸置疑的，他們把那條狗搞定了!我們的前任冠軍也不怎麼樣嘛!',NULL),
(46935,16,0,'deDE','Es sieht so aus, als hätten wir noch einen weiteren Herausforderer, also haltet Euch nicht zurück bei den Wetten!',NULL),
(46935,16,0,'esES','Al parecer hay otro contendiente al que tenemos que hacer frente, así que ¡quiero ver esas apuestas!',NULL),
(46935,16,0,'esMX','Al parecer hay otro contendiente al que tenemos que hacer frente, así que ¡quiero ver esas apuestas!',NULL),
(46935,16,0,'frFR','Mais il semblerait bien qu\'il reste un prétendant à affronter ! Alors faites-moi tourner ces paris !',NULL),
(46935,16,0,'koKR','그러나 우리의 도전자들을 상대할 자가 아직 한 명 더 남아 있습니다. 자, 돈을 거십시오!',NULL),
(46935,16,0,'ruRU','Но, похоже, нам придется сразиться еще с одним претендентом. Так что давайте, делайте ставки!',NULL),
(46935,16,0,'zhCN','看样子，我们又有了一个新的挑战者。现在，大家下注吧！',NULL),
(46935,16,0,'zhTW','看起來我們還有一個挑戰者要面對，所以快點下注吧!',NULL),
(46935,17,0,'deDE','Der Schattenhammer: immer erfreut, den örtlichen ruchlosen Intrigen zu dienen, jederzeit, überall. Und heute ist keine Ausnahme! Unser letzter Kämpfer grüßt aus der Bastion des Zwielichts! Oder der Zwielichtbastion... ach, wen interessiert\'s!',NULL),
(46935,17,0,'esES','El Martillo Crepuscular: dispuestos a entregar planes malvados en cualquier sitio, en cualquier momento. ¡Y hoy no es una excepción! ¡Nuestro combatiente final procede del no muy distante Bastión del Crepúsculo! ¿O era El Bastión Crepuscular...? ¡Bah, qué más da!',NULL),
(46935,17,0,'esMX','El Martillo Crepuscular: dispuestos a entregar planes malvados en cualquier sitio, en cualquier momento. ¡Y hoy no es una excepción! ¡Nuestro combatiente final procede del no muy distante Bastión del Crepúsculo! ¿O era El Bastión Crepuscular...? ¡Bah, qué más da!',NULL),
(46935,17,0,'frFR','Le Marteau du crépuscule, fournisseur officiel de main-d\'œuvre pour plans machiavéliques locaux depuis des générations. Et ce n\'est pas aujourd\'hui que ça va changer ! Notre dernier combattant nous vient du pas-si-lointain bastion du Crépuscule ! Ou du bastion Crépusculaire, je ne sais jamais... Bah, on s\'en fout !',NULL),
(46935,17,0,'koKR','언제 어디서나 여러분 주위에 범죄가 끊이지 않도록 불철주야 노력하는 황혼의 망치단, 오늘도 예외는 아닙니다! 오늘의 마지막 투사는 바로 저 황혼의 요새에서 나온 인물입니다... 뭐, 무슨 상관이겠습니까!',NULL),
(46935,17,0,'ruRU','"Сумеречный Молот: счастливы воплощать злобные замыслы – когда угодно и где угодно." И этот день не исключение! Наш последний боец прибыл из не столь отдаленного Сумеречного бастиона! Или правильно называть бастион Сумрака... Да какая разница!',NULL),
(46935,17,0,'zhCN','暮光之锤：随时随地愿意为实现各种邪恶计划出力，今天也不例外！我们的终极战士向大家致敬！他们来自不远处的暮光堡垒……或者那是暮光城堡……管他呢，谁会在乎这个！',NULL),
(46935,17,0,'zhTW','暮光之錘:隨時隨地都願意扮演壞人。當然啦，今天也不例外!我們最後一位參戰者就來自不算太遠的暮光城堡!還是暮光堡壘...啊，隨便啦!',NULL),
(46935,18,0,'deDE','Ihr hasst es doch alle, dass Ihr liebt, und es macht ihm gar nichts aus, den Hass direkt wieder zurückzugeben. WIR... WOLLEN... BLUT... SEHEN!!!',NULL),
(46935,18,0,'esES','A todos os encantará odiarlo, y él está contento de devolveros vuestro odio. ¡¡QUE... EMPIECE... LA CARNICERÍA!!',NULL),
(46935,18,0,'esMX','A todos les encantará odiarlo, y él está contento de devolverles su odio. ¡¡QUE... EMPIECE... LA CARNICERÍA!!',NULL),
(46935,18,0,'frFR','Vous adorez le détester, et lui est ravi d\'avoir une occasion de vous rendre votre haine à tous. FAUT… QUE… ÇA… SAIGNE !',NULL),
(46935,18,0,'koKR','여러분 모두 열과 성을 다해 이자를 미워하시겠지요. 하지만 이자 또한 자신의 증오를 여러분께 기꺼이 퍼부을 것입니다. 최후의... 경기를... 시작합니다!!!',NULL),
(46935,18,0,'ruRU','Вы все так его ненавидите, и он рад отплатить вам тем же. ТАК ПУСТЬ... ПРОЛЬЕТСЯ... КРОВЬ!!!',NULL),
(46935,18,0,'zhCN','你们全都热衷于痛恨他。而他也喜欢向你们表达他的恨意。让……战斗……开始吧！！！',NULL),
(46935,18,0,'zhTW','你們都很愛仇視他，而他也會很樂意把仇恨灑向大家。讓我們...見血吧!',NULL),
(46935,19,0,'deDE','ICH GLAUBE ES NICHT! Wir HABEN EINEN NEUEN METZELCHAMPION!!! Unser großer, bulliger Herausforderer wurde von einer bunt zusammengewürfelten Gruppe von Namenlosen besiegt! Unglaubliches Finale!',NULL),
(46935,19,0,'esES','¡NO ME LO PUEDO CREER! ¡¡TENEMOS UN NUEVO CAMPEÓN DE MATANZA!! ¡Nuestro campeón grande y robusto ha caído ante una panda de alfeñiques! ¡Un final espectacular!',NULL),
(46935,19,0,'esMX','¡NO ME LO PUEDO CREER! ¡¡TENEMOS UN NUEVO CAMPEÓN DE MATANZA!! ¡Nuestro campeón grande y robusto ha caído ante una panda de alfeñiques! ¡Un final espectacular!',NULL),
(46935,19,0,'frFR','C\'EST TOUT BONNEMENT INCROYABLE ! LE CARNAGE A UN NOUVEAU CHAMPION !! Notre grand méchant prétendant a été vaincu par une banale équipe d\'obscurs inconnus ! Quel coup de théâtre !',NULL),
(46935,19,0,'koKR','믿을 수가 없군요! 새로운 용사가 대학살의 도가니를 접수했습니다! 어중이떠중이로 이루어진 어설픈 무리에게 거칠고 우람하고 악랄한 우리 투사들이 패배하고 말았어요! 참으로 극적입니다!',NULL),
(46935,19,0,'ruRU','ГЛАЗАМ СВОИМ НЕ ВЕРЮ! У НАС ЕСТЬ НОВЫЙ ЧЕМПИОН!!! Наш великий, ужасный и мускулистый претендент сражен – и кем! Командой новичков-оборванцев! Невероятный финал!',NULL),
(46935,19,0,'zhCN','难以置信！新的杀戮勇士诞生了！！！我们高大的，凶恶的，力大无穷的挑战者被一个衣衫褴褛的无名之辈打败了！真是个不可思议的结局！',NULL),
(46935,19,0,'zhTW','不敢相信!新的兇殘勇士誕生了!!!我們又大又壞又猛的挑戰者被一群不起眼的無名小卒給打敗了!了不起!',NULL),
(46945,0,0,'deDE','Das gesamte Hochland gehört dem Drachenmal - sogar diese Grube!',NULL),
(46945,0,0,'esES','¡Todas las tierras altas pertenecen a los Faucedraco, incluido este foso!',NULL),
(46945,0,0,'esMX','¡Todas las tierras altas pertenecen a los Faucedraco, incluido este foso!',NULL),
(46945,0,0,'frFR','Toutes les hautes-terres sont aux Gueules-de-dragon, même cette fosse !',NULL),
(46945,0,0,'koKR','황혼의 고원은 전부 다 용아귀 부족의 것이다! 이 구덩이도 마찬가지야!',NULL),
(46945,0,0,'ruRU','Все нагорье принадлежит Драконьей Пасти, и эта яма тоже!',NULL),
(46945,0,0,'zhCN','这片高地全都属于龙喉氏族，这个大坑也不例外！',NULL),
(46945,0,0,'zhTW','整座高地都是龍喉氏族的，就連這兒也一樣!',NULL),
(46945,1,0,'deDE','Bemitleidenswerte Fleischsäcke! Spürt die volle Kraft des Drachenmals!',NULL),
(46945,1,0,'esES','¡Patéticos sacos de carne! ¡Sentid la verdadera fuerza de los Faucedraco!',NULL),
(46945,1,0,'esMX','¡Patéticos sacos de carne! ¡Sentid la verdadera fuerza de los Faucedraco!',NULL),
(46945,1,0,'frFR','Pitoyables tas de viande ! Subissez la pleine puissance des Gueules-de-dragon !',NULL),
(46945,1,0,'koKR','한심한 고기 덩어리 같으니! 용아귀 부족의 진정한 힘을 느껴 봐라!',NULL),
(46945,1,0,'ruRU','Жалкие мешки с костями! Почувствуйте всю мощь Драконьей Пасти!',NULL),
(46945,1,0,'zhCN','可怜的酒囊饭袋！好好看着龙喉的强大力量吧！',NULL),
(46945,1,0,'zhTW','沒用的東西!看看龍喉氏族真正的力量!',NULL),
(46946,0,0,'deDE','Meine kleine Schwester ist besser als die meisten von Euch. Dies ist keine Arena. Das ist ein Kindergarten!',NULL),
(46946,0,0,'esES','Mi hermanita pequeña podría daros una paliza a todos. ¡Esto no es una arena, esto es una guardería!',NULL),
(46946,0,0,'esMX','Mi hermanita pequeña podría darles una paliza a todos. ¡Esto no es una arena, esto es una guardería!',NULL),
(46946,0,0,'frFR','Ma petite sœur pourrait vous coller une fessée à tous. C\'est pas une arène, ici, c\'est une maternelle !',NULL),
(46946,0,0,'koKR','내 여동생도 너희보다는 낫겠다. 이게 무슨 투기장이야? 보육원이지!',NULL),
(46946,0,0,'ruRU','Моя младшая сестричка победила бы многих из вас. Это не арена, это песочница какая-то!',NULL),
(46946,0,0,'zhCN','我的小妹妹也能把你们都打趴下。这里不是竞技场。这里根本就是个托儿所！',NULL),
(46946,0,0,'zhTW','連我小妹都能打敗你們全部的人。這根本不是競技場，這是托兒所!',NULL),
(46947,0,0,'deDE','Calder hat gesagt, wenn ich Euch töte, bekomme ich Eure Einzelteile.',NULL),
(46947,0,0,'esES','¡Calder me ha dicho que si te mato, puedo quedarme con tus miembros!',NULL),
(46947,0,0,'esMX','¡Calder me ha dicho que si te mato, puedo quedarme con tus miembros!',NULL),
(46947,0,0,'frFR','Calder m\'a dit que si je vous tue, j\'ai le droit de garder les morceaux !',NULL),
(46947,0,0,'koKR','너 처치하면 네 몸뚱이 준다고 칼더 아빠가 약속했다!',NULL),
(46947,0,0,'ruRU','Колдер сказал, если я тебя убью, получу в награду части твоего тела!',NULL),
(46947,0,0,'zhCN','卡尔德说，如果我杀了你，我就能得到你的零件！',NULL),
(46947,0,0,'zhTW','考德爾說，要是我宰了你，我就可以分到你的一部分!',NULL),
(46947,1,0,'deDE','Iehhh! Verzieht Euch, Ihr garstiges Etwas.',NULL),
(46947,1,0,'esES','¡Puaj! ¡Aléjate de mí, bicho repugnante!',NULL),
(46947,1,0,'esMX','¡Puaj! ¡Aléjate de mí, bicho repugnante!',NULL),
(46947,1,0,'frFR','Ahh ! Beuark ! N\'approche pas de moi, truc ignoble !',NULL),
(46947,1,0,'koKR','에잇! 저리 가, 이 고약한 놈아!',NULL),
(46947,1,0,'ruRU','Ы-ых! Уйди от меня, дрянь такая!',NULL),
(46947,1,0,'zhCN','呃！离我远点，你这个脏东西！',NULL),
(46947,1,0,'zhTW','噁!離我遠一點，噁心的東西!',NULL),
(46947,2,0,'deDE','Wie Ihr Wünscht, Vater!',NULL),
(46947,2,0,'esES','¡Como quieras, Papá!',NULL),
(46947,2,0,'esMX','¡Como quieras, Papá!',NULL),
(46947,2,0,'frFR','D\'accord, papa !',NULL),
(46947,2,0,'koKR','응, 아빠!',NULL),
(46947,2,0,'ruRU','Как скажешь, папочка!',NULL),
(46947,2,0,'zhCN','如你所愿，爸爸！',NULL),
(46947,2,0,'zhTW','是的，爸爸!',NULL),
(46947,3,0,'deDE','Oh! Zu voll... oh nein...',NULL),
(46947,3,0,'esES','¡Oh! Demasiado lleno... Oh no...',NULL),
(46947,3,0,'esMX','¡Oh! Demasiado lleno... Oh no...',NULL),
(46947,3,0,'frFR','Oh ! Un peu… ballonné… Oh, oh…',NULL),
(46947,3,0,'koKR','어! 너무 배불러... 안 돼...',NULL),
(46947,3,0,'ruRU','Ох! Слишком много... О нет...',NULL),
(46947,3,0,'zhCN','哦！太满了……哦，不……',NULL),
(46947,3,0,'zhTW','哦!太滿了...哦，不...',NULL),
(46948,0,0,'deDE','Hallo Leute! Ich habe heute Abend eine nicht so überraschende Überraschung für Euch.',NULL),
(46948,0,0,'esES','Vaya, hola, chicos. Tengo una sorpresa no muy sorprendente para vosotros esta noche.',NULL),
(46948,0,0,'esMX','Vaya, hola, chicos. Tengo una sorpresa no muy sorprendente para ustedes esta noche.',NULL),
(46948,0,0,'frFR','Et bien le bonjour mes chers amis, j\'ai une petite surprise pas si surprenante que ça pour vous, aujourd\'hui.',NULL),
(46948,0,0,'koKR','반갑다, 애송이들아. 이 아름다운 저녁에, 그렇게까지 놀랍지는 않은 놀라움을 하나 선사해 주지.',NULL),
(46948,0,0,'ruRU','О, привет, ребятки, у меня этим вечером припасен для вас не такой уж и неожиданный сюрприз.',NULL),
(46948,0,0,'zhCN','你们好，伙计们，今晚，我为你们准备了一个不应该让你们太吃惊的惊喜。',NULL),
(46948,0,0,'zhTW','嗨，夥計們，今晚我有個不算太驚喜的驚喜要給你們。',NULL),
(46948,1,0,'deDE','Ich muss sagen, ich hab jetzt langsam die Nase voll davon. Es wird Zeit, die INNERE BESTIE FREIZULASSEN!',NULL),
(46948,1,0,'esES','Me atrevo a decir que ya he tenido suficiente. Hora de desatar... ¡LA BESTIA INTERIOR!',NULL),
(46948,1,0,'esMX','Me atrevo a decir que ya he tenido suficiente. Hora de desatar... ¡LA BESTIA INTERIOR!',NULL),
(46948,1,0,'frFR','Je dois dire que j\'en ai assez de tout ça. Il est temps de lâcher… LA BÊTE QUI EST EN MOI !',NULL),
(46948,1,0,'koKR','단언하건대, 이런 놀음도 여기서 끝이다. 때가 되었군... 내 안의 야수가 등장할 때가!',NULL),
(46948,1,0,'ruRU','Рискну заявить, что с меня довольно. Пора выпустить... ЗВЕРЯ!',NULL),
(46948,1,0,'zhCN','我对这一切已经受够了。现在该是让……野兽之心出来的时候了！',NULL),
(46948,1,0,'zhTW','我已經受夠了。時候到了，該叫出我...心中的野獸!',NULL),
(46948,2,0,'deDE','Genug gespielt! Es wird Zeit, dass ich mir die Hände schmutzig mache!',NULL),
(46948,2,0,'esES','¡Ya basta de juegos! ¡Hora de mancharme las manos!',NULL),
(46948,2,0,'esMX','¡Ya basta de juegos! ¡Hora de mancharme las manos!',NULL),
(46948,2,0,'frFR','Assez joué ! Il est temps de me salir les mains !',NULL),
(46948,2,0,'koKR','장난은 여기서 그만두지! 이제 손에 피를 묻힐 시간이다!',NULL),
(46948,2,0,'ruRU','Ну, поигрались и будет! Пришло время обагрить руки кровью!',NULL),
(46948,2,0,'zhCN','玩够了！现在该是下手的时候了！',NULL),
(46948,2,0,'zhTW','好，玩夠了!該是我雙手染血的時候了!',NULL),
(46949,0,0,'deDE','Dieses Land soll durch die Flamme des Zwielichts geläutert werden!',NULL),
(46949,0,0,'esES','¡La Llama del Crepúsculo purgará esta tierra!',NULL),
(46949,0,0,'esMX','¡La Llama del Crepúsculo purgará esta tierra!',NULL),
(46949,0,0,'frFR','Cette terre sera purgée par la flamme du Crépuscule !',NULL),
(46949,0,0,'koKR','이 땅은 황혼의 불꽃 아래 정화되리라!',NULL),
(46949,0,0,'ruRU','Земля очистится в пламени Сумерек!',NULL),
(46949,0,0,'zhCN','这片土地应该在暮光烈焰中被净化！',NULL),
(46949,0,0,'zhTW','該以暮光之火淨化這片土地!',NULL),
(46949,1,0,'deDE','Brennt in der flüssigen Hitze der Feuerlande!',NULL),
(46949,1,0,'esES','¡Arde en el calor líquido de las Tierras de Fuego!',NULL),
(46949,1,0,'esMX','¡Arde en el calor líquido de las Tierras de Fuego!',NULL),
(46949,1,0,'frFR','Brûlez dans les flammes liquides des terres de Feu !',NULL),
(46949,1,0,'koKR','불의 땅을 흐르는 열기에 타버려라!',NULL),
(46949,1,0,'ruRU','Гори в жидком пламени Огненных Просторов!',NULL),
(46949,1,0,'zhCN','在火焰之地的流火中被烧毁吧！',NULL),
(46949,1,0,'zhTW','在火源之界的液態火焰中燃燒吧!',NULL),
(46949,2,0,'deDE','Selbst die Himmel brennen mit meinem Zorn!',NULL),
(46949,2,0,'esES','¡Incluso los cielos arden con mi furia!',NULL),
(46949,2,0,'esMX','¡Incluso los cielos arden con mi furia!',NULL),
(46949,2,0,'frFR','Même les cieux brûleront sous ma fureur !',NULL),
(46949,2,0,'koKR','하늘도 내 분노로 타오른다!',NULL),
(46949,2,0,'ruRU','Моя ярость поджигает даже небеса!',NULL),
(46949,2,0,'zhCN','就连天空也要在我的怒火中燃烧！',NULL),
(46949,2,0,'zhTW','連天空都因我的憤怒燃燒!',NULL),
