(47512,0,0,'esES','¡Ve, mi bello ángel! Ah, es tan triste cuando los hijos abandonan el nido, ¿verdad?',NULL),
(47512,0,0,'esMX','¡Ve, mi bello ángel! Ah, es tan triste cuando los hijos abandonan el nido, ¿verdad?',NULL),
(47512,1,0,'deDE','Es wird Zeit für deinen letzten Angriff, mein Schatz!',NULL),
(47512,1,0,'esES','¡Es hora de tu ataque definitivo, cariño!',NULL),
(47512,1,0,'esMX','¡Es hora de tu ataque definitivo, cariño!',NULL),
(47512,1,0,'frFR','Il va être temps de lancer ton attaque ultime, mon trésor !',NULL),
(47512,1,0,'koKR','아가야, 이제 네 최고의 기술을 사용할 시간이다!',NULL),
(47512,1,0,'ruRU','Пришло время твоей решающей атаки, дорогуша!',NULL),
(47512,1,0,'zhCN','该是发动最后一击的时候了，亲爱的！',NULL),
(47512,1,0,'zhTW','親愛的，是發動你的終極攻擊的時候了!',NULL),
(47512,2,0,'deDE','Was? Meine Schöpfung! Sie hat noch nicht einmal den Himmel ausgelöscht! Ich gucke besser noch einmal in meine Notizen...',NULL),
(47512,2,0,'esES','¿Qué...? ¡Mi creación! ¡Ni siquiera ha oscurecido el cielo! Mejor repaso mis notas...',NULL),
(47512,2,0,'esMX','¿Qué...? ¡Mi creación! ¡Ni siquiera ha oscurecido el cielo! Mejor repaso mis notas...',NULL),
(47512,2,0,'frFR','Que… Ma créature ! Elle n\'a même pas obscurci le ciel ! Hum, il va falloir que je vérifie mes calculs…',NULL),
(47512,2,0,'koKR','이럴 수가... 내 창조물이! 하늘을 가릴 만큼 커지지도 않았는데! 연구 일지를 다시 살펴보는 게 좋겠군...',NULL),
(47512,2,0,'ruRU','Что... мое творение! Оно еще не успело сделать и половины всех мерзостей, которые я запланировал! Мне следует перепроверить свои записи...',NULL),
(47512,2,0,'zhCN','什么……我的创造物！它甚至没有飞上过天空！我最好检查一下我的笔记……',NULL),
(47512,2,0,'zhTW','什麼...我的傑作!連把天空遮住都沒有!我最好再看一下我的筆記...',NULL),
(47512,3,0,'deDE','Eure Körper sind alle fantastisch! Wenn ihr gewillt wäret, eine kleine Prise von diesem Chloroform zu nehmen, verspreche ich Euch, dass ihr alle 10-mal stärker und 100-mal... vereinter in eurem Willen wieder erwachen würdet.',NULL),
(47512,3,0,'esES','¡Vuestros cuerpos son magníficos! Si estuvierais dispuestos a aspirar ligeramente el aroma de este cloroformo, os prometo que os despertaréis 10 veces más fuertes y 100 veces más... unificados con ese propósito.',NULL),
(47512,3,0,'esMX','¡Sus cuerpos son magníficos! Si estuvieran dispuestos a aspirar ligeramente el aroma de este cloroformo, les prometo que los despertará 10 veces más fuertes y 100 veces más... unificados con ese propósito.',NULL),
(47512,3,0,'frFR','Oh, comme vos corps sont beaux dans l\'effort ! Tenez, reniflez juste une petite bouffée de ce chloroforme, et je vous promets que vous vous réveillerez tous dix fois plus forts et cent fois plus… unis.',NULL),
(47512,3,0,'koKR','자네의 몸은 참으로 훌륭하군! 내 약속하지. 이 마취제를 조금만 들이키면, 깨어날 땐 지금보다 10배는 더 강하고 100배는 더... 계획적으로 조화를 이룬 모습이 될 걸세.',NULL),
(47512,3,0,'ruRU','Великолепные тела! Не хотите нюхнуть хлороформа? Когда проснетесь, то станете в 10 раз сильнее и в 100 раз... единодушнее.',NULL),
(47512,3,0,'zhCN','你们的身体条件都很出色！如果你们愿意吸点儿这种麻醉剂，我保证当你们醒来时会比现在强壮10倍，凝聚力比现在强……100倍。',NULL),
(47512,3,0,'zhTW','你們的身體十分驚人。如果你們願意喝下一點點麻醉藥劑，我保證你們醒來時會比現在強十倍，而且會比現在更為...團結百倍。',NULL),
(47512,4,0,'deDE','Nein? Tja... mein Angebot gilt. Kommt einfach jederzeit vorbei und ich werde Euch mit Freuden die Generalüberholung verpassen, von der Ihr immer geträumt habt.',NULL),
(47512,4,0,'esES','¿No? Bueno... Mi oferta sigue en pie. Venid cuando queráis y estaré más que contento de facilitaros las mejoras con las que habéis soñado.',NULL),
(47512,4,0,'esMX','¿No? Bueno... Mi oferta sigue en pie. Vengan cuando quieran y estaré más que contento de facilitarles las mejoras con las que han soñado.',NULL),
(47512,4,0,'frFR','Non ? Bon… Mon offre reste ouverte. Passez quand vous voulez, et c\'est avec plaisir que je vous ferai cette petite révision dont vous avez toujours rêvé.',NULL),
(47512,4,0,'koKR','싫다고? 그래... 어쨌든 내 제안은 아직 유효하네. 마음이 바뀌면 언제든 들르게. 자네가 꿈에 그리던 모습으로 손봐 줄 테니.',NULL),
(47512,4,0,'ruRU','Нет? Ну ладно... мое предложение остается в силе. Заходите в любое время. Я с радостью сделаю вас такими, какими вы всегда мечтали стать.',NULL),
(47512,4,0,'zhCN','不愿意？好吧……这项提议永远有效。欢迎随时到我这里来，我很乐意提供你们梦寐以求的大变身。',NULL),
(47512,4,0,'zhTW','不要?好吧...我的提議仍然有效。你任何時候都能來找我，我會給你一直想要的美容。',NULL),
