(49141,9,0,'esMX','¡Buen trabajo! Los has encontrado. Se los llevaré a Mordo.',NULL),
(49141,9,0,'frFR','Joli travail ! Vous les avez trouvées. Rapportons-les à Mordo.',NULL),
