(53565,1,0,'deDE','Ich habe mein Geld auf Lam gesetzt. Habt Ihr gesehen, wie er letzte Woche während des Trainings Chu besiegt hat?',NULL),
(53565,1,0,'esES','He apostado por Lam. ¿Viste como derrotó a Chu en el entrenamiento de la semana pasada?',NULL),
(53565,1,0,'esMX','He apostado por Lam. ¿Viste como derrotó a Chu en el entrenamiento de la semana pasada?',NULL),
(53565,1,0,'frFR','Je parie sur Lam. Tu l’as vu mettre sa raclée à Chu pendant l’entraînement de la semaine dernière ?',NULL),
(53565,1,0,'koKR','난 램한테 걸래. 지난주 대련할 때 추를 꺾는 거 봤어?',NULL),
(53565,1,0,'zhCN','我押蓝获胜。你没看见他在上周的训练中，是怎么打倒楚的吗？',NULL),
(53565,1,0,'zhTW','我賭連姆贏。你沒看他在上週的訓練裡打倒了小楚嗎?',NULL),
(53565,2,0,'deDE','Seine Kondition verblasst im Angesicht von Lams Stärke.',NULL),
(53565,2,0,'esES','Su resistencia no es nada comparada con la fuerza de Lam.',NULL),
(53565,2,0,'esMX','Su resistencia no es nada comparada con la fuerza de Lam.',NULL),
(53565,2,0,'frFR','Son endurance ne fait pas le poids face à la force de Lam.',NULL),
(53565,2,0,'koKR','그래 봤자 램의 힘에 대면 아무것도 아니지.',NULL),
(53565,2,0,'zhCN','周的耐力在蓝的力量面前不值一提。',NULL),
(53565,2,0,'zhTW','他的耐力在連姆的力量面前完全沒用。',NULL),
(53565,3,0,'deDE','Er hat die Beine eines Ochsen! Habt ihr während des Trainings schon einmal einen Tritt von ihm abbekommen?',NULL),
(53565,3,0,'esES','¡Tiene las patas de un buey! ¿Alguna vez te ha dado una patada al entrenar?',NULL),
(53565,3,0,'esMX','¡Tiene las patas de un buey! ¿Alguna vez te ha dado una patada al entrenar?',NULL),
(53565,3,0,'frFR','Il a des jambes solides comme le roc ! Il t’a déjà donné un coup de pied pendant l’entraînement ?',NULL),
(53565,3,0,'koKR','녀석은 다리가 황소 다리야! 대련할 때 걷어차인 적 있어?',NULL),
(53565,3,0,'zhCN','他的腿像牛一样有力！你在训练时被他踢到过吗？',NULL),
(53565,3,0,'zhTW','他的腿壯得跟條牛一樣!你有在訓練裡被他踢過嗎?',NULL),
(53565,5,0,'deDE','Da irrst du dich, Freund. Zhou ist so stämmig wie eine Eiche.',NULL),
(53565,5,0,'esES','Ahí es donde te equivocas. Zhou está como un roble.',NULL),
(53565,5,0,'esMX','Ahí es donde te equivocas. Zhou está como un roble.',NULL),
(53565,5,0,'frFR','C’est là que tu fais erreur, mon ami. Zhou est aussi robuste que le chêne.',NULL),
(53565,5,0,'koKR','그건 네 착각이지. 조우는 떡갈나무처럼 튼튼하다고.',NULL),
(53565,5,0,'zhCN','你这就错了，朋友。周就如橡树一般坚韧不拔。',NULL),
(53565,5,0,'zhTW','那你就錯了，朋友。老周結實得像棵老橡樹。',NULL),
(53565,6,0,'deDE','Zhou hat die Ausdauer von drei Männern und kann so die meisten seiner Gegner überdauern.',NULL),
(53565,6,0,'esES','Zhou posee el aguante de tres hombres, por lo que resiste más que casi todos sus oponentes.',NULL),
(53565,6,0,'esMX','Zhou posee el aguante de tres hombres, por lo que resiste más que casi todos sus oponentes.',NULL),
(53565,6,0,'frFR','Zhou a l’endurance de trois pandarens, il peut venir à bout de la plupart des adversaires.',NULL),
(53565,6,0,'koKR','조우는 체력이 세 사람분이야. 웬만한 적은 상대가 안 된다고.',NULL),
(53565,6,0,'zhCN','周的耐力比得上三个普通人，所以他能打败大部分的对手。',NULL),
(53565,6,0,'zhTW','老周的耐力是普通人的三倍，所以他能比大部分的對手都持久。',NULL),
(53565,7,0,'deDE','Vier Kupfer auf Zhou.',NULL),
(53565,7,0,'esES','Cuatro monedas de cobre para Zhou.',NULL),
