(53565,7,0,'zhCN','我押周，四个铜板。',NULL),
(53565,7,0,'zhTW','四枚銅幣賭老周贏。',NULL),
(54015,0,0,'deDE','Was haben wir da - Besucher unseres Königreichs in den Feuerlanden?',NULL),
(54015,0,0,'esES','¿Qué tenemos aquí? Visitantes en nuestro reino de las Tierras de Fuego.',NULL),
(54015,0,0,'esMX','¿Qué tenemos aquí? Visitantes en nuestro reino de las Tierras de Fuego.',NULL),
(54015,0,0,'frFR','Qu\'est-ce que c\'est… Des visiteurs dans notre royaume des terres de Feu ?',NULL),
(54015,0,0,'koKR','이게 누구신가? 우리 불의 땅에 손님들이 찾아오셨군.',NULL),
(54015,0,0,'ruRU','Кто тут у нас? В царстве Огненных Просторов гости?',NULL),
(54015,0,0,'zhCN','瞧瞧谁来了，这火焰的王国有访客了？',NULL),
(54015,0,0,'zhTW','看看這裡...我們火源之界的王國居然來了訪客?',NULL),
(54015,1,0,'deDE','Ihr Sterblichen erinnert Euch vielleicht an Alysra, die mir auf dem Hyjal die Freiheit brachte. Auch sie wurde wiedergeboren... aus Flammen!',NULL),
(54015,1,0,'esES','Vosotros, mortales, quizá recordéis a Alysra, la que me liberó en el Monte Hyjal. Ella también ha renacido... ¡Renacido de las llamas!',NULL),
(54015,1,0,'esMX','Ustedes, mortales, quizás recuerden a Alysra, la que me liberó en el Monte Hyjal. Ella también ha renacido... ¡Renacido de las llamas!',NULL),
(54015,1,0,'frFR','Vous vous souvenez peut-être d\'Alysra, mortels. Elle m\'avait rendu ma liberté au mont Hyjal. Elle aussi a eu sa renaissance… dans les flammes !',NULL),
(54015,1,0,'koKR','알리스라를 기억할지 모르겠군. 하이잘 산에서 나를 풀어 줬지. 그녀도 다시 태어났다... 화염의 존재로!',NULL),
(54015,1,0,'ruRU','Вы помните Алисру? Я обязан ей своей свободой! Она тоже возродилась... Возродилась в огне!',NULL),
(54015,1,0,'zhCN','凡人们，你们也许还记得奥利瑟拉，在海加尔山释放过我的绿龙。她也在烈焰中……得到了重生！',NULL),
(54015,1,0,'zhTW','你們凡人還記得艾里絲拉吧?是她在海加爾山救我出來的。她，同樣的，也已在火焰中重生了!',NULL),
(54015,2,0,'deDE','Ich würde gern zusehen, wie sie Euer armseliges Grüppchen einäschert, doch ich werde anderswo gebraucht. Lebt wohl!',NULL),
(54015,2,0,'esES','Ojalá pudiera quedarme a ver cómo reduce vuestra patética banda a cenizas, pero me necesitan en otro sitio. ¡Adiós!',NULL),
(54015,2,0,'esMX','Ojalá pudiera quedarme a ver cómo reduce su patética banda a cenizas, pero me necesitan en otro sitio. ¡Adiós!',NULL),
(54015,2,0,'frFR','Elle est belle, non ? J\'aimerais la voir réduire votre pitoyable groupe en cendres, mais je suis attendu ailleurs. Adieu !',NULL),
(54015,2,0,'koKR','그녀가 너희를 잿더미로 만드는 모습을 지켜보고 싶지만, 급히 갈 곳이 있어서 말이야. 잘 있으라고!',NULL),
(54015,2,0,'ruRU','Хотел бы я посмотреть, как она превратит вас в жалкую кучку пепла, но меня ждут другие дела. Прощайте!',NULL),
(54015,2,0,'zhCN','我真希望能亲眼看着她将你们这群可怜的家伙烧成灰烬，但我还有别的事情要忙。永别了！',NULL),
(54015,2,0,'zhTW','我也想目睹你們這些可悲的蟲子化為灰燼，但別處還需要我。再會了!',NULL),
(55267,0,0,'deDE','Ich habe versucht, einem Jademonster einen Kopftritt zu verpassen, aber ich habe mir dabei die Tatze wehgetan',NULL),
(55267,0,0,'esES','Intenté darle un sopapo a un monstruo de jade en la cabeza, pero me hice daño en la zarpa.',NULL),
(55267,0,0,'esMX','Intenté darle un sopapo a un monstruo de jade en la cabeza, pero me hice daño en la zarpa.',NULL),
(55267,0,0,'frFR','J’ai voulu donner un coup de pied dans une statue de jade, mais je me suis fait mal à la patte.',NULL),
(55267,0,0,'koKR','비취 괴물 머리를 한 대 차 줬는데, 제 발만 아팠어요.',NULL),
(55267,0,0,'ruRU','Я пытался ударить нефритовое чудовище по голове, но только лапу поранил.',NULL),
(55267,0,0,'zhCN','我想要踢碎一只玉石怪物的脑袋，结果却把爪子弄伤了。',NULL),
(55267,0,0,'zhTW','我用力踢翠玉獸的腦袋，結果反而害我的腳掌受傷了。',NULL),
