(55267,0,1,'esES','¡Gracias por salvarme!',NULL),
(55267,0,1,'esMX','¡Gracias por salvarme!',NULL),
(55267,0,1,'zhCN','谢谢你救了我！',NULL),
(55267,0,2,'deDE','Es war An! Sie hat Shin herausgefordert, an die Tür der Jadehexe zu klopfen!',NULL),
(55267,0,2,'esES','¡Fue An! Se apostó que Shin no se atrevería a llamar a la puerta de la Bruja de Jade.',NULL),
(55267,0,2,'esMX','¡Fue An! Se apostó que Shin no se atrevería a llamar a la puerta de la Bruja de Jade.',NULL),
(55267,0,2,'frFR','C’est An ! Elle a dit à Shin qu’il serait pas cap de frapper à la porte de la sorcière de jade !',NULL),
(55267,0,2,'koKR','안이 그랬어요! 신한테 겁쟁이라고 놀리면서, 옥의 마녀네 문을 두드리라고 했어요.',NULL),
(55267,0,2,'ruRU','Это все Ань! Это она подбила Шина постучать в дверь дома Нефритовой ведьмы.',NULL),
(55267,0,2,'zhCN','都是安的错！是她怂恿阿信去敲青玉巫婆的大门的。',NULL),
(55267,0,2,'zhTW','是安!是她賭小新不敢去敲玉巫婆的門。',NULL),
