(55832,0,0,'deDE','13 gyromantische Destabilisierer? Da. 10 gnumatische Verbindungsgriffe? Auch da. Jetzt muss ich nur noch meinen Lieblingsschraubenschlüssel finden.',NULL),
(55832,0,0,'esES','¿13 desestabilizadores girománticos? Sí. ¿10 agarrativos gnumáticos? Sí. Ya solo me falta encontrar mi llave inglesa favorita...',NULL),
(55832,0,0,'esMX','¿13 desestabilizadores girománticos? Sí. ¿10 agarrativos gnumáticos? Sí. Ya solo me falta encontrar mi llave inglesa favorita...',NULL),
(55832,0,0,'frFR','Treize déstabilisateurs gyromantiques ? OK. Dix cosmographeurs huilés ? OK. Bon. Où ai-je mis ma clé préférée ?',NULL),
(55832,0,0,'koKR','회전식 불안정화 장치 13개... 있고. 공기역학 테두리잡이 10개... 있고. 근데 내가 제일 좋아하는 스패너가 어디 있지?',NULL),
(55832,0,0,'zhCN','十三个螺旋分离器？没错。十个电动轴节钳？没错。我那把专用扳手上哪儿去了？',NULL),
(55832,0,0,'zhTW','13個旋軸反穩定器?確認。10個合金握柄?確認。我把我最愛的扳手放哪去了?',NULL),
(55832,0,1,'deDE','Hmm. Nur 2 Tonnen Sprengstoff für diese Mission? Ich glaube nicht, dass das reicht. Es scheint die Art Mission zu sein, für die wir viel mehr Sprengstoff benötigen. Goblinischen Pyromanensprengstoff, zum Beispiel.',NULL),
(55832,0,1,'esES','Mmm. ¿Solo dos toneladas de explosivos para esta misión? Es poco para mi gusto. Me da que esta misión es del tipo que exige muchos más explosivos... Estoy hablando del nivel de un goblin pirómano.',NULL),
(55832,0,1,'esMX','Mmm. ¿Solo dos toneladas de explosivos para esta misión? Es poco para mi gusto. Me da que esta misión es del tipo que exige muchos más explosivos... Estoy hablando del nivel de un goblin pirómano.',NULL),
(55832,0,1,'frFR','Hmm. Seulement deux tonnes d’explosifs pour cette mission ? Ça me semble un peu léger. C’est le genre de mission, pour laquelle nous allons avoir besoin de beaucoup plus d’explosifs que ça. Genre... des explosifs de pyromane gobelin !',NULL),
(55832,0,1,'koKR','이 임무에 폭발물 고작 2톤이라고? 제 생각엔 좀 모자랄 것 같은데요. 이런 임무엔 폭발물이 그보단 훨씬 많이 필요하거든요. 고블린 방화광 폭탄 같은 걸로요.',NULL),
(55832,0,1,'zhCN','呃。执行这任务才有两吨炸药？分量不够啊。完成这种使命光靠这么点儿炸药怎么行。起码得请……地精纵火型炸药出马。',NULL),
(55832,0,1,'zhTW','嗯嗯。這任務只有配給2噸的炸藥?我覺得似乎不太夠。這任務所需的炸藥應該要多更多。像是...哥布林縱火狂炸藥。',NULL),
(55832,0,2,'deDE','Nur dreißig Gyrokopter? Wir werden noch viel mehr benötigen, bevor diese Sache ausgestanden ist.',NULL),
(55832,0,2,'esES','¿Solo treinta girocópteros? Nos van a hacer falta muchos más.',NULL),
(55832,0,2,'esMX','¿Solo treinta girocópteros? Nos van a hacer falta muchos más.',NULL),
(55832,0,2,'frFR','Seulement trente gyrocoptères ? Nous en aurons besoin de bien plus avant que tout ça soit terminé.',NULL),
(55832,0,2,'koKR','자이로콥터가 고작 30대라고요? 이번 임무를 제대로 마치려면 그보다는 훨씬 많이 있어야 할 텐데.',NULL),
(55832,0,2,'zhCN','才三十台旋翼机？要想顺利完成任务，还需要许多许多台。',NULL),
(55832,0,2,'zhTW','只有三十架旋翼機?我們在這場戰鬥結束前還需要比這還多上許多的旋翼機。',NULL),
