(62377,3,0,'deDE','Nicht aufhören! Wässert die Zuckerrüben!',NULL),
(62377,3,0,'esES','¡No dejes de moverte! ¡Riega esas remolachas dulces!',NULL),
(62377,3,0,'esMX','¡No dejes de moverte! ¡Riega esas remolachas dulces!',NULL),
(62377,3,0,'frFR','Ne vous arrêtez pas ! Arrosez-moi ces betteraves à sucre !',NULL),
(62377,3,0,'koKR','멈추지 마시고요! 저 사탕무에 물을 주세요!',NULL),
(62377,3,0,'ruRU','Не стой столбом! Полей сахарную свеклу!',NULL),
(62377,3,0,'zhCN','别停！给那些甜菜浇水！',NULL),
(62377,3,0,'zhTW','別停下腳步!去幫甜菜澆水!',NULL),
(62377,4,0,'deDE','Wässert auch meine Melonen! Sie befinden sich weiter den Pfad entlang.',NULL),
(62377,4,0,'esES','¡Vete a regar mis melones enormes, por allí en el camino!',NULL),
(62377,4,0,'esMX','¡Vete a regar mis melones enormes, por allí en el camino!',NULL),
(62377,4,0,'frFR','Allez arroser mes melons énormes, plus loin dans l’allée !',NULL),
(62377,4,0,'koKR','밭 안쪽에 있는 커다란 멜론에 물을 주세요!',NULL),
(62377,4,0,'ruRU','Там дальше растут крупные дыни! Полей их!',NULL),
(62377,4,0,'zhCN','去给我巨大的甜瓜浇水，沿着这条路往下再就是！',NULL),
(62377,4,0,'zhTW','去幫巨型甜瓜澆水，就在路的另一邊!',NULL),
(62377,5,0,'deDE','Nur weiter! Ich möchte, dass Ihr jetzt meinen Rotblattsalat wässert!',NULL),
(62377,5,0,'esES','¡Sigue así! ¡Ahora riega mis lechugas de hoja roja!',NULL),
(62377,5,0,'esMX','¡Sigue así! ¡Ahora riega mis lechugas de hoja roja!',NULL),
(62377,5,0,'frFR','Continuez comme ça ! Maintenant, arrosez ma laitue à feuilles rouges !',NULL),
(62377,5,0,'koKR','계속하세요! 이제 붉은잎 양상추에 물을 주세요!',NULL),
(62377,5,0,'ruRU','Не останавливайся! Теперь полей краснолистовой салат-латук!',NULL),
(62377,5,0,'zhCN','继续！现在给我的红叶莴苣浇水！',NULL),
(62377,5,0,'zhTW','保持下去!現在去幫紅葉萵苣澆水!',NULL),
(62377,6,0,'deDE','Es scheint, meine Zuckerrüben brauchen noch mehr Wasser! Dreht um!',NULL),
(62377,6,0,'esES','¡Parece que mis remolachas dulces necesitan más agua! ¡Vuelve atrás!',NULL),
(62377,6,0,'esMX','¡Parece que mis remolachas dulces necesitan más agua! ¡Vuelve atrás!',NULL),
(62377,6,0,'frFR','On dirait que mes betteraves sucrières ont besoin de plus d’eau ! Revenez !',NULL),
(62377,6,0,'koKR','사탕무에 물을 더 줘야 할 것 같아요! 다시 돌아가세요!',NULL),
(62377,6,0,'ruRU','Поворачивай обратно! Сахарной свекле нужно больше воды!',NULL),
(62377,6,0,'zhCN','看起来给我的甜菜浇的水还不够！赶快回去！',NULL),
(62377,6,0,'zhTW','看來我的甜菜需要更多水!快回頭!',NULL),
(62377,7,0,'zhTW','住手!',NULL),
(63307,0,0,'deDE','Ich habe alles, was ich brauche. Schnell, gehen wir weiter bevor sie zurückkehren!',NULL),
(63307,0,0,'esES','Tengo todo lo necesario. Rápido, ¡vámonos antes de que vuelvan!',NULL),
(63307,0,0,'esMX','Tengo todo lo necesario. Rápido, ¡vámonos antes de que vuelvan!',NULL),
(63307,0,0,'frFR','J’ai tout ce qu’il me faut. Vite, poursuivons notre chemin avant qu’ils ne reviennent !',NULL),
(63307,0,0,'koKR','이제 필요한 건 모두 챙겼네. 어서, 저들이 돌아오기 전에 피하세!',NULL),
(63307,0,0,'ruRU','Все готово. Быстрее, идем, пока они не вернулись!',NULL),
(63307,0,0,'zhCN','好了。快，我们得在他们回来之前继续前进。',NULL),
(63307,0,0,'zhTW','我已經準備好了。快，趁他們回來前快走吧!',NULL),
(63307,1,0,'deDE','Genug der Pandarengeschichte. Lasst uns über Euer Volk sprechen.',NULL),
(63307,1,0,'esES','Pero ya basta de historia pandaren. Hablemos un poco sobre tu gente.',NULL),
(63307,1,0,'esMX','Pero ya basta de historia pandaren. Hablemos un poco sobre tu gente.',NULL),
(63307,1,0,'frFR','Assez d\'histoire pandarène, parlons un peu de votre propre peuple.',NULL),
(63307,1,0,'koKR','판다렌의 역사는 이 정도로 끝내지. 이제 자네 얘기를 하세.',NULL),
(63307,1,0,'ruRU','Но хватит об истории пандаренов. Поговорим лучше о твоем народе.',NULL),
(63307,1,0,'zhCN','熊猫人的历史就说到这儿吧。谈谈你的种族，旅行者。',NULL),
(63307,1,0,'zhTW','聽夠熊貓人的歷史了。跟我說說你們的種族吧，旅行者。',NULL),
(63307,2,0,'deDE','Ich habe bereits viel gelernt, indem ich Euch beobachtet habe. Ihr kämpft mit dem Eifer der Jugend, aber der Erfahrung eines routinierten Kämpfers. Ihr habt Euer Leben mit der Kriegskunst verbracht, habe ich recht?',NULL),
(63307,2,0,'esES','He aprendido mucho solo con verte en acción. Luchas con el fervor de la juventud, pero también con la experiencia de un aguerrido veterano. La guerra ha ocupado toda tu vida, ¿verdad?',NULL),
(63307,2,0,'esMX','He aprendido mucho solo con verte en acción. Luchas con el fervor de la juventud, pero también con la experiencia de un aguerrido veterano. La guerra ha ocupado toda tu vida, ¿verdad?',NULL),
(63307,2,0,'frFR','J\'ai déjà beaucoup appris, simplement en vous voyant agir. Vous combattez avec la ferveur de la jeunesse mais avec l\'expérience d\'un vétéran, comme si vous aviez connu la guerre pendant l\'essentiel de votre existence. N’est-ce pas ?',NULL),
(63307,2,0,'koKR','자네 행동을 보면서 이미 많은 것을 알았네. 자네에게선 젊은이의 열정과 노병의 경험이 함께 보이더군. 일생 동안 전장에서 살았겠지?',NULL),
(63307,2,0,'ruRU','Я многое понял, просто наблюдая за тем, что ты делаешь. Ты сражаешься с юношеским пылом, но в то же время с уверенностью опытного воина. Тебе пришлось повидать много сражений на своем веку?',NULL),
(63307,2,0,'zhCN','仅仅观察你的动作，我已获益良多。你的招式既充满年轻人的热忱，又有老手的稳健。想必你是久经沙场了吧？',NULL),
(63307,2,0,'zhTW','我看著你的舉動已經了解到很多。你用年輕人的狂熱戰鬥，但擁有老兵的經驗。想必你一生都在戰鬥，對吧?',NULL),
(63307,3,0,'deDE','Ah, dies ist ein besonderer Ort. Meine Urgroßeltern nannten diesen Teil des Waldes ihre Heimat. Kommt, es wird nur einen Moment dauern.',NULL),
(63307,3,0,'esES','Ah, este es un lugar especial. Esta parte del bosque era el hogar de mis bisabuelos. Ven, solo será un momento.',NULL),
(63307,3,0,'esMX','Ah, este es un lugar especial. Esta parte del bosque era el hogar de mis bisabuelos. Ven, solo tardaremos un instante.',NULL),
(63307,3,0,'frFR','Ah, nous sommes dans un lieu particulier. Mes arrière-grands-parents considéraient cette partie de la forêt comme leur foyer. Venez, ça ne prendra qu\'un instant.',NULL),
(63307,3,0,'koKR','아, 여긴 특별한 장소라네. 우리 증조부, 증조모께서는 이 숲을 집이라고 부르셨네. 이리 오게. 잠깐이면 되네.',NULL),
(63307,3,0,'ruRU','О, это особенное место. Мои далекие предки считали эту часть леса своим домом. Идем. Это не займет много времени.',NULL),
(63307,3,0,'zhCN','啊，这是个特别的地方。我的祖辈们曾把这片林子当做家。来吧，我们很快就好。',NULL),
(63307,3,0,'zhTW','啊，這是個特別的地方。我的上上一代在森林的這一帶定居。來吧，這只要耽擱一下子。',NULL),
(63307,4,0,'deDE','Wir Pandaren vergöttern unsere Vorfahren nicht, aber wir ehren die Erinnerung an sie und die Weisheit, die sie an uns weitergegeben haben.',NULL),
(63307,4,0,'esES','Los pandaren no adoramos a nuestros ancestros, pero veneramos su memoria y la sabiduría que nos han transmitido.',NULL),
(63307,4,0,'esMX','Los pandaren no adoramos a nuestros ancestros, pero veneramos su memoria y la sabiduría que nos han transmitido.',NULL),
(63307,4,0,'frFR','Nous autres pandarens ne vénérons pas nos ancêtres, mais nous respectons leur mémoire et la sagesse qu\'ils nous ont léguée.',NULL),
(63307,4,0,'koKR','우리 판다렌은 조상을 숭배하지 않네. 하지만 그분들이 우리에게 물려주신 기억과 지혜를 존중하지.',NULL),
(63307,4,0,'ruRU','Мы, пандарены, не поклоняемся своим предкам, но мы чтим память о них и дорожим той мудростью, которую они передали нам.',NULL),
(63307,4,0,'zhCN','我们熊猫人并不崇拜祖先，不过我们尊崇他们传承下来的记忆和智慧。',NULL),
(63307,4,0,'zhTW','我們熊貓人不崇拜祖先。但是，我們尊重關於他們的記憶，及他們流傳下來的智慧。',NULL),
(63307,5,0,'deDE','Es war mein Urgroßvater, der mir zuerst die Geschichte der Mogu erzählte, die Ihr kürzlich von mir gehört habt.',NULL),
(63307,5,0,'esES','Fue mi bisabuelo el que me contó la historia de los mogu que te relaté antes.',NULL),
(63307,5,0,'esMX','Fue mi bisabuelo el que me contó la historia de los mogu que te relaté antes.',NULL),
(63307,5,0,'frFR','C\'est mon arrière-grand-père qui m\'a raconté pour la première fois l\'histoire des mogu dont je vous faisais part tout à l\'heure.',NULL),
(63307,5,0,'koKR','얼마 전에 들려줬던 모구 이야기는, 바로 우리 증조부께서 내게 알려주신 거네.',NULL),
(63307,5,0,'ruRU','Впервые я услышал историю могу, которую недавно пересказал тебе, от своего прадеда.',NULL),
(63307,5,0,'zhCN','我刚才与你分享的魔古族传说，最早是我曾祖父讲给我听的。',NULL),
(63307,5,0,'zhTW','我剛跟你說的，關於魔古的歷史，是我的曾曾祖父告訴我的。',NULL),
(64389,0,0,'deDE','Mmmmm! Ich rieche ein köstliches Schaf!',NULL),
(64389,0,0,'esES','¡Mmm! ¡Huele a oveja deliciosa!',NULL),
(64389,0,0,'esMX','¡Mmm! ¡Huele a oveja deliciosa!',NULL),
(64389,0,0,'frFR','Miaaaam ! Y’a comme une bonne odeur de mouton !',NULL),
(64389,0,0,'koKR','으음! 맛있는 양 냄새가 나는데!',NULL),
(64389,0,0,'ruRU','М-м-м! Чувствую чудесный запах барашка!',NULL),
(64389,0,0,'zhCN','呒！我闻到羊肉的香味！',NULL),
(64389,0,0,'zhTW','嗯...!我聞到一隻美味的綿羊!',NULL),
(64389,1,0,'deDE','Zeit, sich ein leckeres Schaf zu gönnen!',NULL),
(64389,1,0,'esES','¡Vamos a degustar un poco de añojo!',NULL),
(64389,1,0,'esMX','¡Vamos a degustar un poco de añojo!',NULL),
(64389,1,0,'frFR','C’est l’heure de croquer du mouton !',NULL),
(64389,1,0,'koKR','양고기로 군것질해야지!',NULL),
(64389,1,0,'ruRU','Пора отведать баранинки!',NULL),
(64389,1,0,'zhCN','对羊肉大快朵颐的时候到了！',NULL),
(64389,1,0,'zhTW','大口吃羊的時候到了!',NULL),
(64881,0,0,'deDE','Warum verstehe ich kein einziges Wort?',NULL),
(64881,0,0,'esES','¿Por qué no puedo entender una sola palabra?',NULL),
(64881,0,0,'esMX','¿Por qué no puedo entender una sola palabra?',NULL),
(64881,0,0,'frFR','Pourquoi je ne comprends pas les paroles ?',NULL),
(64881,0,0,'koKR','저는 한 마디도 이해가 안 되는데요.',NULL),
(64881,0,0,'zhCN','我怎么一句都听不懂？',NULL),
(64881,0,0,'zhTW','為什麼我連一個字都不懂?',NULL),
(64881,1,0,'deDE','Wir leben auf dem Rücken einer Riesenschildkröte?!',NULL),
(64881,1,0,'esES','¡¿Vivimos a lomos de una tortuga gigante?!',NULL),
(64881,1,0,'esMX','¡¿Vivimos a lomos de una tortuga gigante?!',NULL),
(64881,1,0,'frFR','On vit sur une grosse tortue ?',NULL),
(64881,1,0,'koKR','우리가 커다란 거북이 등에 산다고요?!',NULL),
(64881,1,0,'zhCN','我们住在一只巨龟的背上？！',NULL),
(64881,1,0,'zhTW','我們住在一隻大烏龜的背上?!',NULL),
(64881,2,0,'deDE','Ich fand es schon etwas komisch, dass die Berge Flossen haben!',NULL),
(64881,2,0,'esES','Es verdad que me sorprendía que las montañas tuvieran aletas...',NULL),
(64881,2,0,'esMX','Es verdad que me sorprendía que las montañas tuvieran aletas...',NULL),
(64881,2,0,'frFR','Des montagnes avec des nageoires, je trouvais ça bizarre !',NULL),
(64881,2,0,'koKR','어쩐지 산에 지느러미발이 달려 있는 게 이상하다 했어!',NULL),
(64881,2,0,'zhCN','我刚还觉得纳闷呢，怎么山峰会长蹼！',NULL),
(64881,2,0,'zhTW','我就覺得奇怪，山怎麼會有鰭!',NULL),
(64881,3,0,'deDE','Weiß die Schildkröte denn, dass wir hier sind?',NULL),
(64881,3,0,'esES','¿Y la tortuga sabe que estamos aquí?',NULL),
(64881,3,0,'esMX','¿Y la tortuga sabe que estamos aquí?',NULL),
(64881,3,0,'frFR','Est-ce que la tortue sait qu\'on est là ?',NULL),
(64881,3,0,'koKR','우리가 여기 사는 걸 거북이도 알아요?',NULL),
(64881,3,0,'zhCN','海龟知道我们在这儿吗？',NULL),
(64881,3,0,'zhTW','這烏龜知道我們在這裡嗎?',NULL),
(64881,4,0,'zhCN','嘿！',NULL),
(64881,4,0,'zhTW','嘿!',NULL),
(64881,5,0,'deDE','Ja, Ihr solltet alle mehr wie ich sein.',NULL),
(64881,5,0,'esES','Sí, todos deberíais ser como yo.',NULL),
(64881,5,0,'esMX','Sí, todos deberían ser como yo.',NULL),
(64881,5,0,'frFR','C\'est vrai, vous devriez tous être comme moi.',NULL),
(64881,5,0,'koKR','맞아, 너희 다 나를 닮아야 돼.',NULL),
(64881,5,0,'zhCN','对，你们都该跟我学学。',NULL),
(64881,5,0,'zhTW','沒錯，你們都應該多學學我。',NULL),
(64881,6,0,'deDE','Bedeutet das, dass unsere Mütter, Väter und Großeltern auch alle Erforscher waren?',NULL),
(64881,6,0,'esES','¿Eso quiere decir que nuestros papás y mamás y abuelos eran todos exploradores?',NULL),
(64881,6,0,'esMX','¿Eso quiere decir que nuestros papás y mamás y abuelos eran todos exploradores?',NULL),
(64881,6,0,'frFR','Ça veut dire que nos papas et nos grands-papas ils étaient des explorateurs aussi ?',NULL),
(64881,6,0,'koKR','그러면 우리 엄마, 아빠랑 할머니, 할아버지가 다 탐험가였단 말이에요?',NULL),
(64881,6,0,'zhCN','那是不是说，我们的爸爸妈妈爷爷奶奶也都是探险者？',NULL),
(64881,6,0,'zhTW','那代表我們的爸爸媽媽，還有爺爺奶奶全都是探險家嗎?',NULL),
(64881,7,0,'deDE','Ich will die Welt erkunden!',NULL),
(64881,7,0,'esES','¡Yo quiero explorar el mundo!',NULL),
(64881,7,0,'esMX','¡Yo quiero explorar el mundo!',NULL),
(64881,7,0,'frFR','Je veux explorer le monde !',NULL),
(64881,7,0,'koKR','나도 세상을 탐험하고 싶어!',NULL),
(64881,7,0,'zhCN','我想要探索世界！',NULL),
(64881,7,0,'zhTW','我想要探索世界!',NULL),
(64881,8,0,'deDE','Oh. Na, dann... vergesst es.',NULL),
(64881,8,0,'esES','Ah. Bueno, entonces déjalo.',NULL),
(64881,8,0,'esMX','Ah. Bueno, entonces déjalo.',NULL),
(64881,8,0,'frFR','Ah. Ah ben laissez tomber, alors.',NULL),
(64881,8,0,'koKR','그래? 그럼 안 할래.',NULL),
(64881,8,0,'zhCN','噢。好吧，当我没说过。',NULL),
(64881,8,0,'zhTW','喔。好吧，算了。',NULL),
(64881,9,0,'esES','¿Qué?',NULL),
(64881,9,0,'esMX','¿Qué?',NULL),
(64881,10,0,'deDE','Das ist in-möglich!',NULL),
(64881,10,0,'esES','¡Eso es imposible!',NULL),
(64881,10,0,'esMX','¡Eso es imposible!',NULL),
(64881,10,0,'frFR','Mais c\'est pas possible !',NULL),
(64881,10,0,'koKR','그건 안가능해요!',NULL),
(64881,10,0,'zhCN','那不可能！',NULL),
(64881,10,0,'zhTW','那不可能!',NULL),
(67260,0,0,'deDE','Und jetzt in der Arena: $n, $gein:eine:r; $R, und zwar $gein:eine:c; $C ersten Ranges! $n ist ziemlich neu hier, behandelt $gihn:sie; also schonend!','Und jetzt in der Arena: $n, $gein:eine:r; $R, und zwar $gein:eine:c; $C ersten Ranges! $n ist ziemlich neu hier, behandelt $gihn:sie; also schonend!'),
(67260,0,0,'esES','Y ahora entra en la arena $gun:una; $r $c de rango 1... ¡$n! $n acaba de empezar, ¡así que tened paciencia!','Y ahora entra en la arena $gun:una; $r $c de rango 1... ¡$n! $n acaba de empezar, ¡así que tened paciencia!'),
(67260,0,0,'esMX','Y ahora entra en la arena $gun:una; $r $c de rango 1... ¡$n! $n acaba de empezar, ¡así que tengan paciencia!','Y ahora entra en la arena $gun:una; $r $c de rango 1... ¡$n! $n acaba de empezar, ¡así que tengan paciencia!'),
(67260,0,0,'frFR','Et voici maintenant qui pénètre dans l’arène : $n, $gun:une:r; $r $c de rang 1 ! $n est $gnouveau:nouvelle; ici, alors allez-y mollo !','Et voici maintenant qui pénètre dans l’arène : $n, $gun:une:r; $r $c de rang 1 ! $n est $gnouveau:nouvelle; ici, alors allez-y mollo !'),
(67260,0,0,'koKR','투기장에 들어서는 건... 1계급 $r $c인 $n입니다! $n|1은;는; 여기 새로 온 친구니까, 살살 해봐요!','투기장에 들어서는 건... 1계급 $r $c인 $n입니다! $n|1은;는; 여기 새로 온 친구니까, 살살 해봐요!'),
(67260,0,0,'ruRU','На арене появляется |3-6($r)-|3-6($c) по имени $n, $gнаш новый участник:наша новая участница; 1-го ранга! $gОн:Она; здесь пока новичок, так что полегче!','На арене появляется |3-6($r)-|3-6($c) по имени $n, $gнаш новый участник:наша новая участница; 1-го ранга! $gОн:Она; здесь пока новичок, так что полегче!'),
