(67260,37,1,'zhCN','很好很好！$n获胜！看来我要欠某人一些钱了。','很好很好！$n获胜！看来我要欠某人一些钱了。'),
(67260,37,1,'zhTW','非常好!$n獲勝!看來我欠別人的賭債變多了。','非常好!$n獲勝!看來我欠別人的賭債變多了。'),
(67260,37,2,'deDE','Glückwunsch, $n! Bitte hinterlasst keine blutigen Fußspuren außerhalb der Arena.','Glückwunsch, $n! Bitte hinterlasst keine blutigen Fußspuren außerhalb der Arena.'),
(67260,37,2,'esES','¡Felicidades, $n! Intenta no dejar huellas de sangre fuera de la arena.','¡Felicidades, $n! Intenta no dejar huellas de sangre fuera de la arena.'),
(67260,37,2,'esMX','¡Felicidades, $n! Intenta no dejar huellas de sangre fuera de la arena.','¡Felicidades, $n! Intenta no dejar huellas de sangre fuera de la arena.'),
(67260,37,2,'frFR','Félicitations, $n ! Essayez de ne pas mettre du sang partout en sortant de l’arène.','Félicitations, $n ! Essayez de ne pas mettre du sang partout en sortant de l’arène.'),
(67260,37,2,'koKR','축하합니다, $n! 거기 투기장 밖에 피투성이 발자국은 남기지 마세요.','축하합니다, $n! 거기 투기장 밖에 피투성이 발자국은 남기지 마세요.'),
(67260,37,2,'ruRU','Мои поздравления, $n! Постарайся не оставлять за пределами арены кровавых следов.','Мои поздравления, $n! Постарайся не оставлять за пределами арены кровавых следов.'),
(67260,37,2,'zhCN','祝贺你，$n！请不要在场外留下血脚印。','祝贺你，$n！请不要在场外留下血脚印。'),
(67260,37,2,'zhTW','恭喜，$n!請不要把沾了血跡的腳印留在競技場外。','恭喜，$n!請不要把沾了血跡的腳印留在競技場外。'),
(67260,37,3,'deDE','Das offizielle Ergebnis ist da: $n hat es geschafft, nicht zu sterben. Das habt Ihr großartig gemacht, $n!','Das offizielle Ergebnis ist da: $n hat es geschafft, nicht zu sterben. Das habt Ihr großartig gemacht, $n!'),
(67260,37,3,'esES','¡Ya es oficial! $n ha conseguido no morir. ¡Buen trabajo, $n!','¡Ya es oficial! $n ha conseguido no morir. ¡Buen trabajo, $n!'),
(67260,37,3,'esMX','¡Ya es oficial! $n ha conseguido no morir. ¡Buen trabajo, $n!','¡Ya es oficial! $n ha conseguido no morir. ¡Buen trabajo, $n!'),
(67260,37,3,'frFR','C’est officiel ! $n a réussi à ne pas mourir. Bravo, $n !','C’est officiel ! $n a réussi à ne pas mourir. Bravo, $n !'),
(67260,37,3,'koKR','끝났습니다! $n|1이;가; 가까스로 살아남았습니다. 정말 아슬아슬했네요, $n!','끝났습니다! $n|1이;가; 가까스로 살아남았습니다. 정말 아슬아슬했네요, $n!'),
(67260,37,3,'ruRU','Официально подтверждаю – |3-2($n) удалось не умереть! Молодчина, что $gостался:осталась; в живых, $n!','Официально подтверждаю – |3-2($n) удалось не умереть! Молодчина, что $gостался:осталась; в живых, $n!'),
(67260,37,3,'zhCN','官方消息！$n活下来了。能活下来就不容易啊，$n！','官方消息！$n活下来了。能活下来就不容易啊，$n！'),
(67260,37,3,'zhTW','動真格了!$n竟然還活著。活著就很了不起，$n!','動真格了!$n竟然還活著。活著就很了不起，$n!'),
(67260,38,0,'deDE','Autsch... tut mir leid, $n. Stellt Euch wieder an und versucht\'s erneut.','Autsch... tut mir leid, $n. Stellt Euch wieder an und versucht\'s erneut.'),
(67260,38,0,'esES','Ay... Lo siento, $n. Ponte a la cola y vuelve a intentarlo.','Ay... Lo siento, $n. Ponte a la cola y vuelve a intentarlo.'),
(67260,38,0,'esMX','Ay... Lo siento, $n. Únete a la cola y vuelve a intentarlo.','Ay... Lo siento, $n. Únete a la cola y vuelve a intentarlo.'),
(67260,38,0,'frFR','Ouille… désolé, $n. Retournez dans la file et retentez votre chance.','Ouille… désolé, $n. Retournez dans la file et retentez votre chance.'),
(67260,38,0,'koKR','아이코... 안됐네요, $n 님. 다시 도전해 보세요. 줄은 다시 서야 해요.','아이코... 안됐네요, $n 님. 다시 도전해 보세요. 줄은 다시 서야 해요.'),
(67260,38,0,'ruRU','Ой... извини, $n. Возвращайся в очередь и попробуй еще раз.','Ой... извини, $n. Возвращайся в очередь и попробуй еще раз.'),
(67260,38,0,'zhCN','哎哟……抱歉，$n。请回去重新排队，再试一次。','哎哟……抱歉，$n。请回去重新排队，再试一次。'),
(67260,38,0,'zhTW','噢...抱歉，$n。回去排好隊再來試一次。','噢...抱歉，$n。回去排好隊再來試一次。'),
(67260,38,1,'deDE','Argh... das sieht nicht so schön aus. Wir bräuchten hier mal einen Priester oder so jemanden in der Art.','Argh... das sieht nicht so schön aus. Wir bräuchten hier mal einen Priester oder so jemanden in der Art.'),
(67260,38,1,'esES','Beeej, qué asco. ¡¿Quiere alguien llamar a un sacerdote o algo así?!','Beeej, qué asco. ¡¿Quiere alguien llamar a un sacerdote o algo así?!'),
(67260,38,1,'esMX','Beeej, qué asco. ¡¿Quiere alguien llamar a un sacerdote o algo así?!','Beeej, qué asco. ¡¿Quiere alguien llamar a un sacerdote o algo así?!'),
(67260,38,1,'frFR','Eurk… quel carnage. J’aurais besoin d’un prêtre ou quelque chose du genre ici, s’il vous plaît !','Eurk… quel carnage. J’aurais besoin d’un prêtre ou quelque chose du genre ici, s’il vous plaît !'),
(67260,38,1,'koKR','우엑... 정말 처참하네요. 누가 사제나 뭐 그런 친구 하나 불러 줄래요?!','우엑... 정말 처참하네요. 누가 사제나 뭐 그런 친구 하나 불러 줄래요?!'),
(67260,38,1,'ruRU','Фуу... Ну и месиво. У нас тут жреца поблизости нет?','Фуу... Ну и месиво. У нас тут жреца поблизости нет?'),
(67260,38,1,'zhCN','呃……真是一团糟。找个牧师之类的来好吗？！','呃……真是一团糟。找个牧师之类的来好吗？！'),
(67260,38,1,'zhTW','噁...搞的亂七八糟的。能不能找個牧師還是什麼的來一下?!','噁...搞的亂七八糟的。能不能找個牧師還是什麼的來一下?!'),
(67260,38,2,'deDE','Das... hat kein gutes Ende gefunden.','Das... hat kein gutes Ende gefunden.'),
(67260,38,2,'esES','Eso... no ha acabado bien.','Eso... no ha acabado bien.'),
(67260,38,2,'esMX','Eso... no ha acabado bien.','Eso... no ha acabado bien.'),
(67260,38,2,'frFR','Ça… ne s’est pas très bien terminé.','Ça… ne s’est pas très bien terminé.'),
(67260,38,2,'koKR','그거 참... 안 좋게 끝났네요.','그거 참... 안 좋게 끝났네요.'),
(67260,38,2,'ruRU','Все закончилось... не очень-то хорошо.','Все закончилось... не очень-то хорошо.'),
