(67267,0,0,'esES','Habla con un guardia si quieres luchar, $c.','Habla con un guardia si quieres luchar, $c.'),
(67267,0,0,'esMX','Habla con un guardia si quieres luchar, $c.','Habla con un guardia si quieres luchar, $c.'),
(67267,0,0,'frFR','Parlez à un garde si vous désirez vous battre, $c.','Parlez à un garde si vous désirez vous battre, $c.'),
(67267,0,0,'koKR','싸움에 참여하고 싶으면 경비병에게 말하게, $c.','싸움에 참여하고 싶으면 경비병에게 말하게, $c.'),
(67267,0,0,'ruRU','Если хочешь сражаться – поговори со стражником, |3-6($c).','Если хочешь сражаться – поговори со стражником, |3-6($c).'),
(67267,0,0,'zhCN','如果你想要参战，就去和守卫聊聊，$c。','如果你想要参战，就去和守卫聊聊，$c。'),
(67267,0,0,'zhTW','想打的話就跟衛兵說一聲，$c。','想打的話就跟衛兵說一聲，$c。'),
(67267,1,0,'deDE','Ihr wollt kämpfen? Dafür braucht Ihr eine Einladung.$b$bIhr dürft allerdings gern zusehen.','Ihr wollt kämpfen? Dafür braucht Ihr eine Einladung.$b$bIhr dürft allerdings gern zusehen.'),
(67267,1,0,'esES','¿Quieres luchar? Te hará falta una invitación.$b$bPero puedes quedarte a mirar.','¿Quieres luchar? Te hará falta una invitación.$b$bPero puedes quedarte a mirar.'),
(67267,1,0,'esMX','¿Quieres luchar? Te hará falta una invitación.$b$bPero puedes quedarte a mirar.','¿Quieres luchar? Te hará falta una invitación.$b$bPero puedes quedarte a mirar.'),
(67267,1,0,'frFR','Vous voulez vous battre ? Pour ça il vous faut une invitation.$b$bMais vous pouvez toujours regarder, ceci dit.','Vous voulez vous battre ? Pour ça il vous faut une invitation.$b$bMais vous pouvez toujours regarder, ceci dit.'),
(67267,1,0,'koKR','싸우고 싶다고? 초대장이 필요하다네.$b$b그래도 관람은 마음대로 할 수 있지.','싸우고 싶다고? 초대장이 필요하다네.$b$b그래도 관람은 마음대로 할 수 있지.'),
(67267,1,0,'ruRU','Хочешь поучаствовать в бою? У тебя должно быть приглашение.$b$bНо посмотреть ты можешь и сейчас.','Хочешь поучаствовать в бою? У тебя должно быть приглашение.$b$bНо посмотреть ты можешь и сейчас.'),
(67267,1,0,'zhCN','你想要参加搏击？你需要先收到一份邀请。$b$b当然，欢迎你留下来观看比赛。','你想要参加搏击？你需要先收到一份邀请。$b$b当然，欢迎你留下来观看比赛。'),
(67267,1,0,'zhTW','你想上場打?你要有邀請函才行。$b$b不過歡迎你當觀眾就是。','你想上場打?你要有邀請函才行。$b$b不過歡迎你當觀眾就是。'),
