(67414,0,0,'esES','Venid todos ahora mismo. Acabemos con eh\'to.',NULL),
(67414,0,0,'esMX','Vengan todos ahora mismo. Acabemos con esto.',NULL),
(67414,0,0,'frFR','Tout le monde il est là. On va en finir maintenant.',NULL),
(67414,0,0,'koKR','다 온 것 같군. 빨리 해치우세.',NULL),
(67414,0,0,'ruRU','Все в сборе. Давайте выполним это поручение.',NULL),
(67414,0,0,'zhCN','大家到齐了。我们开始吧。',NULL),
(67414,0,0,'zhTW','大家都到了。我們趕緊把事情辦好吧。',NULL),
(67414,1,0,'deDE','Ganz, wie dem Kriegshäuptling beliebt...',NULL),
(67414,1,0,'esES','Como ordene el Jefe de Guerra.',NULL),
(67414,1,0,'esMX','Como ordene el Jefe de Guerra.',NULL),
(67414,1,0,'frFR','Si le chef de guerre, c’est ce qu’il veut…',NULL),
(67414,1,0,'koKR','대족장님의 명령이라면...',NULL),
(67414,1,0,'ruRU','Как прикажет вождь...',NULL),
(67414,1,0,'zhCN','如酋长所愿……',NULL),
(67414,1,0,'zhTW','承大酋長之令...',NULL),
(67414,2,0,'deDE','Ich bin froh, dass Ihr hier an meiner Seite seid. Garroshs Schläger gefallen mir gar nicht.',NULL),
(67414,2,0,'esES','Me alegra que me guardéis las eh\'paldas. No me guh\'tan los matones de Garrosh.',NULL),
(67414,2,0,'esMX','Me alegra que estén aquí para vigilarme las espaldas. No me gusta la facha de los matones de Garrosh.',NULL),
(67414,2,0,'frFR','Content que vous couvrez mes arrières. La tête de ces gorilles de Garrosh, elle me revient pas.',NULL),
(67414,2,0,'koKR','자네가 있어 안심이군. 가로쉬의 깡패들은 느낌이 안 좋아.',NULL),
(67414,2,0,'ruRU','Я рад, что вы со мной. Не нравятся мне эти головорезы Гарроша.',NULL),
(67414,2,0,'zhCN','很高兴有你掩护我。我讨厌加尔鲁什的恶棍。',NULL),
(67414,2,0,'zhTW','很高興有你罩我，我不喜歡卡爾洛斯手下的眼神。',NULL),
(67414,3,0,'deDE','Kommt – aufsteigen und losreiten!',NULL),
(67414,3,0,'esES','¡Montemos y salgamos de aquí!',NULL),
(67414,3,0,'esMX','¡Montemos y salgamos de aquí!',NULL),
(67414,3,0,'frFR','En selle et dégageons de là !',NULL),
(67414,3,0,'koKR','자, 올라타 출발하세!',NULL),
