(67414,3,0,'zhCN','我们上马，出发！',NULL),
(67414,3,0,'zhTW','整裝上坐騎，準備出發!',NULL),
(67414,4,0,'deDE','Den Spähern nach gibt es in diesen Höhlen uralte Magie. Der Kriegshäuptling will es genau wissen.',NULL),
(67414,4,0,'esES','Los exploradores dicen que hay magia antigua en eh\'tas cuevas. El Jefe de Guerra quiere inveh\'tigah\'las.',NULL),
(67414,4,0,'esMX','Los exploradores dicen que hay magia antigua en estas cuevas. El Jefe de Guerra quiere investigarlas.',NULL),
(67414,4,0,'frFR','Les éclaireurs, ils disent qu’il y a une vieille magie dans ces grottes. Le chef de guerre il veut qu’on vérifie.',NULL),
(67414,4,0,'koKR','정찰대가 이 동굴 안에 고대의 마법이 있다더군. 대족장이 확인하라고 했네.',NULL),
(67414,4,0,'ruRU','Говорят, в этих пещерах таится древняя магия. Вождь хочет исследовать их.',NULL),
(67414,4,0,'zhCN','斥候说洞穴里有古代魔法。酋长让他们来调查。',NULL),
(67414,4,0,'zhTW','斥候回報說在這洞穴裡有古老的法術。大酋長想要調查一下。',NULL),
(67414,5,0,'deDE','Diese Saurok bewachen die Höhle. Räumen wir sie aus\'m Weg!',NULL),
