(67414,5,0,'ruRU','Пещеру сторожат сауроки. Займемся ими.',NULL),
(67414,5,0,'zhCN','那些蜥蜴人守着洞穴。我们得先对付他们。',NULL),
(67414,5,0,'zhTW','那些薩烏洛克在守護洞穴，我們來對付他們。',NULL),
