(67414,24,0,'frFR','C’est la magie qu’est la plus noire, ça, mec !',NULL),
(67414,24,0,'koKR','이건 마법 중에서도 가장 악한 마법이야!',NULL),
(67414,24,0,'ruRU','Это самая темная из темных магий!',NULL),
(67414,24,0,'zhCN','这是最黑暗的魔法，伙计！',NULL),
(67414,24,0,'zhTW','這一定是最黑暗的魔法了，老兄!',NULL),
(67414,25,0,'deDE','Garrosh will Gott spielen? Monster erschaffen? Das geht gegen die Ideale der Horde!',NULL),
(67414,25,0,'esES','¿Garrosh juega a ser un dios? ¿Crea monh\'truos? ¡Esa no es mi Horda!',NULL),
(67414,25,0,'esMX','¿Garrosh jugando a ser dios? ¿Creando monstruos? ¡Esto no es propio de la Horda!',NULL),
(67414,25,0,'frFR','Garrosh il veut jouer les dieux ? Créer des monstres ? C’est pas pour ça que la Horde elle existe !',NULL),
(67414,25,0,'koKR','가로쉬가 신의 흉내를 내서 괴물을 만든다고? 그런 건 호드가 아니야!',NULL),
(67414,25,0,'ruRU','Гаррош хочет быть богом? Творить монстров? Не для того создавалась Орда!',NULL),
(67414,25,0,'zhCN','加尔鲁什想成为神？制造怪物？这有违部落精神！',NULL),
(67414,25,0,'zhTW','卡爾洛斯想要當神?創造怪物?這可不是部落的宗旨!',NULL),
