(67414,27,0,'esES','El... Jefe de Guerra mueh\'tra... sus cartas.',NULL),
(67414,27,0,'esMX','El... Jefe de Guerra muestra... sus cartas.',NULL),
(67414,27,0,'frFR','Le… chef de guerre montre... son vrai visage.',NULL),
