(67414,27,0,'zhTW','大...大酋長...終於露出真面目。',NULL),
(67414,28,0,'deDE','Ist die Horde so weit gesunken, dass sie sich selbst umbringt? Das darf nicht sein.',NULL),
(67414,28,0,'esES','¿En eh\'to se ha conveh\'tido la Horda? ¿Matar a los suyos? No podemos permitih\'lo.',NULL),
(67414,28,0,'esMX','¿En esto se ha convertido la Horda? ¿Matar a los suyos? No podemos permitirlo.',NULL),
(67414,28,0,'frFR','C’est ça que la Horde elle va devenir ? Tuer les siens ? Ça on peut pas laisser faire.',NULL),
(67414,28,0,'koKR','호드가 어쩌다 이 지경에 이른 건가? 같은 호드를 죽이다니. 막아야 하네.',NULL),
(67414,28,0,'ruRU','Вот до чего докатилась Орда? Убивает своих же? Мы этого не допустим.',NULL),
