(67414,29,0,'zhTW','勇士，我需要你幫忙。',NULL),
(67414,30,0,'deDE','Geht zurück zum Kriegshäuptling. Sagt ihm, dass ich tot bin. Bleibt bei ihm. Beobachtet ihn.',NULL),
(67414,30,0,'esES','Volved con el Jefe de Guerra. Decidle que he mueh\'to. Vigiladlo muy de cerca.',NULL),
(67414,30,0,'esMX','Vuelvan con el Jefe de Guerra. Díganle que he muerto. Quédense cerca de él. Vigílenlo.',NULL),
(67414,30,0,'frFR','Retournez voir le chef de guerre. Dites-lui que je suis mort. Restez près de lui. Gardez un œil sur lui.',NULL),
(67414,30,0,'koKR','대족장에게 돌아가게. 내가 죽었다 전하고 곁에서 그를 감시하게.',NULL),
(67414,30,0,'ruRU','Возвращайтесь к вождю. Скажите, что я мертв. Держитесь к нему поближе. Наблюдайте.',NULL),
(67414,30,0,'zhCN','回去找酋长。告诉他我死了。跟紧他。看着他。',NULL),
(67414,30,0,'zhTW','回去找大酋長。告訴他我已經死了。待在他身邊。監視他。',NULL),
(67414,31,0,'deDE','Ihr und ich, wir kümmern uns um ihn, wenn die Zeit reif ist.',NULL),
(67414,31,0,'esES','Daremos el paso para acabar con él cuando llegue el momento.',NULL),
(67414,31,0,'esMX','Ustedes y yo actuaremos para acabar con él cuando llegue el momento.',NULL),
(67414,31,0,'frFR','Vous et moi, on va faire en sorte de le chasser en temps voulu.',NULL),
(67414,31,0,'koKR','자네들과 내가, 때가 되면 움직여 놈을 없애버려야 하네.',NULL),
(67414,31,0,'ruRU','И когда придет время, мы нанесем удар.',NULL),
(67414,31,0,'zhCN','你和我，我们将在适当的时机推翻他。',NULL),
(67414,31,0,'zhTW','你跟我聯手，等時機成熟了再一起幹掉他。',NULL),
(67414,32,0,'deDE','Es gibt andere wie mich. Ihr müsst sie finden.',NULL),
(67414,32,0,'esES','Hay otros como yo. Debéis encontrah\'los.',NULL),
(67414,32,0,'esMX','Hay otros como yo. Deben encontrarlos.',NULL),
(67414,32,0,'frFR','Il y en a d’autres qui pensent comme moi. Faut les trouver.',NULL),
(67414,32,0,'koKR','나 같은 이들이 또 있을 테니, 찾아 주게.',NULL),
(67414,32,0,'ruRU','Есть и другие, кто думает, как я. Найдите их.',NULL),
(67414,32,0,'zhCN','还有和我一样的人。去找他们。',NULL),
(67414,32,0,'zhTW','其他像我這樣的人。你得找到他們。',NULL),
(67414,33,0,'deDE','Schwört den Bluteid mit mir.',NULL),
