(67414,33,0,'zhTW','發誓...跟我一起立下血誓。',NULL),
(67569,0,0,'deDE','Wenn Ihr die Waren ausgeliefert habt, ist Eure Arbeit noch nicht getan. Ihr müsst dafür sorgen, dass unsere Vorräte immer gut gefüllt bleiben.',NULL),
(67569,0,0,'esES','No basta con entregar suministros. Esfuérzate en mantener una reserva de recursos.',NULL),
(67569,0,0,'esMX','No basta con entregar suministros. Esfuérzate en mantener una reserva de recursos.',NULL),
(67569,0,0,'frFR','Votre travail n’est pas terminé une fois les fournitures livrées. Faites de votre mieux pour que les ressources restent au maximum.',NULL),
(67569,0,0,'koKR','보급품을 한 번 가져다 준다고 해서 자네 일이 끝나는 건 아니네. 최선을 다해 물자가 풍족하게 유지될 수 있게 하게.',NULL),
(67569,0,0,'ruRU','Если вы выполнили поставку, можете считать свою часть работы выполненной. Следите за тем, чтобы у ваших рабочих всегда хватало ресурсов.',NULL),
(67569,0,0,'zhCN','把补给物资送达之后，你的工作还没有结束。你需要保持我们的资源存量。',NULL),
(67569,0,0,'zhTW','等你運送完補給，還有工作要做。盡量讓我們的資源不虞匱乏。',NULL),
(67569,1,0,'deDE','Sucht nach brüchigen Wurzeln, die aus der Erde ragen. Die haben gutes Holz!',NULL),
(67569,1,0,'esES','Busca raíces frágiles que sobresalgan del suelo. ¡Dan buena madera!',NULL),
(67569,1,0,'esMX','Busca raíces frágiles que sobresalgan del suelo. ¡Dan buena madera!',NULL),
(67569,1,0,'frFR','Gardez un œil sur les racines cassantes qu’on voit dépasser de terre. Elles contiennent du bon bois !',NULL),
(67569,1,0,'koKR','땅에서 솟아나온 부러질 듯한 나무를 찾게. 아주 쓸 만한 목재니까!',NULL),
(67569,1,0,'ruRU','Ищи древесный корни, которые могут торчать из земли. Их древесина нам пригодится!',NULL),
(67569,1,0,'zhCN','脆弱的根茎有时会暴露在土外。那些可是上好的木材。',NULL),
(67569,1,0,'zhTW','留意從土裡伸出來的脆弱的樹根，裡面的纖維品質很好!',NULL),
(67569,2,0,'deDE','Wir brauchen vor allem Holz und Lebensmittel. Sprecht mich wieder an, wenn Ihr uns weiterhelfen wollt.',NULL),
(67569,2,0,'esES','Nuestras necesidades primarias son la comida y la madera. Habla conmigo si quieres ayudarnos aún más.',NULL),
(67569,2,0,'esMX','Nuestras necesidades primarias son la comida y la madera. Habla conmigo si quieres ayudarnos aún más.',NULL),
(67569,2,0,'frFR','Nous avons avant tout besoin de nourriture et de bois. Venez me voir si vous souhaitez faire plus encore pour nous.',NULL),
