(68323,7,0,'frFR','Et voici qui pénètre dans l’arène : vous $gle:la; connaissez, vous l’adorez… Faites une ovation à $N, notre $gcompétiteur:compétitrice; de rang 8 !!','Et voici qui pénètre dans l’arène : vous $gle:la; connaissez, vous l’adorez… Faites une ovation à $N, notre $gcompétiteur:compétitrice; de rang 8 !!'),
(68323,7,0,'koKR','드디어! 다들 아시죠? 다들 사랑하시죠? 8계급 싸움꾼, $N에게 박수를 부탁드립니다!','드디어! 다들 아시죠? 다들 사랑하시죠? 8계급 싸움꾼, $N에게 박수를 부탁드립니다!'),
(68323,7,0,'ruRU','На арену выходит... Вы все $gего:ее; знаете! Вы все $gего:ее; любите! Поприветствуйте бойца 8-го ранга |3-3($n)!!!','На арену выходит... Вы все $gего:ее; знаете! Вы все $gего:ее; любите! Поприветствуйте бойца 8-го ранга |3-3($n)!!!'),
(68323,7,0,'zhCN','现在进场的这位可谓是声名远扬，人见人爱。大家鼓掌欢迎我们的8级拳手，$N！！','现在上场的这位可谓是声名远扬，人见人爱。大家鼓掌欢迎我们的8级拳手，$N！！'),
(68323,7,0,'zhTW','現在進入競技場的，你們都認識$g他:她;，你們都愛$g他:她;。掌聲歡迎第8階的鬥士$N!!','現在進入競技場的，你們都認識$g他:她;，你們都愛$g他:她;。掌聲歡迎第8階的鬥士$N!!'),
(68323,8,0,'deDE','$gEr:Sie; zählt zu den Grubenkampf-Veteranen des 9. Ranges hier in der Shlae\'gararena. Hier kommt $n!','$gEr:Sie; zählt zu den Grubenkampf-Veteranen des 9. Ranges hier in der Shlae\'gararena. Hier kommt $n!'),
(68323,8,0,'esES','Recibid a $guno de nuestros veteranos:una de nuestras veteranas; contendientes de rango 9 en el Club de Lucha. ¡Es $n!','Recibid a $guno de nuestros veteranos:una de nuestras veteranas; contendientes de rango 9 en el Club de Lucha. ¡Es $n!'),
(68323,8,0,'esMX','Reciban a $guno de nuestros veteranos:una de nuestras veteranas; contendientes de rango 9 en el Club de Lucha. ¡Es $n!','Reciban a $guno de nuestros veteranos:una de nuestras veteranas; contendientes de rango 9 en el Club de Lucha. ¡Es $n!'),
(68323,8,0,'frFR','C’est l’un de nos bastonneurs vétérans de rang 9 au Bar-Tabasse. Applaudissez $n !','C’est l’un de nos bastonneurs vétérans de rang 9 au Bar-Tabasse. Applaudissez $n !'),
(68323,8,0,'koKR','싸움굴의 9계급 베테랑 싸움꾼, $n|1을;를; 소개합니다!','투기장의 9계급 베테랑 싸움꾼, $n|1을;를; 소개합니다!'),
(68323,8,0,'ruRU','Поприветствуйте бойца-ветерана 9-го ранга Морд’Боя! Это $n!','Поприветствуйте бойца-ветерана 9-го ранга Морд’Боя! Это $n!'),
(68323,8,0,'zhCN','$g他:她;可是我们搏击竞技场最精锐的9级拳手之一：$n！','$g他:她;可是我们搏击竞技场最精锐的9级拳手之一：$n！'),
(68323,8,0,'zhTW','$g他:她;正是位居鬥陣俱樂部的第9階老手，$n!','$g他:她;正是位居鬥陣俱樂部第9階的老手，$n!'),
(68323,9,0,'deDE','Weiter betritt die Arena: Bruce, ein Krokilisk, den wir gefunden haben!',NULL),
(68323,9,0,'esES','También entra en la arena... ¡Bruce, un crocolisco que nos encontramos!',NULL),
(68323,9,0,'esMX','También entra en la arena... ¡Bruce, un crocolisco que nos encontramos!',NULL),
(68323,9,0,'frFR','Un autre adversaire entre dans l’arène : Bruce, un crocilisque que nous avons trouvé !',NULL),
(68323,9,0,'koKR','이어서 어딘가에서 발견된 악어 브루스가 투기장에 등장합니다!',NULL),
(68323,9,0,'ruRU','На арене появляется Брюс, найденный нами кроколиск!',NULL),
(68323,9,0,'zhCN','同时进场的还有布鲁斯，它是我们特意找来的一条巨鳄！',NULL),
(68323,9,0,'zhTW','同時進場的是，我們不小心在路邊找到的鱷魚 - 布魯斯!!!!',NULL),
(68323,10,0,'deDE','In der anderen Ecke haben wir Vian, den Flammen schleudernden Gefolgsmann des Donnerkönigs!',NULL),
(68323,10,0,'esES','¡En la otra esquina está Vian, el flamígero seguidor del Rey del Trueno!',NULL),
(68323,10,0,'esMX','¡En la otra esquina está Vian, el flamígero seguidor del Rey del Trueno!',NULL),
(68323,10,0,'frFR','À ma droite, voici Vian, le serviteur projectoflammes du roi-tonnerre !',NULL),
(68323,10,0,'koKR','이에 맞설 상대는... 천둥왕의 추종자, 일촉즉발의 비안입니다!',NULL),
(68323,10,0,'ruRU','В противоположном углу – Виан, изрыгающий пламя последователь Властелина Грома!',NULL),
(68323,10,0,'zhCN','我们的另一边，则是雷电之王的狂热追随者，瓦安！',NULL),
(68323,10,0,'zhTW','另一邊角落的是雷王麾下的火焰使者，『暴烈』維安!',NULL),
(68323,24,0,'deDE','Haltet Euch bereit für eine heiße Sohle auf dem Parkett. Deeken ist da!',NULL),
(68323,24,0,'esES','¡Preparaos para bailar! ¡Aquí está Deeken!',NULL),
(68323,24,0,'esMX','¡Prepárense para bailar! ¡Aquí está Deeken!',NULL),
(68323,24,0,'frFR','Tout le monde sur la piste ! Deeken est dans la place !',NULL),
(68323,24,0,'koKR','모두들 춤 출 준비를 하세요! 디켄이 나타났습니다!',NULL),
(68323,24,0,'ruRU','Вы готовы к танцам? На арене Дикен!',NULL),
(68323,24,0,'zhCN','大家一起来跳舞吧！迪肯来啦！',NULL),
(68323,24,0,'zhTW','準備跳舞!歡迎迪肯出場!',NULL),
(68323,25,0,'deDE','Als Nächstes an der Reihe ist Millie Watt! Auf der Technischen Hochschule waren wir ein Pärchen!',NULL),
(68323,25,0,'esES','¡Ahora viene Millie Vatio! ¡Salí con ella en la escuela de ingeniería!',NULL),
(68323,25,0,'esMX','¡Ahora viene Millie Vatio! ¡Salí con ella en la escuela de ingeniería!',NULL),
(68323,25,0,'frFR','Le prochain concurrent est une concurrente, c’est Millie Watt ! Je fricotais avec elle à l’école d’ingénieurs !',NULL),
(68323,25,0,'koKR','다음 상대는 밀리 와트입니다! 기계공학부에 다니던 시절에 제가 잠깐 사귀었던 아가씨죠!',NULL),
(68323,25,0,'ruRU','Далее в программе Милли Ватт! Мы с ней встречались в инженерной школе!',NULL),
(68323,25,0,'zhCN','哦，下一位选手是米莉·沃特！上工程学院的时候我和她约过会！',NULL),
(68323,25,0,'zhTW','下一個，米莉耶·瓦特!我以前在工程學校常跟她出去約會!',NULL),
(68323,26,0,'deDE','Heute auch in der Arena: 12 Fuß misst sie, die allerorts beliebte magische Leiche Fjoll! Spreche ich das überhaupt richtig aus?',NULL),
(68323,26,0,'esES','También entra en la arena... ¡vuestro cadáver de cuatro metros mágico favorito, Fjoll! ¿Lo he pronunciado bien?',NULL),
(68323,26,0,'esMX','También entra en la arena... ¡su cadáver de cuatro metros mágico favorito, Fjoll! ¿Lo he pronunciado bien?',NULL),
(68323,26,0,'frFR','Également en lice : le cadavre magique grand de quatre mètres préféré de tous, j’ai nommé Fjoll ! Je prononce bien, là ?',NULL),
(68323,26,0,'koKR','이번 상대는... 모두의 사랑을 한몸에 받는... 키가 3.5미터에 이르는 마법 시체! 피올입니다! 음... 발음이 이게 맞나요?',NULL),
(68323,26,0,'ruRU','Еще один боец. Всеобщий любимец – огроменный мертвец Фьолл! Я правильно произнес?',NULL),
(68323,26,0,'zhCN','同时进场的还有——大家最喜爱的、12英尺高的神奇僵尸，弗琼！我没读错吧？',NULL),
(68323,26,0,'zhTW','此外進場的是，大家最愛的12呎高魔法屍體，菲歐!!!! ...我有沒有念錯名字?',NULL),
(68323,27,0,'deDE','Oje... tut mir leid, aber Ihr werdet wohl gegen Proboskus antreten müssen.',NULL),
(68323,27,0,'esES','Oh, no... Lo siento, pero parece que te va a tocar luchar contra Proboskus.',NULL),
(68323,27,0,'esMX','Oh, no... Lo siento, pero parece que te va a tocar luchar contra Proboskus.',NULL),
(68323,27,0,'frFR','Bonté divine… Navré, mais on dirait que vous allez devoir affronter Proboskus.',NULL),
(68323,27,0,'koKR','아 이런... 미안합니다. 상대가 프로보스쿠스네요!',NULL),
(68323,27,0,'ruRU','Ух ты!... Мне тебя жаль, но, похоже, тебе придется сразиться с Носатиком.',NULL),
(68323,27,0,'zhCN','哦，天哪……对不起，你的对手好像是普罗波库斯。',NULL),
(68323,27,0,'zhTW','嗚，真不妙... 抱歉啦，看來要跟你打的就是普羅伯斯庫!',NULL),
(68323,28,0,'deDE','Unter den Gegnern sind einige von Gnomeregans Besten... auch wenn sie schon bessere Zeiten gesehen haben. Das Lepragnomquintett!',NULL),
(68323,28,0,'esES','Los contrincantes son la élite de Gnomeregan... aunque han visto días mejores. ¡Es el quinteto de gnomos parias!',NULL),
(68323,28,0,'esMX','Los contrincantes son la élite de Gnomeregan... aunque han visto días mejores. ¡Es el quinteto de gnomos parias!',NULL),
(68323,28,0,'frFR','Parmi les adversaires se trouve le gratin de Gnomeregan… même s’il n’est plus au mieux de sa forme. Voilà le cinq des gnomes lépreux !',NULL),
(68323,28,0,'koKR','상대는 놈리건 최고의 용사들입니다... 지금은 그다지 돋보이지 않지만요. 오염된 노움 5인조!',NULL),
(68323,28,0,'ruRU','В противоположном углу сильнейшие представители Гномрегана... хотя, конечно, они знавали и лучшие времена. Квинтет лепрогномов!',NULL),
(68323,28,0,'zhCN','另一边是诺莫瑞根的精英小队……至少他们曾经是。麻疯侏儒五重奏！',NULL),
(68323,28,0,'zhTW','接下來出場的是諾姆瑞根的精英... 顛峰等級爆表到瘋癲的... 痲瘋地精五人組!',NULL),
(68323,29,0,'deDE','Ihn fanden wir, als er dabei war, einen Sturm in Auchindoun herbeizukrächzen. Eine Runde Applaus für Yikkan Izu!',NULL),
(68323,29,0,'esES','A este nos lo encontramos venga a graznar en Auchindoun. ¡Aplaudid a Yikkan Izu!',NULL),
(68323,29,0,'esMX','A este nos lo encontramos venga a graznar en Auchindoun. ¡Aplaudan a Yikkan Izu!',NULL),
(68323,29,0,'frFR','On a déniché celui-ci en train de croasser à mort à Auchindoun. Des applaudissements pour Yikkan Izu, s’il vous plaît !',NULL),
(68323,29,0,'koKR','아킨둔에서 이 친구가 까악까악 울면서 폭풍을 일으키는 걸 발견했습니다. 이칸 이주에게 박수를 보내주세요!',NULL),
(68323,29,0,'ruRU','Мы нашли его в Аукиндоне, когда он призывал бурю. Дамы и господа, Йиккан Изу!',NULL),
(68323,29,0,'zhCN','我们在奥金顿找到了这位在风暴中嚎叫的家伙。大家鼓掌欢迎——伊坎·伊祖！',NULL),
(68323,29,0,'zhTW','我們看到這傢伙在奧齊頓嘎嘎叫個不停。向伊坎·易祖臣服吧!',NULL),
(68323,30,0,'deDE','Einige unter euch Veteranen mögen sich an diesen Kerl erinnern. Er ist vielleicht zerschlagen, aber heute zerschlägt er Euch! Hier ist Akama!',NULL),
(68323,30,0,'esES','Es posible que algunos de los veteranos se acuerden de este tipo. Sí, es un tábido, ¡pero al final del combate también lo serás tú! ¡Es Akama!',NULL),
(68323,30,0,'esMX','Es posible que algunos de los veteranos se acuerden de este tipo. Sí, es un tábido, ¡pero al final del combate también lo serás tú! ¡Es Akama!',NULL),
(68323,30,0,'frFR','Certains vétérans dans l’assistance se souviennent de cet individu. Oui, c’est un Roué, mais c’est vous qu’il va rouer de coups ! Une ovation pour Akama !',NULL),
(68323,30,0,'koKR','노장 분들은 이 친구를 기억하실지도 모르겠네요. 뒤틀린 친구이긴 하지만, 오늘만은 상대를 뒤틀어 버릴 겁니다! 아카마를 소개합니다!',NULL),
(68323,30,0,'ruRU','Многие из вас, старичков, его помнят. Может, он и Сломленный, но сегодня это не помешает ему сломить тебя! Акама!',NULL),
(68323,30,0,'zhCN','也许有些老兵还记得这个人。他是个破碎者，但今天他会打碎你的骨头！是阿卡玛！',NULL),
(68323,30,0,'zhTW','資深人士應該還記得這傢伙。是啊是啊，他是個破碎者，但是他今天就是要來把你弄破!!!把你弄碎!!!把你徹底破碎!!!歡迎阿卡瑪!!!!',NULL),
(68323,31,0,'deDE','Auch Draufhau Hufstampf heißen wir willkommen, den trotzigen Tauren aus Donnerfels! Schaut Euch nur diese MASSIVEN Schulterpolster an!',NULL),
(68323,31,0,'esES','También damos la bienvenida a Machaque Hollapezuña, ¡el tauren más terrible de Cima del Trueno! ¡Mirad qué hombreras!',NULL),
(68323,31,0,'esMX','También damos la bienvenida a Machaque Hollapezuña, ¡el tauren más terrible de Cima del Trueno! ¡Mirad qué hombreras!',NULL),
(68323,31,0,'frFR','Souhaitons aussi la bienvenue à Fracasse Martèle-Sabot, le terrible tauren des Pitons-du-Tonnerre ! Mais visez-moi ces ÉNORMES protège-épaules !',NULL),
(68323,31,0,'koKR','썬더 블러프에서 온 끔찍한 타우렌도 환영해 주세요! 스매시 후프스톰프입니다! 저 커다란 어깨보호구 좀 보세요!',NULL),
(68323,31,0,'ruRU','Поприветствуйте также Гроха Топота Копыт, ужасного таурена из Громового Утеса! Вы только посмотрите на эти мощные наплечные пластины!',NULL),
(68323,31,0,'zhCN','我们还要欢迎来自雷霆崖的恐怖牛头人——斯马什·重蹄！看看他那华丽到掉渣的肩铠！',NULL),
(68323,31,0,'zhTW','我們也歡迎潰擊·蹄踏，來自雷霆崖的恐怖牛頭人!',NULL),
(68323,32,0,'deDE','Darf ich um Ruhe bitten... wir wollen sie doch nicht verärgern. Bewundert sie in stiller Ehrfurcht: Unguloxx, die Blutgieraffe!',NULL),
(68323,32,0,'esES','Que todo el mundo guarde silencio... No queremos que se enfade. Limitaos a observar a Unguloxx, ¡la Asesinarafa!',NULL),
(68323,32,0,'esMX','Que todo el mundo guarde silencio... No queremos que se enfade. Limítense a observar a Unguloxx, ¡la Asesinarafa!',NULL),
(68323,32,0,'frFR','Un peu de silence dans la salle… Il ne faudrait pas mettre la prochaine concurrente en colère. Contentez-vous de l’admirer bouche bée. Voilà Unguloxx, la Girafféroce !',NULL),
(68323,32,0,'koKR','다들 조용히 하세요... 저 친구를 화나게 하면 안 됩니다. 조용히 감상하십시오. 살인기린 운구록스입니다!',NULL),
(68323,32,0,'ruRU','Спокойно, спокойно... Мы же не хотим разозлить его? Просто посмотрите с благоговейным трепетом на Ангулокса, жирафа-убийцу!',NULL),
(68323,32,0,'zhCN','各位，请安静……我们可不想激怒它。请屏息静气地欢迎我们的杀人鹿，乌古洛克斯！',NULL),
(68323,32,0,'zhTW','大家安靜... 千萬別惹牠生氣。只要默默的、敬畏地看著昂格洛斯...殺人長頸鹿!!!',NULL),
(68323,33,0,'deDE','Zu dieser Partnerschaft hätte es nie kommen sollen. Mir wird dabei fast übel. Hier kommt die GG Ingenieurskunst GmbH!',NULL),
(68323,33,0,'esES','Su colaboración es antinatural. De hecho, me pone enfermo. ¡Aquí viene Ingeniería GG!',NULL),
(68323,33,0,'esMX','Su colaboración es antinatural. De hecho, me pone enfermo. ¡Aquí viene Ingeniería GG!',NULL),
(68323,33,0,'frFR','Leur partenariat est un affront à la nature. En fait, ça me donne la nausée. Voilà la GG Ingénierie !',NULL),
(68323,33,0,'koKR','참 잘 어울리지 않는 한 쌍입니다. 구역질이 나려고 하네요. GG 기계공학단이 나타났습니다!',NULL),
(68323,33,0,'ruRU','Никто никогда бы не подумал, что они могут стать напарниками. На мой взгляд, в этом есть что-то нездоровое. Команда ГГ Инжиниринг!',NULL),
(68323,33,0,'zhCN','他们的搭档完全是一个意外。事实上我对此颇为厌恶。他们就是，GG工程公司组合！',NULL),
(68323,33,0,'zhTW','他們實在不該合夥的。事實上，還害我覺得有點噁心呢。接著入場的就是GG工程公司!',NULL),
(68323,34,0,'deDE','Heute auch in der Arena: Der dunkle Beschwörer. Oha, noch nicht einmal einen richtigen Namen hat er. Beängstigend!',NULL),
(68323,34,0,'esES','También entra en la arena... el invocador oscuro. Guau, ni siquiera tiene nombre. ¡Qué miedo!',NULL),
(68323,34,0,'esMX','También entra en la arena... el invocador oscuro. Guau, ni siquiera tiene nombre. ¡Qué miedo!',NULL),
(68323,34,0,'frFR','Également présent dans l’arène : le sombre invocateur. Holà, il n’a même pas de vrai nom. Ça, ça fait peur !',NULL),
(68323,34,0,'koKR','상대는... 암흑소환사입니다. 우와, 진짜 이름도 따로 없군요. 으스스합니다!',NULL),
(68323,34,0,'ruRU','На арене появляется... Призыватель Тьмы. Ничего себе, у него даже нет имени. Как страшно!',NULL),
(68323,34,0,'zhCN','另一位进入竞技场的是：黑暗召唤师。喔，他甚至没有真正的名字。好可怕！',NULL),
(68323,34,0,'zhTW','另外進場的是: 黑暗召喚師!! 哇，他連名字都沒有，好可怕呦～～～～',NULL),
(68323,35,0,'deDE','Weiter betritt die Arena: Kampftron! Dieser mächtige Schrotthaufen wartet nur darauf, Euch im Gesicht zu explodieren!',NULL),
(68323,35,0,'esES','También entra en la arena... ¡el Batallatrón! ¡Ese montón de chatarra está esperando el momento de explotarte en la cara!',NULL),
(68323,35,0,'esMX','También entra en la arena... ¡el Batallatrón! ¡Ese montón de chatarra está esperando el momento de explotarte en la cara!',NULL),
(68323,35,0,'frFR','À l’affiche en ce moment : Combatron ! Cette boîte de conserve n’attend qu’une chose : vous exploser dessus !',NULL),
(68323,35,0,'koKR','이어서, 배틀트론이 투기장에 나타났습니다! 이 고철 덩어리가 상대를 폭발시켜 버릴 겁니다!',NULL),
(68323,35,0,'ruRU','На арену выходит Битвотрон! Эта груда железа только и ждет того, чтобы разнести тебя в клочья!',NULL),
(68323,35,0,'zhCN','另一位进入竞技场的是：巴特隆！这块破铜烂铁会把你们全炸飞！',NULL),
(68323,35,0,'zhTW','同時進入競技場的是: 戰魔像!這坨廢鐵已經等不及要把你炸到天外天啦!',NULL),
(68323,36,0,'deDE','Und... Fleischklops.',NULL),
(68323,36,0,'esES','Y... Albóndiga.',NULL),
(68323,36,0,'esMX','Y... Albóndiga.',NULL),
(68323,36,0,'frFR','Et… Boulette.',NULL),
(68323,36,0,'koKR','그리고... 미트볼입니다.',NULL),
(68323,36,0,'ruRU','И... Мясыш!',NULL),
(68323,36,0,'zhCN','另一位是……肉弹！',NULL),
(68323,36,0,'zhTW','還有...肉糰。',NULL),
(68323,37,0,'deDE','$n hat gewonnen!','$n hat gewonnen!'),
(68323,37,0,'esES','¡$n ha ganado!','¡$n ha ganado!'),
(68323,37,0,'esMX','¡$n ha ganado!','¡$n ha ganado!'),
(68323,37,0,'frFR','$n est notre $gchampion:championne; !','$n est notre $gchampion:championne; !'),
(68323,37,0,'koKR','승자는 $n입니다!','승자는 $n입니다!'),
(68323,37,0,'ruRU','$gНаш победитель:Наша победительница; – $n!','$gНаш победитель:Наша победительница; – $n!'),
(68323,37,0,'zhCN','胜利者是：$n！','胜利者是：$n！'),
(68323,37,0,'zhTW','$n是我們的贏家!','$n是我們的贏家!'),
(68323,37,1,'deDE','Sieh an, sieh an! $n hat gewonnen! Da schulde ich jetzt wohl jemandem Geld.','Sieh an, sieh an! $n hat gewonnen! Da schulde ich jetzt wohl jemandem Geld.'),
(68323,37,1,'esES','¡Vaya, vaya! ¡Ha ganado $n! Creo que le debo dinero a alguien.','¡Vaya, vaya! ¡Ha ganado $n! Creo que le debo dinero a alguien.'),
(68323,37,1,'esMX','¡Vaya, vaya! ¡Ha ganado $n! Creo que le debo dinero a alguien.','¡Vaya, vaya! ¡Ha ganado $n! Creo que le debo dinero a alguien.'),
(68323,37,1,'frFR','Bien, bien, bien ! $n l’emporte ! Je crois bien que je dois de l’argent à quelqu’un, moi…','Bien, bien, bien ! $n l \'emporte ! Je crois bien que je dois de l’argent à quelqu’un, moi…'),
(68323,37,1,'koKR','이런 이런 이런... $n|1이;가; 이겼네요! 저도 돈을 좀 잃은 것 같아요.','이런 이런 이런... $n|1이;가; 이겼네요! 저도 돈을 좀 잃은 것 같아요.'),
(68323,37,1,'ruRU','Так-так-так! $n побеждает! Похоже, теперь я кое-кому должен денег.','Так-так-так! $n побеждает! Похоже, теперь я кое-кому должна денег.'),
(68323,37,1,'zhCN','很好很好！$n获胜！看来我要欠某人一些钱了。','很好很好！$n获胜！看来我要欠某人一些钱了。'),
(68323,37,1,'zhTW','非常好!$n獲勝!看來我欠別人的賭債變多了。','非常好!$n獲勝!看來我欠別人的賭債變多了。'),
(68323,37,2,'deDE','Glückwunsch, $n! Bitte hinterlasst keine blutigen Fußspuren außerhalb der Arena.','Glückwunsch, $n! Bitte hinterlasst keine blutigen Fußspuren außerhalb der Arena.'),
(68323,37,2,'esES','¡Felicidades, $n! Intenta no dejar huellas de sangre fuera de la arena.','¡Felicidades, $n! Intenta no dejar huellas de sangre fuera de la arena.'),
(68323,37,2,'esMX','¡Felicidades, $n! Intenta no dejar huellas de sangre fuera de la arena.','¡Felicidades, $n! Intenta no dejar huellas de sangre fuera de la arena.'),
(68323,37,2,'frFR','Félicitations, $n ! Essayez de ne pas mettre du sang partout en sortant de l’arène.','Félicitations, $n ! Essayez de ne pas mettre du sang partout en sortant de l’arène.'),
(68323,37,2,'koKR','축하합니다, $n! 거기 투기장 밖에 피투성이 발자국은 남기지 마세요.','축하합니다, $n! 거기 투기장 밖에 피투성이 발자국은 남기지 마세요.'),
(68323,37,2,'ruRU','Мои поздравления, $n! Постарайся не оставлять за пределами арены кровавых следов.','Мои поздравления, $n! Постарайся не оставлять за пределами арены кровавых следов.'),
(68323,37,2,'zhCN','祝贺你，$n！请不要在场外留下血脚印。','祝贺你，$n！请不要在场外留下血脚印。'),
(68323,37,2,'zhTW','恭喜，$n!請不要把沾了血跡的腳印留在競技場外。','恭喜，$n!請不要把沾了血跡的腳印留在競技場外。'),
(68323,37,3,'deDE','Das offizielle Ergebnis ist da: $n hat es geschafft, nicht zu sterben. Das habt Ihr großartig gemacht, $n!','Das offizielle Ergebnis ist da: $n hat es geschafft, nicht zu sterben. Das habt Ihr großartig gemacht, $n!'),
(68323,37,3,'esES','¡Ya es oficial! $n ha conseguido no morir. ¡Buen trabajo, $n!','¡Ya es oficial! $n ha conseguido no morir. ¡Buen trabajo, $n!'),
(68323,37,3,'esMX','¡Ya es oficial! $n ha conseguido no morir. ¡Buen trabajo, $n!','¡Ya es oficial! $n ha conseguido no morir. ¡Buen trabajo, $n!'),
(68323,37,3,'frFR','C’est officiel ! $n a réussi à ne pas mourir. Bravo, $n !','C’est officiel ! $n a réussi à ne pas mourir. Bravo, $n !'),
(68323,37,3,'koKR','끝났습니다! $n|1이;가; 가까스로 살아남았습니다. 정말 아슬아슬했네요, $n!','끝났습니다! $n|1이;가; 가까스로 살아남았습니다. 정말 아슬아슬했네요, $n!'),
(68323,37,3,'ruRU','Официально подтверждаю – |3-2($n) удалось не умереть! Молодчина, что $gостался:осталась; в живых, $n!','Официально подтверждаю – |3-2($n) удалось не умереть! Молодчина, что $gостался:осталась; в живых, $n!'),
(68323,37,3,'zhCN','官方消息！$n活下来了。能活下来就不容易啊，$n！','官方消息！$n活下来了。能活下来就不容易啊，$n！'),
(68323,37,3,'zhTW','動真格了!$n竟然還活著。活著就很了不起，$n!','動真格了!$n竟然還活著。活著就很了不起，$n!'),
(68323,38,0,'deDE','Autsch... tut mir leid, $n. Stellt Euch wieder an und versucht\'s erneut.','Autsch... tut mir leid, $n. Stellt Euch wieder an und versucht\'s erneut.'),
(68323,38,0,'esES','Ay... Lo siento, $n. Ponte a la cola y vuelve a intentarlo.','Ay... Lo siento, $n. Ponte a la cola y vuelve a intentarlo.'),
(68323,38,0,'esMX','Ay... Lo siento, $n. Únete a la cola y vuelve a intentarlo.','Ay... Lo siento, $n. Únete a la cola y vuelve a intentarlo.'),
(68323,38,0,'frFR','Ouille… désolé, $n. Retournez dans la file et retentez votre chance.','Ouille… désolé, $n. Retournez dans la file et retentez votre chance.'),
(68323,38,0,'koKR','아이코... 안됐네요, $n 님. 다시 도전해 보세요. 줄은 다시 서야 해요.','아이코... 안됐네요, $n 님. 다시 도전해 보세요. 줄은 다시 서야 해요.'),
(68323,38,0,'ruRU','Ой... извини, $n. Возвращайся в очередь и попробуй еще раз.','Ой... извини, $n. Возвращайся в очередь и попробуй еще раз.'),
(68323,38,0,'zhCN','哎哟……抱歉，$n。请回去重新排队，再试一次。','哎哟……抱歉，$n。请回去重新排队，再试一次。'),
(68323,38,0,'zhTW','噢...抱歉，$n。回去排好隊再來試一次。','噢...抱歉，$n。回去排好隊再來試一次。'),
(68323,38,1,'deDE','Argh... das sieht nicht so schön aus. Wir bräuchten hier mal einen Priester oder so jemanden in der Art.','Argh... das sieht nicht so schön aus. Wir bräuchten hier mal einen Priester oder so jemanden in der Art.'),
(68323,38,1,'esES','Beeej, qué asco. ¡¿Quiere alguien llamar a un sacerdote o algo así?!','Beeej, qué asco. ¡¿Quiere alguien llamar a un sacerdote o algo así?!'),
(68323,38,1,'esMX','Beeej, qué asco. ¡¿Quiere alguien llamar a un sacerdote o algo así?!','Beeej, qué asco. ¡¿Quiere alguien llamar a un sacerdote o algo así?!'),
(68323,38,1,'frFR','Eurk… quel carnage. J’aurais besoin d’un prêtre ou quelque chose du genre ici, s’il vous plaît !','Eurk… quel carnage. J’aurais besoin d’un prêtre ou quelque chose du genre ici, s’il vous plaît !'),
(68323,38,1,'koKR','우엑... 정말 처참하네요. 누가 사제나 뭐 그런 친구 하나 불러 줄래요?!','우엑... 정말 처참하네요. 누가 사제나 뭐 그런 친구 하나 불러 줄래요?!'),
(68323,38,1,'ruRU','Фуу... Ну и месиво. У нас тут жреца поблизости нет?','Фуу... Ну и месиво. У нас тут жреца поблизости нет?'),
(68323,38,1,'zhCN','呃……真是一团糟。找个牧师之类的来好吗？！','呃……真是一团糟。找个牧师之类的来好吗？！'),
(68323,38,1,'zhTW','噁...搞的亂七八糟的。能不能找個牧師還是什麼的來一下?!','噁...搞的亂七八糟的。能不能找個牧師還是什麼的來一下?!'),
(68323,38,2,'deDE','Das... hat kein gutes Ende gefunden.','Das... hat kein gutes Ende gefunden.'),
(68323,38,2,'esES','Eso... no ha acabado bien.','Eso... no ha acabado bien.'),
(68323,38,2,'esMX','Eso... no ha acabado bien.','Eso... no ha acabado bien.'),
(68323,38,2,'frFR','Ça… ne s’est pas très bien terminé.','Ça… ne s’est pas très bien terminé.'),
(68323,38,2,'koKR','그거 참... 안 좋게 끝났네요.','그거 참... 안 좋게 끝났네요.'),
(68323,38,2,'ruRU','Все закончилось... не очень-то хорошо.','Все закончилось... не очень-то хорошо.'),
(68323,38,2,'zhCN','这个……下场可不怎么样。','这个……下场可不怎么样。'),
(68323,38,2,'zhTW','結局...不盡如人意。','結局...不盡如人意。'),
(68323,38,3,'deDE','$n, $n, $n. Das nächste Mal versucht doch bitte, nicht so häufig zu sterben.','$n, $n, $n. Das nächste Mal versucht doch bitte, nicht so häufig zu sterben.'),
(68323,38,3,'esES','$n, $n, $n... La próxima vez intenta que no te maten tanto.','$n, $n, $n... La próxima vez intenta que no te maten tanto.'),
(68323,38,3,'esMX','$n, $n, $n... La próxima vez intenta que no te maten tanto.','$n, $n, $n... La próxima vez intenta que no te maten tanto.'),
(68323,38,3,'frFR','$n, $n, $n. La prochaine fois, essayez de moins mourir.','$n, $n, $n. La prochaine fois, essayez de moins mourir.'),
(68323,38,3,'koKR','$n, $n, 우리 $n... 다음 번에는 이렇게 자주 죽지 마세요.','$n, $n, 우리 $n... 다음 번에는 이렇게 쉽게 죽지 마세요.'),
(68323,38,3,'ruRU','$n, $n, $n. Постарайся в следующий раз не умирать так сильно.','$n, $n, $n. Постарайся в следующий раз не умирать так сильно.'),
(68323,38,3,'zhCN','$n，$n，$n。拜托你下回别再死那么多次了。','$n，$n，$n。拜托你下回别再死那么多次了。'),
(68323,38,3,'zhTW','$n、$n、$n。下一次，想辦法別死這麼大。','$n、$n、$n。下一次，想辦法別死這麼大。'),
(68323,39,0,'deDE','Was sehen meine müden Augen? Bruce ist wieder da! Ein besserer, schnellerer, stärkerer Bruce! MECHA-BRUCE!!!',NULL),
(68323,39,0,'esES','¿Pero qué es esto? ¡Bruce ha vuelto! ¡Un Bruce mejor, más rápido y más fuerte! ¡Es MECA-BRUCE! ¡¡Yujuuuu!!',NULL),
(68323,39,0,'esMX','¿Pero qué es esto? ¡Bruce ha vuelto! ¡Un Bruce mejor, más rápido y más fuerte! ¡Es MECA-BRUCE! ¡¡Yujuuuu!!',NULL),
(68323,39,0,'frFR','Voyez-vous ça ? Bruce est de retour ! Meilleur, plus rapide, plus fort, c’est Méca-Bruce ! OUAIS !!',NULL),
(68323,39,0,'koKR','이게 누구야? 브루스가 돌아왔습니다! 더 힘세고 강해져서 돌아온 브루스! 기계브루스입니다! 만세!!',NULL),
(68323,39,0,'ruRU','Что это? Брюс вернулся! Он стал лучше, быстрее, сильнее! Это Меха-Брюс! Ура!!!',NULL),
(68323,39,0,'zhCN','这是谁啊？布鲁斯回来了！一个更好、更快、更强的布鲁斯！他就是，机甲布鲁斯！！耶！！！',NULL),
(68323,39,0,'zhTW','咦，怎麼回事?布魯斯回來了!更強、更壯、更快!機械布魯斯!!喔耶!!',NULL),
(68323,40,0,'deDE','Zeit, die alten Glücksbringer abzustauben, denn heute werdet Ihr sie brauchen. Gegen Opa Brummelflüte!',NULL),
(68323,40,0,'esES','Sácale brillo al grisgrís, porque te va a hacer falta. ¡Es el abuelo Chiriflauta!',NULL),
(68323,40,0,'esMX','Sácale brillo al grisgrís, porque te va a hacer falta. ¡Es el abuelo Chiriflauta!',NULL),
(68323,40,0,'frFR','Dépoussiérez vos grigris, vous allez en avoir besoin. Voilà Pépé Rouspéteur !',NULL),
(68323,40,0,'koKR','복덩이의 먼지를 터십시오. 이번엔 복이 필요할테니까요. 이번 상대는 할아범 투덜피리입니다!',NULL),
(68323,40,0,'ruRU','Стряхните пыль со своих счастливых талисманов, они вам пригодятся. Это Дедушка Скрипучая Флейта!',NULL),
(68323,40,0,'zhCN','擦亮你的幸运符吧，你会用得上它的。接下来进场的是，老爹土笛子！',NULL),
(68323,40,0,'zhTW','拍拍幸運星，因為你接下來真的需要點運氣。歡迎寶笛爺爺!',NULL),
(68323,41,0,'deDE','Habt Ihr Euch schon einmal gefragt, was wir mit all unseren ausgedienten Robotern machen? Wir lassen sie in blutigen Gladiatorenkämpfen antreten, ist doch klar! Hier kommt der Blingtron 3000!',NULL),
(68323,41,0,'esES','¿Os habéis preguntado alguna vez qué se hace con los robots obsoletos? Los mandamos a morir a sangrientas arenas de gladiadores, por supuesto. ¡Aquí tenéis al Joyatrón 3000!',NULL),
(68323,41,0,'esMX','¿Se han preguntado alguna vez qué se hace con los robots obsoletos? Los mandamos a morir a sangrientas arenas de gladiadores, por supuesto. ¡Les presento al Joyatrón 3000!',NULL),
(68323,41,0,'frFR','Vous ne vous êtes jamais demandé ce que nous faisions de nos robots obsolètes ? Nous les envoyons finir leurs jours dans une arène sanglante, évidemment ! Voici le Bling-o-tron 3000 !',NULL),
(68323,41,0,'koKR','우리가 한물 간 로봇들로 뭘 하냐고요? 당연히 유혈이 난무하는 검투사 투기장으로 보내 죽을 때까지 싸우게 하죠! 여러분, 블링트론 3000입니다!',NULL),
(68323,41,0,'ruRU','Знаете, что мы делаем с устаревшими роботами? Посылаем их на смерть на кровавых гладиаторских аренах, разумеется! А вот и Блескотрон-3000!',NULL),
(68323,41,0,'zhCN','想知道我们是怎么处理报废机器人的吗？当然是把他们送到血腥的竞技场来送死了！现在进场的是，布林顿3000！',NULL),
(68323,41,0,'zhTW','你是否想過，要怎麼處理不要的機器人?當然是派它們到血腥的競技場送死呀!歡迎布靈登3000型登場!',NULL),
(68323,42,0,'deDE','Ebenfalls im Ring: der Ho-zen mit der Bombenkiste! Meister Don-Don, der explosive Affenabt!',NULL),
(68323,42,0,'esES','¡También está entrando en la arena el hozen con la caja de explosivos! Es el maestro Bum Bum, ¡el monje mono lanzador de dinamita!',NULL),
(68323,42,0,'esMX','¡También está entrando en la arena el hozen con la caja de explosivos! Es el maestro Bum Bum, ¡el monje mono lanzador de dinamita!',NULL),
(68323,42,0,'frFR','Du neuf dans l’arène : un hozen bardé de bombes ! Voici Maître Boum Boum, le singe moine lanceur de dynamite !',NULL),
(68323,42,0,'koKR','이제 투기장에 들어서는 건, 폭탄 상자를 든 호젠입니다! 다이너마이트를 투척하는 원숭이 수도사, 사부 뻥 뻥을 소개합니다!',NULL),
(68323,42,0,'ruRU','Также на арену выходит хозен с ящиком бомб! Это мастер Бум-Бум, обезьяна-монах – подрывник!',NULL),
(68323,42,0,'zhCN','同时进场的还有：带着大箱炸弹的猢狲！他就是扔炸药的猢狲武僧，布姆布姆大师！',NULL),
(68323,42,0,'zhTW','另一邊踏入競技場的是:帶著一箱炸彈的猴人!讓我們歡迎丟炸彈功力無人能及的位猴人武僧，砰砰大師!',NULL),
