(68408,1,0,'deDE','Ihr wollt kämpfen? Kommt wieder, wenn Ihr ein wenig stärker seid.$b$bIhr dürft allerdings gern zusehen.','Ihr wollt kämpfen? Kommt wieder, wenn Ihr ein wenig stärker seid.$b$bIhr dürft allerdings gern zusehen.'),
(68408,1,0,'esES','¿Quieres luchar? Vuelve cuando seas un poco más fuerte.$b$bPero puedes quedarte a mirar.','¿Quieres luchar? Vuelve cuando seas un poco más fuerte.$b$bPero puedes quedarte a mirar.'),
