(68408,1,0,'koKR','싸우고 싶다고? 더 강해지면 다시 찾아오게.$b$b그래도 관람은 언제든 할 수 있지.','싸우고 싶다고? 더 강해지면 다시 찾아오게.$b$b그래도 관람은 언제든 할 수 있지.'),
(68408,1,0,'ruRU','Хочешь поучаствовать в бою? Возвращайся, когда станешь немного сильнее.$b$bНо посмотреть ты можешь и сейчас.','Хочешь поучаствовать в бою? Возвращайся, когда станешь немного сильнее.$b$bНо посмотреть ты можешь и сейчас.'),
