(69026,10,0,'esES','¡Ven a contarlos, cobarde!',NULL),
(69026,10,0,'esMX','¡Ven a contarlos, cobarde!',NULL),
(69026,10,0,'frFR','Venez les compter vous-même, lâche !',NULL),
(69026,10,0,'koKR','나와라, 겁쟁이! 보여줄 테니!',NULL),
(69026,10,0,'ruRU','Выйди и посмотри сам, трус!',NULL),
(69026,10,0,'zhCN','自己出来数数啊，懦夫！',NULL),
(69026,10,0,'zhTW','過來數一數啊，懦夫!',NULL),
(69026,11,0,'deDE','Hier ist keine Armee. Nur eine Handvoll Helden steht zwischen dir und dem König von Sturmwind. Hast du etwa Angst?',NULL),
(69026,11,0,'esES','Aquí no hay ningún ejército. Solo un puñado de héroes os separa del Rey de Ventormenta. ¿Tenéis miedo?',NULL),
(69026,11,0,'esMX','Aquí no hay ningún ejército. Solo hay un puñado de héroes entre ustedes y el Rey de Ventormenta. ¿Tienen miedo?',NULL),
(69026,11,0,'frFR','Nous n’avons pas d’armée. Seuls quelques héros se dressent entre vous et le roi de Hurlevent. De quoi avez-vous peur ?',NULL),
(69026,11,0,'koKR','우리 군대는 여기 없다. 영웅 몇 명만 쓰러뜨리면 스톰윈드 왕을 노릴 수 있다. 두려운가?',NULL),
(69026,11,0,'ruRU','Здесь нет армии. Лишь горстка смельчаков стоит между тобой и королем Штормграда.',NULL),
(69026,11,0,'zhCN','这里可没有什么大军，只有暴风城国王和几名英雄而已。难道你怕了吗？',NULL),
(69026,11,0,'zhTW','這裡又沒有軍隊。只有一些英雄擋在你跟暴風城國王中間。你怕了嗎?',NULL),
(69026,12,0,'deDE','Der Sieg ist unser! Und nicht ein Tropfen Blut wurde auf diesem heiligen Boden vergossen.',NULL),
(69026,12,0,'esES','¡La victoria es nuestra! Y sin derramar una gota de sangre en suelo sagrado.',NULL),
(69026,12,0,'esMX','¡La victoria es nuestra! Y no se derramó ni una gota de sangre en suelo sagrado.',NULL),
(69026,12,0,'frFR','Victoire ! Et pas une seule goutte de sang versée sur une terre sainte.',NULL),
(69026,12,0,'koKR','승리했다! 게다가 신성한 땅에 피를 흘리지도 않았다.',NULL),
(69026,12,0,'ruRU','Мы победили! Ни капли крови не упало на священную землю.',NULL),
(69026,12,0,'zhCN','我们胜利了！而且没让这片圣地溅上一滴鲜血。',NULL),
(69026,12,0,'zhTW','我們的勝利之日!而且沒有流下一滴血到這片神聖之地。',NULL),
(69026,13,0,'deDE','Es gab eine Zeit, da hätte ich dasselbe getan. Aber über die Jahre habe ich viel gelernt. Ich bin auf zu viele von Garroshs Tricks hereingefallen.',NULL),
(69026,13,0,'esES','Hubo un tiempo en el que yo habría hecho lo mismo. Pero he aprendido con los años. He caído en demasiados ardides de Garrosh.',NULL),
(69026,13,0,'esMX','Hubo un tiempo en el que yo habría hecho lo mismo. Pero he aprendido mucho con los años. He caído en demasiadas trampas de Garrosh.',NULL),
(69026,13,0,'frFR','Autrefois, j’aurais fait la même erreur. Mais j’ai beaucoup appris au fil des ans. Garrosh m’a piégé un trop grand nombre de fois.',NULL),
(69026,13,0,'koKR','예전의 나라면 그랬을 거요. 하지만 그 동안 많은 걸 배웠지. 가로쉬에게 한두 번 당한 게 아니니.',NULL),
(69026,13,0,'ruRU','Раньше я бы так и поступил. Но с годами я многому научился. Мы слишком часто попадались на уловки Гарроша.',NULL),
(69026,13,0,'zhCN','我曾经也和你一样。但这么多年来我学会了许多，我也已经尝够了加尔鲁什的诡计。',NULL),
(69026,13,0,'zhTW','以前的我也會這麼做，但這麼多年來我終於學乖了。我已經中過太多次卡爾洛斯的詭計了。',NULL),
(69026,14,0,'deDE','Von jetzt an bestimmen wir die Gefechtsumstände.',NULL),
(69026,14,0,'esES','A partir de ahora, nosotros dictamos las reglas.',NULL),
(69026,14,0,'esMX','A partir de ahora, jugaremos según nuestras reglas.',NULL),
(69026,14,0,'frFR','À partir de maintenant, c’est nous qui établissons les règles.',NULL),
(69026,14,0,'koKR','지금부터는 우리가 이 전쟁을 주도하오.',NULL),
(69026,14,0,'ruRU','Теперь мы будем вступать в бой только на наших условиях.',NULL),
(69026,14,0,'zhCN','从今天起，我们赋予了战争新的含义。',NULL),
(69026,14,0,'zhTW','從今天起，戰況將由我們來主導。',NULL),
(69026,15,0,'deDE','Ich mag kein Politiker sein, Tyrande. Aber ich bin ein Kämpfer. Und wir können diesen Krieg gewinnen.',NULL),
(69026,15,0,'esES','Tyrande, no seré un político, pero sí soy un luchador. Sé que podemos ganar esta guerra.',NULL),
(69026,15,0,'esMX','Tyrande, no seré un político, pero sí soy un luchador. Sé que podemos ganar esta guerra.',NULL),
(69026,15,0,'frFR','Tyrande, je ne suis peut-être pas politicien, mais je suis un bon guerrier. Je sais que nous pouvons gagner.',NULL),
(69026,15,0,'koKR','티란데, 나는 정치는 못할지 몰라도 싸움은 잘하오. 우린 이 전쟁에서 이길 수 있소.',NULL),
(69026,15,0,'ruRU','Я не политик, Тиранда, я воин. И я знаю, что мы можем победить в этой войне.',NULL),
(69026,15,0,'zhCN','泰兰德，我并非政客，我是个战士。我知道我们能赢。',NULL),
(69026,15,0,'zhTW','泰蘭妲，可能我不是個政治家。但是我是個戰士。我知道我們能在這場戰爭中獲勝。',NULL),
(69026,16,0,'deDE','Wir müssen zusammenhalten. Ihr müsst mir vertrauen. Darauf, dass ich das Richtige tue. Gemeinsam können wir nicht verlieren.',NULL),
(69026,16,0,'esES','Tenemos que permanecer juntos. Confía en mí. Te aseguro que haré lo correcto. Si actuamos unidos, no podemos fracasar.',NULL),
(69026,16,0,'esMX','Solo tenemos que permanecer juntos. Debes confiar en mí. Saber que haré lo correcto. Si actuamos unidos, no podemos fracasar.',NULL),
(69026,16,0,'frFR','Nous devons nous serrer les coudes. Faites-moi confiance. Je prendrai les bonnes décisions. Ensemble, nous n’échouerons pas.',NULL),
(69026,16,0,'koKR','단결해야 하오. 나를 믿어 주시오. 내가 옳은 선택을 할 거라고 말이오. 우리가 하나가 되면 절대 실패하지 않소.',NULL),
(69026,16,0,'ruRU','Нужно только действовать сообща. Доверься мне. Пойми, что я поступаю правильно. Если мы будем едины, то все преодолеем.',NULL),
(69026,16,0,'zhCN','我们必须团结一致。你要相信我，并且认同我。只要我们齐心协力，就一定会赢。',NULL),
(69026,16,0,'zhTW','我們必須要團結努力。你得相信我，相信我一定會做出正確的決定。只要同心協力，我們絕不可能落敗。',NULL),
(69926,0,0,'deDE','Ihr wagt es, uns\'re Vorbereitungen zu stör\'n? Die Zandalari werd\'n sich nicht aufhalten lass\'n, diesmal nicht!','Ihr wagt es, uns\'re Vorbereitungen zu stör\'n? Die Zandalari werd\'n sich nicht aufhalten lass\'n, diesmal nicht!'),
(69926,0,0,'esES','¡Cómo osáis interrumpir nueh\'tros preparativos! ¡Nadie detendrá a los Zandalari! ¡Eh\'ta vez no!','¡Cómo osáis interrumpir nueh\'tros preparativos! ¡Nadie detendrá a los Zandalari! ¡Eh\'ta vez no!'),
(69926,0,0,'esMX','¡Cómo osan interrumpir nuestros preparativos! ¡Nadie detendrá a los Zandalari! ¡Esta vez no!','¡Cómo osan interrumpir nuestros preparativos! ¡Nadie detendrá a los Zandalari! ¡Esta vez no!'),
(69926,0,0,'frFR','Comment osez-vous interrompre nos préparatifs ! Les Zandalari ne seront pas stoppés. Pas cette fois !','Comment osez-vous interrompre nos préparatifs ! Les Zandalari ne seront pas stoppés. Pas cette fois !'),
(69926,0,0,'koKR','감히 우릴 막겠다고? 잔달라 부족을 막을 순 없다! 이번엔 안 돼!','감히 우릴 막겠다고? 잔달라 부족을 막을 순 없다! 이번엔 안 돼!'),
(69926,0,0,'ruRU','Как вы смеете вмешиваться в наши планы! На этот раз зандаларов не остановить!','Как вы смеете вмешиваться в наши планы! На этот раз зандаларов не остановить!'),
(69926,0,0,'zhCN','你们竟敢打断我的筹备工作！这一次，赞达拉不可阻挡！','你们竟敢打断我的筹备工作！这一次，赞达拉不可阻挡！'),
(69926,0,0,'zhTW','你們竟敢打擾我們的準備工作!贊達拉這次不會再被阻止了!','你們竟敢打擾我們的準備工作!贊達拉這次不會再被阻止了!'),
(69926,1,0,'deDE','Vernichtet sie, ich befehle es! Nein, nein, halt! Stopp! Stooo...','Vernichtet sie, ich befehle es! Nein, nein, halt! Stopp! Stooo...'),
(69926,1,0,'esES','¡Deh\'trúyelos, te lo o\'deno! ¡No, para! ¡Para!','¡Deh\'trúyelos, te lo o\'deno! ¡No, para! ¡Para!'),
(69926,1,0,'esMX','¡Destrúyanlos, se los ordeno! ¡No, basta! ¡Basta!','¡Destrúyanlos, se los ordeno! ¡No, basta! ¡Basta!'),
(69926,1,0,'frFR','Détruisez-les, c’est un ordre ! Non, arrêtez ! Arrêtez !','Détruisez-les, c’est un ordre ! Non, arrêtez ! Arrêtez !'),
(69926,1,0,'koKR','놈들을 처치해라, 명령이다! 잠깐, 멈춰! 멈춰!','놈들을 처치해라, 명령이다! 잠깐, 멈춰! 멈춰!'),
(69926,1,0,'ruRU','Уничтожь их, это приказ! Нет, стой, стой! Остановись!','Уничтожь их, это приказ! Нет, стой, стой! Остановись!'),
(69926,1,0,'zhCN','我命令你，消灭他们！不，住手！住手！','我命令你，消灭他们！不，住手！住手！'),
(69926,1,0,'zhTW','消滅他們，我命令你!不，停，停!','消滅他們，我命令你!不，停，停!'),
(70126,0,0,'deDE','Ja! Endlich! Ich habe eine Einladung zur Kampfgilde gewonnen! Jetzt kann mich niemand mehr aufhalten!',NULL),
(70126,0,0,'esES','¡Sí! ¡Por fin he ganado una invitación para la Hermandad de camorristas! ¡Ahora nadie podrá detenerme!',NULL),
(70126,0,0,'esMX','¡Sí! ¡Por fin he ganado una invitación para el Gremio de luchadores! ¡Ahora nadie podrá detenerme!',NULL),
(70126,0,0,'frFR','Oui ! Enfin ! On m’a invité chez les Bastonneurs ! Plus rien ne peut m’arrêter maintenant !',NULL),
(70126,0,0,'koKR','아싸! 드디어! 싸움꾼 조합 초대장이다! 이제 날 막을 자는 없어!',NULL),
(70126,0,0,'ruRU','Да! Наконец-то! Я выиграл приглашение в бойцовскую гильдию! Теперь меня никто не остановит!',NULL),
(70126,0,0,'zhCN','耶！终于来了！我赢得了搏击俱乐部的邀请函！现在谁也别想拦着我！',NULL),
(70126,0,0,'zhTW','太棒了!我終於拿到鬥陣俱樂部的邀請!沒有人能阻止我了!',NULL),
(70126,0,1,'deDE','Seht alle her! Ich habe eine Einladung zur Kampfgilde gewonnen! Ich kann es nicht erwarten, es auszuprobieren!',NULL),
(70126,0,1,'esES','¡Mirad todos! ¡He ganado una invitación para la Hermandad de camorristas! ¡Estoy deseando usarla!',NULL),
(70126,0,1,'esMX','¡Miren todos! ¡He ganado una invitación para el Gremio de luchadores! ¡Estoy deseando usarla!',NULL),
(70126,0,1,'frFR','Regardez, tout le monde ! J’ai gagné une invitation chez les Bastonneurs ! J’ai hâte d’y être !',NULL),
(70126,0,1,'koKR','다들 이것 좀 봐요! 싸움꾼 조합 초대장을 받았어요! 어서 가 보고 싶네요!',NULL),
(70126,0,1,'ruRU','Смотрите все! Я выиграл приглашение в бойцовскую гильдию! Не могу дождаться, чтобы попасть туда!',NULL),
(70126,0,1,'zhCN','大家快看！我赢得了搏击俱乐部的邀请函！我已经等不及要去试试身手了！',NULL),
(70126,0,1,'zhTW','大家看啊!我贏到鬥陣俱樂部的邀請了!我等不及要拿來用啊!',NULL),
(70126,0,2,'deDE','Ich habe gerade eine Einladung zur Kampfgilde erhalten! Ich werde heute Abend bestimmt schon auf Rang 8 sein! Ich hoffe nur, dass ich bis dahin nicht mein Ticket verliere.',NULL),
(70126,0,2,'esES','¡Acabo de ganar una invitación para la Hermandad de camorristas! ¡Seguro que esta noche ya tendré rango 8! Espero no perder la invitación antes de llegar.',NULL),
(70126,0,2,'esMX','¡Acabo de ganar una invitación para el Gremio de luchadores! ¡Seguro que esta noche ya tendré rango 8! Espero no perder la invitación antes de llegar.',NULL),
(70126,0,2,'frFR','Je viens de gagner une invitation chez les Bastonneurs ! J’atteindrai certainement le rang 8 avant demain ! Le tout, c’est de ne pas perdre mon ticket.',NULL),
(70126,0,2,'koKR','방금 싸움꾼 조합 초대장을 받았어! 분명 오늘 밤이면 8계급이 될 거야! 도착하기 전에 초대장을 잃어버리지 않아야 하는데.',NULL),
(70126,0,2,'ruRU','Я только что выиграл приглашение в бойцовскую гильдию! Ну все, сегодня точно получу 8-й ранг! Надеюсь, я не потеряю свой билет по пути туда.',NULL),
(70126,0,2,'zhCN','我刚刚赢得了一张搏击俱乐部的邀请函！我今晚肯定就能到8级！但愿在抵达那里之前，我不会把票弄丢了。',NULL),
(70126,0,2,'zhTW','我剛剛贏到鬥陣俱樂部的邀請了!今晚我一定會衝到第8階的!希望不要人還沒到就把票搞丟了...',NULL),
(70126,1,0,'deDE','Ich glaube, ich war noch nicht bereit ein Grubenkämpfer zu sein.',NULL),
(70126,1,0,'esES','Supongo que no estaba preparado para ser un camorrista.',NULL),
(70126,1,0,'esMX','Supongo que no estaba preparado para ser un luchador.',NULL),
(70126,1,0,'frFR','Il faut croire que je n’étais pas encore prêt à devenir un Bastonneur.',NULL),
(70126,1,0,'koKR','싸움꾼이 되기엔 부족했던 모양이야.',NULL),
(70126,1,0,'ruRU','Кажется, я еще не готов быть бойцом.',NULL),
(70126,1,0,'zhCN','我想我还没有做好成为拳手的准备。',NULL),
(70126,1,0,'zhTW','我大概還不夠格當鬥士吧。',NULL),
