(70678,0,0,'esES','¡Flauta grisgrís!',NULL),
(70678,0,0,'esMX','¡Flauta grisgrís!',NULL),
(70678,0,0,'frFR','Grigri flatulent !',NULL),
(70678,0,0,'koKR','복덩이 플루트!',NULL),
(70678,0,0,'ruRU','Флейта-удачка!',NULL),
(70678,0,0,'zhCN','幸运之笛！',NULL),
(70678,0,0,'zhTW','看我的幸運笛!',NULL),
(70678,1,0,'deDE','Dummes Grummelbündel!',NULL),
(70678,1,0,'esES','¡Estúpido paquete grúmel!',NULL),
(70678,1,0,'esMX','¡Estúpido paquete grúmel!',NULL),
(70678,1,0,'frFR','Saleté de paquetage grumelot !',NULL),
(70678,1,0,'koKR','멍청한 그루멀짐 같으니!',NULL),
