(70740,0,0,'deDE','Ihr wollt ein Geschenk?! TJA, MEINE BEINE FUNKTIONIEREN NOCH NICHT EINMAL!!!',NULL),
(70740,0,0,'esES','¡¿Quieres un regalo?! ¡¡¡PUES A MÍ NO ME FUNCIONAN LAS PIERNAS!!!',NULL),
(70740,0,0,'esMX','¡¿Quieres un regalo?! ¡¡¡PUES A MÍ NO ME FUNCIONAN LAS PIERNAS!!!',NULL),
(70740,0,0,'frFR','Vous voulez un cadeau ?! POUR INFO, MES JAMBES NE FONCTIONNENT MÊME PAS !!!',NULL),
(70740,0,0,'koKR','선물 하나 달라고?! 난 지금 다리도 못 움직이거든?!!',NULL),
(70740,0,0,'ruRU','Подарок, значит, хочешь? Да у меня даже ноги не ходят!',NULL),
(70740,0,0,'zhCN','你想要礼物？！好极了，我的腿都不能动了！！！',NULL),
(70740,0,0,'zhTW','想要禮物嗎?!拿去吧，反正我的腿根本就不能用!!!',NULL),
(70740,1,0,'deDE','Ausgeblingt…',NULL),
(70740,1,0,'esES','He perdido mi brillo...',NULL),
(70740,1,0,'esMX','He perdido mi brillo...',NULL),
(70740,1,0,'frFR','Mon bling a fait dong…',NULL),
(70740,1,0,'koKR','나도 반짝반짝한... 데...',NULL),
